static const char* getJsonString(cJSON* obj, const char* name) {
  cJSON* item = cJSON_GetObjectItemCaseSensitive(obj, name);
  return cJSON_IsString(item) ? item->valuestring : nullptr;
}

static SStreamWindowPlan* makeDeploySessionPlan(bool invalidOuterOverlap) {
  SStreamWindowPlan* pPlan = (SStreamWindowPlan*)taosMemoryCalloc(1, sizeof(*pPlan));
  if (pPlan == NULL) return NULL;
  pPlan->version = STREAM_WINDOW_PLAN_VERSION;
  pPlan->pLayers = taosArrayInit(2, sizeof(SStreamWindowLayerSpec));
  if (pPlan->pLayers == NULL) {
    tDestroyStreamWindowPlan(&pPlan);
    return NULL;
  }

  SStreamWindowLayerSpec outer = {0};
  tstrncpy(outer.name, "outer", sizeof(outer.name));
  if (invalidOuterOverlap) {
    outer.triggerType = WINDOW_TYPE_INTERVAL;
    outer.trigger.sliding.interval = 20;
    outer.trigger.sliding.sliding = 10;
  } else {
    outer.triggerType = WINDOW_TYPE_SESSION;
    outer.trigger.session.sessionVal = 20;
  }
  if (taosArrayPush(pPlan->pLayers, &outer) == NULL) {
    tDestroyStreamWindowPlan(&pPlan);
    return NULL;
  }

  SStreamWindowLayerSpec leaf = {0};
  leaf.triggerType = WINDOW_TYPE_SESSION;
  leaf.trigger.session.sessionVal = 10;
  if (taosArrayPush(pPlan->pLayers, &leaf) == NULL) {
    tDestroyStreamWindowPlan(&pPlan);
    return NULL;
  }
  return pPlan;
}

static SMStreamHbRspMsg makeDeployHeartbeat(bool invalidOuterOverlap) {
  SMStreamHbRspMsg heartbeat = {0};
  heartbeat.deploy.streamList = taosArrayInit_s(sizeof(SStmStreamDeploy), 1);
  if (heartbeat.deploy.streamList == NULL) return heartbeat;
  SStmStreamDeploy* pStream = (SStmStreamDeploy*)taosArrayGet(heartbeat.deploy.streamList, 0);
  pStream->streamId = 42;
  pStream->triggerTask = (SStmTaskDeploy*)taosMemoryCalloc(1, sizeof(SStmTaskDeploy));
  if (pStream->triggerTask == NULL) return heartbeat;

  pStream->triggerTask->task.type = STREAM_TRIGGER_TASK;
  pStream->triggerTask->task.streamId = pStream->streamId;
  pStream->triggerTask->task.taskId = 7;
  SStreamTriggerDeployMsg* pMsg = &pStream->triggerTask->msg.trigger;
  pMsg->triggerType = WINDOW_TYPE_SESSION;
  pMsg->trigger.session.sessionVal = 10;
  pMsg->triTsSlotId = -1;
  pMsg->calcTsSlotId = -1;
  pMsg->triPkSlotId = -1;
  pMsg->calcPkSlotId = -1;
  pMsg->precision = TSDB_TIME_PRECISION_MILLI;
  pMsg->streamName = taosStrdup("test.deploy_window_plan");
  pMsg->addOptions = STREAM_OPTION_NESTED_WINDOW_PLAN | STREAM_OPTION_FLUSH_ON_OUTER_CLOSE;
  pMsg->pWindowPlan = makeDeploySessionPlan(invalidOuterOverlap);
  return heartbeat;
}

static SStreamTriggerDeployMsg* deployTrigger(SMStreamHbRspMsg* pHeartbeat) {
  SStmStreamDeploy* pStream = (SStmStreamDeploy*)taosArrayGet(pHeartbeat->deploy.streamList, 0);
  return &pStream->triggerTask->msg.trigger;
}

static void releaseStackTask(void* pParam) {
  SStreamTriggerTask** ppTask = (SStreamTriggerTask**)pParam;
  streamTaskStatsHandleLifecycle(&(*ppTask)->pStats, STREAM_TASK_STATS_OWNER_DESTROYED);
  *ppTask = NULL;
}

