static void setDeployTriggerFilter(SStreamTriggerDeployMsg* pMsg) {
  SNode* pNode = NULL;
  ASSERT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_COLUMN, &pNode));
  ASSERT_NE(nullptr, pNode);
  char*   encoded = NULL;
  int32_t len = 0;
  ASSERT_EQ(TSDB_CODE_SUCCESS, nodesNodeToString(pNode, false, &encoded, &len));
  ASSERT_NE(nullptr, encoded);
  pMsg->triggerPrevFilter = encoded;
  nodesDestroyNode(pNode);
}

static void addDeployRunner(SStreamTriggerDeployMsg* pMsg) {
  pMsg->runnerList = taosArrayInit(1, sizeof(SStreamRunnerTarget));
  ASSERT_NE(nullptr, pMsg->runnerList);
  SStreamRunnerTarget runner = {0};
  runner.execReplica = 1;
  ASSERT_NE(nullptr, taosArrayPush(pMsg->runnerList, &runner));
}

static SNode* makeDeployColumnNode(int16_t colId) {
  SNode* pNode = NULL;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_COLUMN, &pNode));
  if (pNode == NULL) return NULL;
  SColumnNode* pColumn = (SColumnNode*)pNode;
  pColumn->colId = colId;
  pColumn->colType = COLUMN_TYPE_COLUMN;
  pColumn->node.resType.type = TSDB_DATA_TYPE_INT;
  pColumn->node.resType.bytes = sizeof(int32_t);
  tstrncpy(pColumn->tableAlias, "t", sizeof(pColumn->tableAlias));
  tsnprintf(pColumn->colName, sizeof(pColumn->colName), "c%d", colId);
  return pNode;
}

static char* encodeDeployNode(SNode* pNode) {
  if (pNode == NULL) return NULL;
  char*   encoded = NULL;
  int32_t len = 0;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesNodeToString(pNode, false, &encoded, &len));
  nodesDestroyNode(pNode);
  return encoded;
}

static char* makeDeployCondition(int16_t colId, bool nodeList) {
  SNode* pColumn = makeDeployColumnNode(colId);
  if (pColumn == NULL || !nodeList) return encodeDeployNode(pColumn);

  SNode* pNode = NULL;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_NODE_LIST, &pNode));
  if (pNode == NULL) {
    nodesDestroyNode(pColumn);
    return NULL;
  }
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesListMakeStrictAppend(&((SNodeListNode*)pNode)->pNodeList, pColumn));
  return encodeDeployNode(pNode);
}

static char* makeDeployEventStartConditions() {
  SNode* pNode = nullptr;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_NODE_LIST, &pNode));
  if (pNode == nullptr) return nullptr;

  auto* pConditions = reinterpret_cast<SNodeListNode*>(pNode);
  for (int16_t slotId = 1; slotId <= 3; ++slotId) {
    SNode* pColumn = makeDeployColumnNode(slotId);
    if (pColumn == nullptr) {
      nodesDestroyNode(pNode);
      return nullptr;
    }
    reinterpret_cast<SColumnNode*>(pColumn)->slotId = slotId;
    int32_t code = nodesListMakeStrictAppend(&pConditions->pNodeList, pColumn);
    EXPECT_EQ(TSDB_CODE_SUCCESS, code);
    if (code != TSDB_CODE_SUCCESS) {
      nodesDestroyNode(pNode);
      return nullptr;
    }
  }
  return encodeDeployNode(pNode);
}

static char* makeDeployEventEndCondition() {
  SNode* pColumn = makeDeployColumnNode(4);
  if (pColumn == nullptr) return nullptr;
  reinterpret_cast<SColumnNode*>(pColumn)->slotId = 3;
  return encodeDeployNode(pColumn);
}

static SNode* makeDeployParityEventComparison(int16_t slotId, EOperatorType opType, uint8_t literal) {
  SNode* pColumn = makeDeployColumnNode(slotId);
  if (pColumn == nullptr) return nullptr;
  auto* pColumnNode = reinterpret_cast<SColumnNode*>(pColumn);
  pColumnNode->node.resType.type = TSDB_DATA_TYPE_UTINYINT;
  pColumnNode->node.resType.bytes = sizeof(uint8_t);
  pColumnNode->slotId = slotId;

  SNode* pValue = nullptr;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_VALUE, &pValue));
  if (pValue == nullptr) {
    nodesDestroyNode(pColumn);
    return nullptr;
  }
  auto* pValueNode = reinterpret_cast<SValueNode*>(pValue);
  pValueNode->node.resType.type = TSDB_DATA_TYPE_UTINYINT;
  pValueNode->node.resType.bytes = sizeof(uint8_t);
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesSetValueNodeValue(pValueNode, &literal));
  pValueNode->translate = true;

  SNode* pOperator = nullptr;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_OPERATOR, &pOperator));
  if (pOperator == nullptr) {
    nodesDestroyNode(pColumn);
    nodesDestroyNode(pValue);
    return nullptr;
  }
  auto* pOperatorNode = reinterpret_cast<SOperatorNode*>(pOperator);
  pOperatorNode->node.resType.type = TSDB_DATA_TYPE_BOOL;
  pOperatorNode->node.resType.bytes = sizeof(bool);
  pOperatorNode->opType = opType;
  pOperatorNode->pLeft = pColumn;
  pOperatorNode->pRight = pValue;
  return pOperator;
}

static SNode* makeDeployEventStartLeaf(SNode* pCondition) {
  if (pCondition == nullptr) return nullptr;
  SNode* pNode = nullptr;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_EVENT_START_LEAF, &pNode));
  if (pNode == nullptr) {
    nodesDestroyNode(pCondition);
    return nullptr;
  }
  reinterpret_cast<SEventStartLeafNode*>(pNode)->pCond = pCondition;
  return pNode;
}

static char* makeDeployParityEventStartConditions() {
  SNode* pNode = nullptr;
  EXPECT_EQ(TSDB_CODE_SUCCESS, nodesMakeNode(QUERY_NODE_NODE_LIST, &pNode));
  if (pNode == nullptr) return nullptr;

  auto* pConditions = reinterpret_cast<SNodeListNode*>(pNode);
  for (uint8_t conditionIndex = 1; conditionIndex <= 3; ++conditionIndex) {
    SNode* pCondition = makeDeployEventStartLeaf(makeDeployParityEventComparison(2, OP_TYPE_EQUAL, conditionIndex));
    if (pCondition == nullptr) {
      nodesDestroyNode(pNode);
      return nullptr;
    }
    int32_t code = nodesListMakeStrictAppend(&pConditions->pNodeList, pCondition);
    EXPECT_EQ(TSDB_CODE_SUCCESS, code);
    if (code != TSDB_CODE_SUCCESS) {
      nodesDestroyNode(pNode);
      return nullptr;
    }
  }
  return encodeDeployNode(pNode);
}

static char* makeDeployParityEventEndCondition() {
  return encodeDeployNode(makeDeployParityEventComparison(3, OP_TYPE_NOT_EQUAL, 0));
}

