static void setDeployPartition(SStreamTriggerDeployMsg* pMsg) {
  pMsg->isTriggerTblStb = 1;
  pMsg->partitionCols = makeDeployNodeList(1);
  ASSERT_NE(nullptr, pMsg->partitionCols);
}

static void setDeployStateInput(SStreamWindowLayerSpec* pLayer, int16_t slotId) {
  ASSERT_NE(nullptr, pLayer);
  taosArrayDestroy(pLayer->input.pConditionSlotIds);
  pLayer->input.pConditionSlotIds = taosArrayInit(1, sizeof(slotId));
  ASSERT_NE(nullptr, pLayer->input.pConditionSlotIds);
  ASSERT_NE(nullptr, taosArrayPush(pLayer->input.pConditionSlotIds, &slotId));
}

static void setDeployStateTrigger(SStreamTriggerDeployMsg* pMsg) {
  pMsg->triggerType = WINDOW_TYPE_STATE;
  pMsg->trigger = {};
  SStateWinTrigger* pState = &pMsg->trigger.stateWin;
  pState->pSlotIds = taosArrayInit(1, sizeof(int16_t));
  ASSERT_NE(nullptr, pState->pSlotIds);
  int16_t slotId = 1;
  ASSERT_NE(nullptr, taosArrayPush(pState->pSlotIds, &slotId));
  pState->extend = 1;
  pState->zeroth = makeDeployNodeList(1);
  pState->expr = makeDeployNodeList(2);
  ASSERT_NE(nullptr, pState->zeroth);
  ASSERT_NE(nullptr, pState->expr);

  SStreamWindowLayerSpec* pLeaf = (SStreamWindowLayerSpec*)taosArrayGet(
      pMsg->pWindowPlan->pLayers, taosArrayGetSize(pMsg->pWindowPlan->pLayers) - 1);
  pLeaf->triggerType = WINDOW_TYPE_STATE;
  pLeaf->trigger = {};
  pLeaf->trigger.stateWin.pSlotIds = taosArrayDup(pState->pSlotIds, NULL);
  pLeaf->trigger.stateWin.extend = pState->extend;
  pLeaf->trigger.stateWin.zeroth = taosStrdup((const char*)pState->zeroth);
  pLeaf->trigger.stateWin.expr = taosStrdup((const char*)pState->expr);
  ASSERT_NE(nullptr, pLeaf->trigger.stateWin.pSlotIds);
  ASSERT_NE(nullptr, pLeaf->trigger.stateWin.zeroth);
  ASSERT_NE(nullptr, pLeaf->trigger.stateWin.expr);
  setDeployStateInput(pLeaf, slotId);
}

static void setDeployEventTrigger(SStreamTriggerDeployMsg* pMsg, bool multiStart, bool parityExpressions = false) {
  pMsg->triggerType = WINDOW_TYPE_EVENT;
  pMsg->trigger = {};
  SEventTrigger* pEvent = &pMsg->trigger.event;
  pEvent->startCond = parityExpressions ? makeDeployParityEventStartConditions()
                      : multiStart      ? makeDeployEventStartConditions()
                                        : makeDeployCondition(1, false);
  pEvent->endCond = parityExpressions ? makeDeployParityEventEndCondition()
                    : multiStart      ? makeDeployEventEndCondition()
                                      : makeDeployCondition(2, false);
  ASSERT_NE(nullptr, pEvent->startCond);
  ASSERT_NE(nullptr, pEvent->endCond);

  SStreamWindowLayerSpec* pLeaf = (SStreamWindowLayerSpec*)taosArrayGet(
      pMsg->pWindowPlan->pLayers, taosArrayGetSize(pMsg->pWindowPlan->pLayers) - 1);
  pLeaf->triggerType = WINDOW_TYPE_EVENT;
  pLeaf->trigger = {};
  pLeaf->trigger.event.startCond = taosStrdup((const char*)pEvent->startCond);
  pLeaf->trigger.event.endCond = taosStrdup((const char*)pEvent->endCond);
  ASSERT_NE(nullptr, pLeaf->trigger.event.startCond);
  ASSERT_NE(nullptr, pLeaf->trigger.event.endCond);
}

static void setDeployCountTrigger(SStreamTriggerDeployMsg* pMsg, int64_t count, int64_t step) {
  pMsg->triggerType = WINDOW_TYPE_COUNT;
  pMsg->trigger = {};
  pMsg->trigger.count.countVal = count;
  pMsg->trigger.count.sliding = step;

  auto* pLeaf = static_cast<SStreamWindowLayerSpec*>(
      taosArrayGet(pMsg->pWindowPlan->pLayers, taosArrayGetSize(pMsg->pWindowPlan->pLayers) - 1));
  ASSERT_NE(nullptr, pLeaf);
  pLeaf->triggerType = WINDOW_TYPE_COUNT;
  pLeaf->trigger = {};
  pLeaf->trigger.count.countVal = count;
  pLeaf->trigger.count.sliding = step;
}

