class StreamTriggerCacheTeardownTest : public ::testing::Test {
 protected:
  void SetUp() override {
    ASSERT_EQ(nullptr, g_pDataSinkManager.dsStreamTaskList);
    setDataSinkMaxMemSize(DS_MEM_SIZE_RESERVED + 1024 * 1024);
    ASSERT_EQ(TSDB_CODE_SUCCESS, initStreamDataSink());
    task_.task.type = STREAM_TRIGGER_TASK;
    task_.task.streamId = 7137932980LL;
    task_.task.taskId = 1;
    task_.task.undeployCb = releaseStackTask;
    taosInitRWLatch(&task_.calcDataCacheIterLock);
    taosInitRWLatch(&task_.readerProgressLock);
  }

  void TearDown() override {
    if (taskPtr_ != nullptr) {
      EXPECT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskUndeploy(&taskPtr_, true));
    }
    blockDataDestroy(block_);
    destroyDataSinkMgr();
    setDataSinkMaxMemSize(savedBufferSize_);
  }

  void CheckUndeploy(bool history, SCleanMode cleanMode) {
    void**     cache = nullptr;
    SHashObj** iterators = nullptr;
    if (history) {
      task_.pHistoryContext =
          static_cast<SSTriggerHistoryContext*>(taosMemoryCalloc(1, sizeof(SSTriggerHistoryContext)));
      ASSERT_NE(nullptr, task_.pHistoryContext);
      task_.pHistoryContext->pTask = &task_;
      cache = &task_.pHistoryContext->pCalcDataCache;
      iterators = &task_.pHistoryContext->pCalcDataCacheIters;
    } else {
      task_.pRealtimeContext =
          static_cast<SSTriggerRealtimeContext*>(taosMemoryCalloc(1, sizeof(SSTriggerRealtimeContext)));
      ASSERT_NE(nullptr, task_.pRealtimeContext);
      auto* context = task_.pRealtimeContext;
      context->pTask = &task_;
      ASSERT_EQ(TSDB_CODE_SUCCESS, taosObjListInit(&context->dumpTableUids, &context->tableUidPool));
      ASSERT_EQ(TSDB_CODE_SUCCESS, taosObjListInit(&context->pAllCalcTableUids, &context->tableUidPool));
      ASSERT_EQ(TSDB_CODE_SUCCESS, taosObjListInit(&context->pCalcTableUids, &context->tableUidPool));
      cache = &context->pCalcDataCache;
      iterators = &context->pCalcDataCacheIters;
    }
    ASSERT_EQ(TSDB_CODE_SUCCESS, initStreamDataCache(task_.task.streamId, task_.task.taskId, 1, cleanMode, 0, cache));
    ASSERT_EQ(TSDB_CODE_SUCCESS, stCreateCalcDataCacheIterMap(iterators));
    ASSERT_EQ(TSDB_CODE_SUCCESS, createDataBlock(&block_));
    SColumnInfoData info = createColumnInfoData(TSDB_DATA_TYPE_TIMESTAMP, sizeof(TSKEY), 0);
    ASSERT_EQ(TSDB_CODE_SUCCESS, blockDataAppendColInfo(block_, &info));
    ASSERT_EQ(TSDB_CODE_SUCCESS, blockDataEnsureCapacity(block_, 1));
    auto*       column = static_cast<SColumnInfoData*>(taosArrayGet(block_->pDataBlock, 0));
    const TSKEY ts = 100;
    ASSERT_EQ(TSDB_CODE_SUCCESS, colDataSetVal(column, 0, reinterpret_cast<const char*>(&ts), false));
    block_->info.rows = 1;
    const int64_t gid = 7;
    ASSERT_EQ(TSDB_CODE_SUCCESS, putStreamDataCache(*cache, gid, ts, ts, block_, 0, 0));

    void* iterator = nullptr;
    ASSERT_EQ(TSDB_CODE_SUCCESS, getStreamDataCache(*cache, gid, ts, ts, &iterator));
    ASSERT_NE(nullptr, iterator);
    const int32_t code = taosHashPut(*iterators, &gid, sizeof(gid), &iterator, sizeof(iterator));
    if (code != TSDB_CODE_SUCCESS) cancelStreamDataCacheIterate(&iterator);
    ASSERT_EQ(TSDB_CODE_SUCCESS, code);

    ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskUndeploy(&taskPtr_, true));
    EXPECT_EQ(nullptr, taskPtr_);
    EXPECT_EQ(nullptr, task_.pHistoryContext);
    EXPECT_EQ(nullptr, task_.pRealtimeContext);
    EXPECT_EQ(0, taosHashGetSize(g_pDataSinkManager.dsStreamTaskList));
    EXPECT_EQ(0, g_pDataSinkManager.usedMemSize);
  }

  SStreamTriggerTask  task_ = {};
  SStreamTriggerTask* taskPtr_ = &task_;
  SSDataBlock*        block_ = nullptr;
  const int64_t       savedBufferSize_ = tsStreamBufferSizeBytes;
};

TEST_F(StreamTriggerCacheTeardownTest, HistoryReleasesAlignIteratorBeforeCache) {
  CheckUndeploy(true, DATA_CLEAN_IMMEDIATE);
}

TEST_F(StreamTriggerCacheTeardownTest, HistoryReleasesSlidingIteratorBeforeCache) {
  CheckUndeploy(true, DATA_CLEAN_EXPIRED);
}

TEST_F(StreamTriggerCacheTeardownTest, RealtimeReleasesAlignIteratorBeforeCache) {
  CheckUndeploy(false, DATA_CLEAN_IMMEDIATE);
}

TEST_F(StreamTriggerCacheTeardownTest, RealtimeReleasesSlidingIteratorBeforeCache) {
  CheckUndeploy(false, DATA_CLEAN_EXPIRED);
}

class StreamTriggerTaskTest : public ::testing::Test {
 protected:
  void SetUp() override {
    // Test setup
    // Use Asia/Shanghai timezone for consistent testing
    taosSetGlobalTimezone("Asia/Shanghai");
  }

  void TearDown() override {
    // Test cleanup
  }

  /**
   * Helper function to convert human-readable datetime to timestamp
   * @param year Year (e.g., 2026)
   * @param month Month (1-12)
   * @param day Day (1-31)
   * @param hour Hour (0-23)
   * @param minute Minute (0-59)
   * @param second Second (0-59)
   * @param precision Time precision (TSDB_TIME_PRECISION_MILLI/MICRO/NANO)
   * @return Timestamp in specified precision
   */
  int64_t makeTimestamp(int year, int month, int day, int hour, int minute, int second,
                        int8_t precision = TSDB_TIME_PRECISION_MILLI) {
    struct tm tm = {0};
    tm.tm_year = year - 1900;
    tm.tm_mon = month - 1;
    tm.tm_mday = day;
    tm.tm_hour = hour;
    tm.tm_min = minute;
    tm.tm_sec = second;
    tm.tm_isdst = -1;

    time_t  t = taosMktime(&tm, NULL);
    int64_t ts = (int64_t)t;

    switch (precision) {
      case TSDB_TIME_PRECISION_MILLI:
        return ts * 1000LL;
      case TSDB_TIME_PRECISION_MICRO:
        return ts * 1000000LL;
      case TSDB_TIME_PRECISION_NANO:
        return ts * 1000000000LL;
      default:
        return ts * 1000LL;
    }
  }

  int64_t makeTimestampAt(int year, int month, int day, int hour, int minute, int second, timezone_t timezone,
                          int8_t precision = TSDB_TIME_PRECISION_MILLI) {
    struct tm tm = {0};
    tm.tm_year = year - 1900;
    tm.tm_mon = month - 1;
    tm.tm_mday = day;
    tm.tm_hour = hour;
    tm.tm_min = minute;
    tm.tm_sec = second;
    tm.tm_isdst = -1;

    time_t timestamp = taosMktime(&tm, timezone);
    return static_cast<int64_t>(timestamp) * TSDB_TICK_PER_SECOND(precision);
  }

  void expectIntervalWindowParity(const SInterval& interval, int64_t timestamp) {
    SStreamTriggerTask task = {};
    task.triggerType = STREAM_TRIGGER_SLIDING;
    task.interval = interval;

    STimeWindow query = getAlignQueryTimeWindow(&interval, timestamp);
    STimeWindow stream = stTriggerTaskGetTimeWindow(&task, timestamp);
    EXPECT_EQ(stream.skey, query.skey);
    EXPECT_EQ(stream.ekey, query.ekey);

    STimeWindow expected = query;
    expected.skey = getNextTimeWindowStart(&interval, expected.skey, TSDB_ORDER_DESC);
    expected.ekey = taosTimeGetIntervalEnd(expected.skey, &interval);
    stTriggerTaskPrevTimeWindow(&task, &stream);
    EXPECT_EQ(stream.skey, expected.skey);
    EXPECT_EQ(stream.ekey, expected.ekey);

    expected = query;
    expected.skey = getNextTimeWindowStart(&interval, expected.skey, TSDB_ORDER_ASC);
    expected.ekey = taosTimeGetIntervalEnd(expected.skey, &interval);
    stream = query;
    stTriggerTaskNextTimeWindow(&task, &stream);
    EXPECT_EQ(stream.skey, expected.skey);
    EXPECT_EQ(stream.ekey, expected.ekey);
  }

  /**
   * Helper function to verify window boundaries
   * @param win Window to verify
   * @param precision Time precision
   * @param skeyYear Expected skey year (e.g., 2026), -1 to skip
   * @param skeyMonth Expected skey month (1-12), -1 to skip
   * @param skeyDay Expected skey day (1-31), -1 to skip
   * @param skeyHour Expected skey hour (0-23), -1 to skip
   * @param skeyMin Expected skey minute (0-59), -1 to skip
   * @param skeySec Expected skey second (0-59), -1 to skip
   * @param skeyWday Expected skey day of week (0-6, 0=Sunday), -1 to skip
   * @param ekeyYear Expected ekey year (e.g., 2026), -1 to skip
   * @param ekeyMonth Expected ekey month (1-12), -1 to skip
   * @param ekeyDay Expected ekey day (1-31), -1 to skip
   * @param ekeyHour Expected ekey hour (0-23), -1 to skip
   * @param ekeyMin Expected ekey minute (0-59), -1 to skip
   * @param ekeySec Expected ekey second (0-59), -1 to skip
   * @param ekeyWday Expected ekey day of week (0-6, 0=Sunday), -1 to skip
   * @param expectedDurationMs Expected duration in milliseconds (closed interval), -1 to skip
   */
  void verifyWindow(const STimeWindow& win, int8_t precision, int skeyYear = -1, int skeyMonth = -1, int skeyDay = -1,
                    int skeyHour = -1, int skeyMin = -1, int skeySec = -1, int skeyWday = -1, int ekeyYear = -1,
                    int ekeyMonth = -1, int ekeyDay = -1, int ekeyHour = -1, int ekeyMin = -1, int ekeySec = -1,
                    int ekeyWday = -1, int64_t expectedDurationMs = -1) {
    // Convert precision factor
    int64_t precisionFactor = 1;
    switch (precision) {
      case TSDB_TIME_PRECISION_MILLI:
        precisionFactor = 1000LL;
        break;
      case TSDB_TIME_PRECISION_MICRO:
        precisionFactor = 1000000LL;
        break;
      case TSDB_TIME_PRECISION_NANO:
        precisionFactor = 1000000000LL;
        break;
    }

    // Verify skey
    time_t    t_skey = win.skey / precisionFactor;
    struct tm tm_skey;
    taosLocalTime(&t_skey, &tm_skey, NULL, 0, NULL);

    if (skeyYear >= 0) EXPECT_EQ(tm_skey.tm_year, skeyYear - 1900);
    if (skeyMonth >= 0) EXPECT_EQ(tm_skey.tm_mon, skeyMonth - 1);
    if (skeyDay >= 0) EXPECT_EQ(tm_skey.tm_mday, skeyDay);
    if (skeyHour >= 0) EXPECT_EQ(tm_skey.tm_hour, skeyHour);
    if (skeyMin >= 0) EXPECT_EQ(tm_skey.tm_min, skeyMin);
    if (skeySec >= 0) EXPECT_EQ(tm_skey.tm_sec, skeySec);
    if (skeyWday >= 0) EXPECT_EQ(tm_skey.tm_wday, skeyWday);

    // Verify ekey
    time_t    t_ekey = win.ekey / precisionFactor;
    struct tm tm_ekey;
    taosLocalTime(&t_ekey, &tm_ekey, NULL, 0, NULL);

    if (ekeyYear >= 0) EXPECT_EQ(tm_ekey.tm_year, ekeyYear - 1900);
    if (ekeyMonth >= 0) EXPECT_EQ(tm_ekey.tm_mon, ekeyMonth - 1);
    if (ekeyDay >= 0) EXPECT_EQ(tm_ekey.tm_mday, ekeyDay);
    if (ekeyHour >= 0) EXPECT_EQ(tm_ekey.tm_hour, ekeyHour);
    if (ekeyMin >= 0) EXPECT_EQ(tm_ekey.tm_min, ekeyMin);
    if (ekeySec >= 0) EXPECT_EQ(tm_ekey.tm_sec, ekeySec);
    if (ekeyWday >= 0) EXPECT_EQ(tm_ekey.tm_wday, ekeyWday);

    // Verify duration (closed interval: ekey - skey + 1)
    if (expectedDurationMs >= 0) {
      int64_t duration = win.ekey - win.skey + 1;
      int64_t expectedDuration = expectedDurationMs * (precisionFactor / 1000LL);
      EXPECT_EQ(duration, expectedDuration);
    }
  }
};

static int32_t     gTimezoneAllocCalls = 0;
static int32_t     gTimezoneFreeCalls = 0;
static bool        gFailTimezoneAlloc = false;
static std::string gAllocatedTimezone;
static char        gTimezoneHandleStorage = 0;

static timezone_t countTimezoneAlloc(const char* timezone) {
  ++gTimezoneAllocCalls;
  gAllocatedTimezone = timezone == nullptr ? "" : timezone;
  return gFailTimezoneAlloc ? nullptr : reinterpret_cast<timezone_t>(&gTimezoneHandleStorage);
}

static void countTimezoneFree(timezone_t timezone) {
  if (timezone == reinterpret_cast<timezone_t>(&gTimezoneHandleStorage)) {
    ++gTimezoneFreeCalls;
  }
}

static void noOpTriggerUndeploy(void*) {}

static SStreamTriggerDeployMsg makeTimeTriggerDeployMsg(EWindowType type, bool independentSliding = false) {
  static char streamName[] = "task-8-trigger";

  SStreamTriggerDeployMsg msg = {};
  msg.triggerType = static_cast<int8_t>(type);
  msg.streamName = streamName;
  msg.precision = TSDB_TIME_PRECISION_MILLI;
  if (type == WINDOW_TYPE_PERIOD) {
    msg.trigger.period.periodUnit = 'n';
    msg.trigger.period.offsetUnit = 'a';
    msg.trigger.period.precision = TSDB_TIME_PRECISION_NANO;
    msg.trigger.period.period = 1;
  } else {
    msg.trigger.sliding.intervalUnit = 's';
    msg.trigger.sliding.slidingUnit = 's';
    msg.trigger.sliding.offsetUnit = 'a';
    msg.trigger.sliding.soffsetUnit = 'a';
    msg.trigger.sliding.precision = TSDB_TIME_PRECISION_MILLI;
    msg.trigger.sliding.interval = independentSliding ? 0 : 1000;
    msg.trigger.sliding.sliding = independentSliding ? 1000 : 0;
  }
  return msg;
}

static SStreamTriggerDeployMsg makeNonTimeTriggerDeployMsg(EWindowType type) {
  static char streamName[] = "task-8-non-time-trigger";

  SStreamTriggerDeployMsg msg = {};
  msg.triggerType = static_cast<int8_t>(type);
  msg.streamName = streamName;
  msg.precision = TSDB_TIME_PRECISION_MILLI;
  return msg;
}

static char* makeSerializedColumnNode(int16_t slotId) {
  SNode* pNode = nullptr;
  if (nodesMakeNode(QUERY_NODE_COLUMN, &pNode) != TSDB_CODE_SUCCESS) {
    return nullptr;
  }

  SColumnNode* pColumn = reinterpret_cast<SColumnNode*>(pNode);
  pColumn->slotId = slotId;
  pColumn->colId = slotId + 1;
  pColumn->node.resType.type = TSDB_DATA_TYPE_INT;
  pColumn->node.resType.bytes = sizeof(int32_t);
  tstrncpy(pColumn->colName, "c1", sizeof(pColumn->colName));

  char*   serialized = nullptr;
  int32_t code = nodesNodeToString(pNode, false, &serialized, nullptr);
  nodesDestroyNode(pNode);
  return code == TSDB_CODE_SUCCESS ? serialized : nullptr;
}

static void cleanupTriggerDeployTestTask(SStreamTriggerTask* task) {
  task->task.undeployCb = noOpTriggerUndeploy;
  SStreamTriggerTask* taskPtr = task;
  EXPECT_EQ(stTriggerTaskUndeploy(&taskPtr, true), TSDB_CODE_SUCCESS);
  streamTaskStatsHandleLifecycle(&task->pStats, STREAM_TASK_STATS_OWNER_DESTROYED);
  taosMemoryFreeClear(task->task.extraErrMsg);
}

TEST_F(StreamTriggerTaskTest, DeployOwnsOneTimezoneForEachTimeTrigger) {
  const struct {
    EWindowType type;
    bool        independentSliding;
  } cases[] = {
      {WINDOW_TYPE_INTERVAL, false},
      {WINDOW_TYPE_INTERVAL, true},
      {WINDOW_TYPE_PERIOD, false},
  };

  for (const auto& testCase : cases) {
    SCOPED_TRACE(testCase.independentSliding ? "independent sliding" : std::to_string(testCase.type));
    gTimezoneAllocCalls = 0;
    gTimezoneFreeCalls = 0;
    gFailTimezoneAlloc = false;
    gAllocatedTimezone.clear();

    Stub stub;
    stub.set(tzalloc, countTimezoneAlloc);
    stub.set(tzfree, countTimezoneFree);

    SStreamTriggerTask task = {};
    task.task.type = STREAM_TRIGGER_TASK;
    SStreamTriggerDeployMsg msg = makeTimeTriggerDeployMsg(testCase.type, testCase.independentSliding);
    tstrncpy(msg.timeConfig.timezone, "Asia/Shanghai", sizeof(msg.timeConfig.timezone));
    msg.timeConfig.firstDayOfWeek = 4;

    int32_t code = stTriggerTaskDeploy(&task, &msg);
    EXPECT_EQ(code, TSDB_CODE_SUCCESS);
    EXPECT_EQ(gTimezoneAllocCalls, 1);
    EXPECT_EQ(gAllocatedTimezone, "Asia/Shanghai");
    EXPECT_EQ(task.timezone, task.interval.timezone);
    EXPECT_NE(task.interval.timezone, nullptr);
    EXPECT_EQ(task.interval.firstDayOfWeek, 4);
    if (!testCase.independentSliding && testCase.type == WINDOW_TYPE_INTERVAL) {
      EXPECT_EQ(task.interval.sliding, task.interval.interval);
    }

    cleanupTriggerDeployTestTask(&task);
    EXPECT_EQ(gTimezoneFreeCalls, 1);
    EXPECT_EQ(task.timezone, nullptr);
    EXPECT_EQ(task.interval.timezone, nullptr);
  }
}

