TEST_F(StreamNestedRealtimeTest, NoticeBatchDispatchesOnWorkerQueue) {
  streamNoticeQueueCleanup();
  ASSERT_EQ(TSDB_CODE_SUCCESS, streamNoticeQueueInit());
  SStreamTriggerTask task = {};
  configureNestedNoticeTask(&task, 0);
  {
    std::lock_guard<std::mutex> lock(gAsyncNoticeMutex);
    gAsyncNoticeDelivered = false;
    gAsyncNoticeThread = {};
    gAsyncNoticeUrl.clear();
    gAsyncNoticePayload.clear();
  }

  Stub stub;
  stub.set(streamSendNotifyPayloadCached, captureAsyncNoticeSend);
  const std::thread::id callerThread = std::this_thread::get_id();
  stageNestedNotice(&task);
  {
    std::unique_lock<std::mutex> lock(gAsyncNoticeMutex);
    const bool                   delivered =
        gAsyncNoticeCondition.wait_for(lock, std::chrono::seconds(2), [] { return gAsyncNoticeDelivered; });
    EXPECT_TRUE(delivered);
    if (delivered) {
      EXPECT_NE(callerThread, gAsyncNoticeThread);
      EXPECT_EQ("ws://nested-notify.test", gAsyncNoticeUrl);
      EXPECT_FALSE(gAsyncNoticePayload.empty());
    }
  }
  streamNoticeQueueCleanup();
  stub.reset(streamSendNotifyPayloadCached);
  destroyNestedNoticeTask(&task);
}

TEST_F(StreamNestedRealtimeTest, NoticeQueueRejectsWorkBeyondCapacity) {
  constexpr int32_t queueCapacity = 4096;
  streamNoticeQueueCleanup();
  ASSERT_EQ(TSDB_CODE_SUCCESS, streamNoticeQueueInit());
  {
    std::lock_guard<std::mutex> lock(gAsyncNoticeMutex);
    gBlockingNoticeEntered = false;
    gBlockingNoticeReleased = false;
  }

  Stub stub;
  stub.set(streamSendNotifyPayloadCached, captureBlockingNoticeSend);
  ASSERT_EQ(TSDB_CODE_SUCCESS, streamEnqueueNotifyPayload("ws://blocked.test", "x", 1));
  {
    std::unique_lock<std::mutex> lock(gAsyncNoticeMutex);
    EXPECT_TRUE(gAsyncNoticeCondition.wait_for(lock, std::chrono::seconds(2), [] { return gBlockingNoticeEntered; }));
  }

  int32_t accepted = 0;
  int32_t firstFailure = TSDB_CODE_SUCCESS;
  for (int32_t i = 0; i <= queueCapacity; ++i) {
    int32_t code = streamEnqueueNotifyPayload("ws://blocked.test", "x", 1);
    if (code == TSDB_CODE_SUCCESS) {
      ++accepted;
    } else {
      firstFailure = code;
      break;
    }
  }
  EXPECT_EQ(queueCapacity - 1, accepted);
  EXPECT_EQ(TSDB_CODE_UTIL_QUEUE_OUT_OF_MEMORY, firstFailure);

  {
    std::lock_guard<std::mutex> lock(gAsyncNoticeMutex);
    gBlockingNoticeReleased = true;
  }
  gAsyncNoticeCondition.notify_one();
  streamNoticeQueueCleanup();
  stub.reset(streamSendNotifyPayloadCached);
}

