static int32_t captureRealtimePipelineClock(int, struct timespec* pTime) {
  if (pTime == nullptr) return TSDB_CODE_INVALID_PARA;
  int64_t nowNs = gRealtimePipelineClockNs;
  pTime->tv_sec = static_cast<time_t>(nowNs / NANOSECOND_PER_SEC);
  pTime->tv_nsec = static_cast<long>(nowNs % NANOSECOND_PER_SEC);
  return TSDB_CODE_SUCCESS;
}

static void resetRealtimePipelineTurnClock(int64_t wallClockNs, int64_t wallClockStepNs, int64_t monoClockNs) {
  gRealtimePipelineTurnWallClockNs = wallClockNs;
  gRealtimePipelineTurnWallClockStepNs = wallClockStepNs;
  gRealtimePipelineTurnMonoClockNs = monoClockNs;
  gRealtimePipelineTurnWallClockCalls = 0;
}

static int32_t captureRealtimePipelineTurnClock(int clockId, struct timespec* pTime) {
  if (pTime == nullptr) return TSDB_CODE_INVALID_PARA;
  int64_t nowNs = gRealtimePipelineTurnMonoClockNs;
  if (clockId == CLOCK_REALTIME) {
    nowNs = gRealtimePipelineTurnWallClockNs +
            static_cast<int64_t>(gRealtimePipelineTurnWallClockCalls++) * gRealtimePipelineTurnWallClockStepNs;
  }
  pTime->tv_sec = static_cast<time_t>(nowNs / NANOSECOND_PER_SEC);
  pTime->tv_nsec = static_cast<long>(nowNs % NANOSECOND_PER_SEC);
  return TSDB_CODE_SUCCESS;
}

static int32_t captureRealtimePipelineWaitAppend(SList* pList, const void* pData) {
  if (pList == nullptr || pData == nullptr) return TSDB_CODE_INVALID_PARA;
  constexpr int32_t waitPrefixSize = static_cast<int32_t>(offsetof(RealtimePipelineWaitInfo, reason));
  if (listEleSize(pList) >= waitPrefixSize) {
    RealtimePipelineWaitInfo info = {};
    memcpy(&info, pData, std::min<int32_t>(listEleSize(pList), sizeof(info)));
    if (info.streamId == gRealtimePipelineWaitStreamId && info.taskId == gRealtimePipelineWaitTaskId &&
        info.sessionId == gRealtimePipelineWaitSessionId) {
      gRealtimePipelineWaitInfo = info;
      ++gRealtimePipelineWaitCaptureCount;
      gRealtimePipelineWaitCaptured = true;
    }
  }
  if (gRealtimePipelineWaitAppendCode != TSDB_CODE_SUCCESS) {
    int32_t code = gRealtimePipelineWaitAppendCode;
    gRealtimePipelineWaitAppendCode = TSDB_CODE_SUCCESS;
    return code;
  }
  return tdListAdd(pList, pData) == nullptr ? terrno : TSDB_CODE_SUCCESS;
}

static Stub*                          gHistoryRefWalkStub = nullptr;
static std::unordered_set<SListNode*> gHistoryRefWalkNodes;
static int64_t                        gHistoryRefWalkVisits = 0;

static SListNode* countHistoryRefWalkVisits(SListIter* pIter) {
  if (pIter != nullptr && pIter->next != nullptr && gHistoryRefWalkNodes.count(pIter->next) > 0) {
    ++gHistoryRefWalkVisits;
  }
  gHistoryRefWalkStub->reset(tdListNext);
  SListNode* pNode = tdListNext(pIter);
  gHistoryRefWalkStub->set(tdListNext, countHistoryRefWalkVisits);
  return pNode;
}

static Stub*            gHistoryGroupIterStub = nullptr;
static const SSHashObj* gHistoryGroupIterTarget = nullptr;
static int64_t          gHistoryGroupIterCalls = 0;

static void* countHistoryGroupIterations(const SSHashObj* pHashObj, void* pData, int32_t* pIter) {
  if (pHashObj == gHistoryGroupIterTarget) ++gHistoryGroupIterCalls;
  gHistoryGroupIterStub->reset(tSimpleHashIterate);
  void* pResult = tSimpleHashIterate(pHashObj, pData, pIter);
  gHistoryGroupIterStub->set(tSimpleHashIterate, countHistoryGroupIterations);
  return pResult;
}

static int32_t gHistoryPressureAcquireCalls = 0;

static int32_t captureUnavailableHistoryCalcSlot(SStreamTriggerTask*, int64_t, int64_t,
                                                 SSTriggerCalcRequest** ppRequest) {
  if (ppRequest == nullptr) return TSDB_CODE_INVALID_PARA;
  ++gHistoryPressureAcquireCalls;
  *ppRequest = nullptr;
  return TSDB_CODE_SUCCESS;
}

static int32_t failNestedPendingCalcNode(const SStreamNestedPendingCalcEvent*, SListNode** ppNode) {
  if (ppNode != nullptr) *ppNode = nullptr;
  return TSDB_CODE_OUT_OF_MEMORY;
}

static Stub*                gNestedHistoryPendingNodeStub = nullptr;
static int32_t              gNestedHistoryPendingNodeCalls = 0;
static int32_t              gNestedHistoryPendingNodeFailureCall = 0;
static int32_t              gNestedHistoryPendingNodeShallowAfterCall = INT32_MAX;
static bool                 gNestedHistoryPendingNodeRecordGids = true;
static std::vector<int64_t> gNestedHistoryPendingNodeGids;
static SSTriggerHistoryGroup* gNestedHistoryFirstAppendGroup = nullptr;
static int64_t                gNestedHistoryFirstGroupPendingAtSecondAppend = -1;

static int32_t failSelectedNestedHistoryPendingNode(const SStreamNestedPendingCalcEvent* pEvent, SListNode** ppNode) {
  ++gNestedHistoryPendingNodeCalls;
  if (gNestedHistoryFirstGroupPendingAtSecondAppend < 0 && gNestedHistoryFirstAppendGroup != nullptr &&
      pEvent != nullptr && pEvent->leafIdentity.gid != gNestedHistoryFirstAppendGroup->gid) {
    gNestedHistoryFirstGroupPendingAtSecondAppend =
        listNEles(&gNestedHistoryFirstAppendGroup->pendingNestedEvents) +
        listNEles(&gNestedHistoryFirstAppendGroup->pendingNestedParWinEvents);
  }
  if (gNestedHistoryPendingNodeRecordGids) {
    gNestedHistoryPendingNodeGids.push_back(pEvent == nullptr ? INT64_MIN : pEvent->leafIdentity.gid);
  }
  if (gNestedHistoryPendingNodeCalls == gNestedHistoryPendingNodeFailureCall) {
    if (ppNode != nullptr) *ppNode = nullptr;
    return TSDB_CODE_OUT_OF_MEMORY;
  }
  if (gNestedHistoryPendingNodeCalls > gNestedHistoryPendingNodeShallowAfterCall) {
    SListNode* pNode =
        static_cast<SListNode*>(taosMemoryCalloc(1, sizeof(SListNode) + sizeof(SStreamNestedPendingCalcEvent)));
    if (pNode == nullptr) return terrno;
    auto* pClone = reinterpret_cast<SStreamNestedPendingCalcEvent*>(pNode->data);
    *pClone = *pEvent;
    pClone->calcParam.extraNotifyContent = nullptr;
    pClone->calcParam.resultNotifyContent = nullptr;
    pClone->calcParam.pExternalWindowData = nullptr;
    pClone->leafIdentity.lineage.pScopes = nullptr;
    pClone->pSnapshots = nullptr;
    *ppNode = pNode;
    return TSDB_CODE_SUCCESS;
  }
  gNestedHistoryPendingNodeStub->reset(stAllocNestedPendingCalcNode);
  int32_t code = stAllocNestedPendingCalcNode(pEvent, ppNode);
  gNestedHistoryPendingNodeStub->set(stAllocNestedPendingCalcNode, failSelectedNestedHistoryPendingNode);
  return code;
}

