static void overwriteRecoveryCheckpointFrameLength(std::vector<uint8_t>* pCheckpoint, int32_t payloadLen) {
  ASSERT_NE(nullptr, pCheckpoint);
  ASSERT_GE(pCheckpoint->size(), sizeof(payloadLen));
  std::memcpy(pCheckpoint->data(), &payloadLen, sizeof(payloadLen));
}

