TEST_F(StreamNestedRecoveryTest, TransactionalCheckpointParseCommitsAllFieldsOnce) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  RecoveryLiveState liveState;
  ASSERT_TRUE(seedRecoveryLiveState(&harness, false, &liveState));
  constexpr int64_t    newCutoffGid = 0x930;
  constexpr int64_t    newCutoffTime = 0x931;
  constexpr int64_t    newExtUid = 0x932;
  constexpr int64_t    newExtMaxTs = 0x933;
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 9}}, {{newCutoffGid, newCutoffTime}}, 0,
                                     &checkpoint, 3, {{kRecoveryLiveExtTaskId, {{newExtUid, newExtMaxTs}}}}));
  harness.setCheckpointBytes(std::move(checkpoint));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  const SSTriggerWalProgress* pProgress = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId);
  ASSERT_NE(nullptr, pProgress);
  EXPECT_EQ(5, pProgress->startVer);
  EXPECT_EQ(9, pProgress->savedVer);
  EXPECT_EQ(5, pProgress->doneVer);
  EXPECT_EQ(5, pProgress->lastScanVer);
  EXPECT_EQ(501, pProgress->verTime);
  EXPECT_NE(liveState.pCutoff, harness.task()->pHistoryCutoffTime);
  ASSERT_EQ(1, tSimpleHashGetSize(harness.task()->pHistoryCutoffTime));
  const auto* pCutoff = static_cast<const int64_t*>(
      tSimpleHashGet(harness.task()->pHistoryCutoffTime, &newCutoffGid, sizeof(newCutoffGid)));
  ASSERT_NE(nullptr, pCutoff);
  EXPECT_EQ(newCutoffTime, *pCutoff);
  auto** ppExt = static_cast<SSTriggerExtProgress**>(
      tSimpleHashGet(harness.context()->pReaderExtProgress, &kRecoveryLiveExtTaskId, sizeof(kRecoveryLiveExtTaskId)));
  ASSERT_NE(nullptr, ppExt);
  ASSERT_EQ(liveState.pExt, *ppExt);
  EXPECT_NE(liveState.pExtUidMaxTs, (*ppExt)->triggerSideUidMaxTs);
  ASSERT_EQ(1, tSimpleHashGetSize((*ppExt)->triggerSideUidMaxTs));
  const auto* pMaxTs =
      static_cast<const int64_t*>(tSimpleHashGet((*ppExt)->triggerSideUidMaxTs, &newExtUid, sizeof(newExtUid)));
  ASSERT_NE(nullptr, pMaxTs);
  EXPECT_EQ(newExtMaxTs, *pMaxTs);
  EXPECT_EQ(0, atomic_load_8(&harness.task()->historyFinished));
  EXPECT_EQ(17, atomic_load_32(&harness.task()->checkpointVersion));
  EXPECT_TRUE(harness.context()->recovering);
  EXPECT_TRUE(harness.context()->boundDetermined);
  EXPECT_NE(nullptr, harness.task()->pNestedRecovery);
}

