struct RecoveryPublicationProbe {
  Stub    stub;
  int32_t noticeBatchSendCount = 0;
};

static RecoveryPublicationProbe* gRecoveryPublicationProbe = nullptr;

static void captureRecoveryNoticeBatchSend(SStreamTriggerNoticeBatch** ppBatch) {
  RecoveryPublicationProbe* pProbe = gRecoveryPublicationProbe;
  ++pProbe->noticeBatchSendCount;
  pProbe->stub.reset(stTriggerNoticeBatchSend);
  stTriggerNoticeBatchSend(ppBatch);
  pProbe->stub.set(stTriggerNoticeBatchSend, captureRecoveryNoticeBatchSend);
}

class ScopedRecoveryPublicationProbe {
 public:
  ScopedRecoveryPublicationProbe() {
    EXPECT_EQ(nullptr, gRecoveryPublicationProbe);
    gRecoveryPublicationProbe = &probe_;
    probe_.stub.set(stTriggerNoticeBatchSend, captureRecoveryNoticeBatchSend);
  }

  ~ScopedRecoveryPublicationProbe() {
    if (gRecoveryPublicationProbe == &probe_) gRecoveryPublicationProbe = nullptr;
  }

  int32_t noticeBatchSendCount() const { return probe_.noticeBatchSendCount; }

  ScopedRecoveryPublicationProbe(const ScopedRecoveryPublicationProbe&) = delete;
  ScopedRecoveryPublicationProbe& operator=(const ScopedRecoveryPublicationProbe&) = delete;

 private:
  RecoveryPublicationProbe probe_;
};

static int32_t countRecoveryCacheScopeRows(void* pCache, const SStreamCacheScope* pScope, int32_t* pRowCount) {
  if (pCache == nullptr || pScope == nullptr || pRowCount == nullptr) return TSDB_CODE_INVALID_PARA;
  *pRowCount = 0;

  void*   pIter = nullptr;
  int32_t code = getStreamDataCacheScoped(pCache, pScope, INT64_MIN, INT64_MAX, &pIter);
  if (code != TSDB_CODE_SUCCESS) return code;
  while (pIter != nullptr) {
    SSDataBlock* pBlock = nullptr;
    code = getNextStreamDataCache(&pIter, &pBlock);
    if (code != TSDB_CODE_SUCCESS || pBlock == nullptr) {
      blockDataDestroy(pBlock);
      cancelStreamDataCacheIterate(&pIter);
      return code != TSDB_CODE_SUCCESS ? code : TSDB_CODE_INVALID_MSG;
    }
    *pRowCount += blockDataGetNumOfRows(pBlock);
    blockDataDestroy(pBlock);
  }
  cancelStreamDataCacheIterate(&pIter);
  return TSDB_CODE_SUCCESS;
}

