TEST_F(StreamNestedRecoveryTest, ShadowInitFailurePreservesLiveBundleAndRegistration) {
  const std::array<RecoveryShadowFailureTarget, 3> targets = {
      RecoveryShadowFailureTarget::Bundle,
      RecoveryShadowFailureTarget::Context,
      RecoveryShadowFailureTarget::DetachedCache,
  };
  for (RecoveryShadowFailureTarget target : targets) {
    SCOPED_TRACE(static_cast<int32_t>(target));
    RealtimePipelineHarness harness;
    harness.enableNestedTrowsCacheProjection();
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
    harness.task()->nestedRecoveryGeneration = 0x1234;
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    const uint64_t recoveryGeneration = harness.task()->pNestedRecovery->generation;
    ASSERT_NE(static_cast<uint64_t>(kRecoveryRealtimeSessionId), recoveryGeneration);

    SSTriggerRealtimeContext* const pLiveContext = harness.context();
    void* const                     pLiveCache = pLiveContext->pCalcDataCache;
    SSHashObj* const                pLiveGroups = pLiveContext->pGroups;
    SSHashObj* const                pLiveProgresses = pLiveContext->pReaderWalProgress;
    const SSTriggerWalProgress*     pProgress = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId);
    ASSERT_NE(nullptr, pLiveCache);
    ASSERT_NE(nullptr, pProgress);
    const RecoveryWalLiveState progress = {
        RealtimePipelineHarness::kVgId, pProgress->startVer, pProgress->savedVer, pProgress->doneVer,
        pProgress->lastScanVer,         pProgress->verTime};

    RecoveryShadowProbe probe;
    probe.failureTarget = target;
    EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY,
              harness.respondRecoverySuccess(0, 7, 700, false, false, installRecoveryShadowProbe, &probe));
    EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
    EXPECT_EQ(nullptr, harness.task()->pRetiredNestedRecoveries);
    EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, harness.task()->nestedRecoveryError);
    EXPECT_EQ(pLiveContext, harness.context());
    EXPECT_EQ(pLiveCache, harness.context()->pCalcDataCache);
    EXPECT_EQ(pLiveGroups, harness.context()->pGroups);
    EXPECT_EQ(pLiveProgresses, harness.context()->pReaderWalProgress);
    pProgress = recoveryWalProgress(harness, RealtimePipelineHarness::kVgId);
    ASSERT_NE(nullptr, pProgress);
    EXPECT_EQ(progress.startVer, pProgress->startVer);
    EXPECT_EQ(progress.savedVer, pProgress->savedVer);
    EXPECT_EQ(progress.doneVer, pProgress->doneVer);
    EXPECT_EQ(progress.lastScanVer, pProgress->lastScanVer);
    EXPECT_EQ(progress.verTime, pProgress->verTime);
    EXPECT_EQ(0, probe.replaceCalls);
    EXPECT_EQ(0, probe.registeredCacheInitCalls);
    EXPECT_EQ(0, probe.sequenceErrors);
    EXPECT_EQ(1, probe.bundleAllocCalls);
    EXPECT_EQ(target == RecoveryShadowFailureTarget::Bundle ? 0 : 1, probe.contextAllocCalls);
    EXPECT_EQ(target == RecoveryShadowFailureTarget::Bundle || target == RecoveryShadowFailureTarget::Context ? 0 : 1,
              probe.detachedCreateCalls);
    RecoveryShadowProbeStage expectedStage = RecoveryShadowProbeStage::AwaitBundle;
    if (target == RecoveryShadowFailureTarget::Context) {
      expectedStage = RecoveryShadowProbeStage::AwaitContext;
    } else if (target == RecoveryShadowFailureTarget::DetachedCache) {
      expectedStage = RecoveryShadowProbeStage::InitContext;
    }
    EXPECT_EQ(expectedStage, probe.stage);
    EXPECT_EQ(0, harness.pendingSendCount());

    SStreamDataCacheLease* pLease = nullptr;
    void*                  pRegisteredCache = nullptr;
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              acquireStreamDataCacheLease(RealtimePipelineHarness::kStreamId, RealtimePipelineHarness::kTaskId,
                                          kRecoveryRealtimeSessionId, &pLease, &pRegisteredCache));
    EXPECT_EQ(pLiveCache, pRegisteredCache);
    releaseStreamDataCacheLease(&pLease);
    pRegisteredCache = nullptr;
    EXPECT_EQ(TSDB_CODE_INVALID_PARA,
              acquireStreamDataCacheLease(RealtimePipelineHarness::kStreamId, RealtimePipelineHarness::kTaskId,
                                          static_cast<int64_t>(recoveryGeneration), &pLease, &pRegisteredCache));
    EXPECT_EQ(nullptr, pLease);
    EXPECT_EQ(nullptr, pRegisteredCache);
    EXPECT_EQ(0, probe.detachedDestroyCalls);
  }
}

