TEST_F(StreamNestedRecoveryTest, CurrentTokenCursorOrderAndDuplicateMismatchesAbort) {
  enum class Mismatch { Identity, Cursor, Order, Duplicate };
  for (Mismatch mismatch : {Mismatch::Identity, Mismatch::Cursor, Mismatch::Order, Mismatch::Duplicate}) {
    SCOPED_TRACE(static_cast<int32_t>(mismatch));
    RealtimePipelineHarness harness;
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 5, 7}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    SSTriggerNestedWalAttempt* pAttempt = harness.pendingRecoveryAttempt(0);
    ASSERT_NE(nullptr, pAttempt);
    switch (mismatch) {
      case Mismatch::Identity:
        ++pAttempt->token.taskId;
        break;
      case Mismatch::Cursor:
        ++pAttempt->request.walMetaDataNewReq.lastVer;
        break;
      case Mismatch::Order:
        ++pAttempt->token.pageSeq;
        break;
      case Mismatch::Duplicate:
        pAttempt->handled = true;
        break;
    }
    EXPECT_NE(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 7, 700));
    EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
    EXPECT_NE(TSDB_CODE_SUCCESS, harness.task()->nestedRecoveryError);
    EXPECT_EQ(0, harness.pendingRecoverySendCount());
  }
}

