TEST_F(StreamNestedRecoveryTest, CalcIteratorAndRunningCalcRequestBlockCutover) {
  NestedRouteRuntimeFixture harness;
  RecoveryShadowProbe       probe;
  probe.allowReplace = true;
  CapturedPullAttempt* pFinalSource = nullptr;
  ASSERT_TRUE(prepareVirtualRecoveryFinalSource(harness, probe, &pFinalSource));
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pFinalSource, NestedRouteRuntimeFixture::kEventTs, 202));
  SSTriggerRealtimeContext* pShadow = harness.shadowContext();
  ASSERT_NE(nullptr, pShadow);
  SSTriggerRealtimeContext* pLive = harness.task()->pRealtimeContext;
  ASSERT_NE(nullptr, pLive);
  ASSERT_NE(nullptr, pLive->pCalcDataCacheIters);
  SSTriggerCalcRequest runningRequest = {};
  pShadow->pCalcReq = &runningRequest;
  constexpr int64_t iterKey = 0x1234;
  void* const       pNullIter = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            taosHashPut(pLive->pCalcDataCacheIters, &iterKey, sizeof(iterKey), &pNullIter, sizeof(pNullIter)));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  EXPECT_EQ(0, probe.replaceCalls);
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  EXPECT_EQ(0, probe.replaceCalls);
  pShadow->pCalcReq = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  EXPECT_EQ(0, probe.replaceCalls);
  ASSERT_EQ(TSDB_CODE_SUCCESS, taosHashRemove(pLive->pCalcDataCacheIters, &iterKey, sizeof(iterKey)));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(1, probe.replaceCalls);
}

TEST_F(StreamNestedRecoveryTest, ConcurrentCacheIteratorAdmissionWaitsForBundlePublication) {
  NestedRouteRuntimeFixture harness;
  RecoveryShadowProbe       probe;
  probe.allowReplace = true;
  CapturedPullAttempt* pFinalSource = nullptr;
  ASSERT_TRUE(prepareVirtualRecoveryFinalSource(harness, probe, &pFinalSource));
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pFinalSource, NestedRouteRuntimeFixture::kEventTs, 202));
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));

  SSTriggerRealtimeContext* const pLive = harness.task()->pRealtimeContext;
  SSTriggerRealtimeContext* const pShadow = harness.shadowContext();
  ASSERT_NE(nullptr, pLive);
  ASSERT_NE(nullptr, pShadow);
  if (pLive->pCalcDataCacheIters == nullptr) {
    ASSERT_EQ(TSDB_CODE_SUCCESS, stCreateCalcDataCacheIterMap(&pLive->pCalcDataCacheIters));
  }
  if (pShadow->pCalcDataCacheIters == nullptr) {
    ASSERT_EQ(TSDB_CODE_SUCCESS, stCreateCalcDataCacheIterMap(&pShadow->pCalcDataCacheIters));
  }

  ScopedStreamContextInput contextInput(NestedRouteRuntimeFixture::kGid);
  ASSERT_NE(nullptr, contextInput.policy());
  ASSERT_NE(nullptr, contextInput.ancestor());
  const auto* pParam =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(contextInput.ancestor()->pParamContexts, 0));
  ASSERT_NE(nullptr, pParam);
  const SStreamCacheScope scope = {
      .gid = pParam->leafIdentity.gid,
      .lineage = {.pScopes = pParam->leafIdentity.lineage.pScopes},
  };
  ASSERT_EQ(TSDB_CODE_SUCCESS, putPoolCacheValue(pLive->pCalcDataCache, &scope, 10));
  ASSERT_EQ(TSDB_CODE_SUCCESS, putPoolCacheValue(pShadow->pCalcDataCache, &scope, 20));

  ScopedTriggerTaskMapRegistration registration(harness.task());
  ASSERT_TRUE(registration.install());

  SStreamRuntimeFuncInfo runtime = {};
  runtime.groupId = NestedRouteRuntimeFixture::kGid;
  runtime.curIdx = 0;
  runtime.sessionId = kRecoveryRealtimeSessionId;
  runtime.curNodeId = harness.task()->task.nodeId;
  runtime.pContextPolicy = contextInput.policy();
  runtime.pAncestorContext = contextInput.ancestor();
  SStreamCacheReadInfo readInfo = {};
  readInfo.taskInfo.streamId = harness.task()->task.streamId;
  readInfo.taskInfo.taskId = harness.task()->task.taskId;
  readInfo.taskInfo.sessionId = kRecoveryRealtimeSessionId;
  readInfo.gid = NestedRouteRuntimeFixture::kGid;
  readInfo.start = 100;
  readInfo.end = 101;
  readInfo.pRuntime = &runtime;
  ScopedCacheReadCleanup readCleanup(&readInfo);

  CacheReaderAcquireHandshake acquireHandshake(harness.task()->task.streamId, harness.task()->task.taskId);
  ASSERT_TRUE(acquireHandshake.install());
  std::mutex       completionMutex;
  bool             readerCompleted = false;
  bool             readerAcquiredBeforeCas = false;
  bool             readerCompletedBeforeCas = true;
  bool             entryReadLockHeldBeforeCas = false;
  bool             iterWriteLockHeldBeforeCas = false;
  int32_t          readCode = TSDB_CODE_INTERNAL_ERROR;
  int32_t          readValue = 0;
  bool             readFinished = true;
  std::thread      reader;
  ScopedThreadJoin joinReader(&reader);
  probe.beforeReplace = [&] {
    reader = std::thread([&] {
      readCode = readStreamDataCache(&readInfo, &readFinished);
      if (readCode == TSDB_CODE_SUCCESS && readInfo.pBlock != nullptr) {
        const auto* pValueCol = static_cast<const SColumnInfoData*>(taosArrayGet(readInfo.pBlock->pDataBlock, 1));
        if (pValueCol != nullptr) {
          readValue = *reinterpret_cast<const int32_t*>(colDataGetData(pValueCol, 0));
        }
      }
      std::lock_guard<std::mutex> lock(completionMutex);
      readerCompleted = true;
    });
    readerAcquiredBeforeCas = acquireHandshake.waitUntilAcquired();
    if (readerAcquiredBeforeCas) {
      entryReadLockHeldBeforeCas = taosWTryLockLatch(&harness.task()->task.entryLock) != 0;
      if (!entryReadLockHeldBeforeCas) taosWUnLockLatch(&harness.task()->task.entryLock);
      iterWriteLockHeldBeforeCas = taosWTryLockLatch(&harness.task()->calcDataCacheIterLock) != 0;
      if (!iterWriteLockHeldBeforeCas) taosWUnLockLatch(&harness.task()->calcDataCacheIterLock);
    }
    {
      std::lock_guard<std::mutex> lock(completionMutex);
      readerCompletedBeforeCas = readerCompleted;
    }
    acquireHandshake.release();
  };

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  if (reader.joinable()) reader.join();
  EXPECT_TRUE(readerAcquiredBeforeCas);
  EXPECT_TRUE(entryReadLockHeldBeforeCas);
  EXPECT_TRUE(iterWriteLockHeldBeforeCas);
  EXPECT_FALSE(readerCompletedBeforeCas);
  EXPECT_EQ(TSDB_CODE_SUCCESS, readCode);
  EXPECT_FALSE(readFinished);
  EXPECT_EQ(20, readValue);
  EXPECT_EQ(pShadow, harness.task()->pRealtimeContext);
  EXPECT_EQ(1, probe.replaceCalls);
  EXPECT_EQ(1, taosHashGetSize(pShadow->pCalcDataCacheIters));
}

TEST_F(StreamNestedRecoveryTest, ActiveAndRetiredRecoveryOwnersGateHistoryAndRecalc) {
  for (RecoveryOwnerMode ownerMode : {RecoveryOwnerMode::Active, RecoveryOwnerMode::RetainedRetired}) {
    SCOPED_TRACE(ownerMode == RecoveryOwnerMode::Active ? "active" : "retained retired");
    RealtimePipelineHarness harness;
    harness.enableNestedTrowsCacheProjection();
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
    std::vector<uint8_t> checkpoint;
    ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 1, 2}}, {}, 0, &checkpoint));
    harness.setCheckpointBytes(std::move(checkpoint));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 2, 200));
    ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
    PipelineWalGroup group = {.gid = RealtimePipelineHarness::kGid,
                              .uid = RealtimePipelineHarness::kUid,
                              .timestamps = {1000},
                              .values = {1},
                              .version = 2};
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryGroups(0, {group}));
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    ASSERT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY_DRAINED, harness.task()->pNestedRecovery->phase);
    SSTriggerRealtimeContext* pShadow = harness.task()->pNestedRecovery->pShadowBundle->pContext;
    ASSERT_NE(nullptr, pShadow);
    auto* ppGroup =
        static_cast<SSTriggerRealtimeGroup**>(tSimpleHashGet(pShadow->pGroups, &group.gid, sizeof(group.gid)));
    ASSERT_NE(nullptr, ppGroup);
    SSTriggerRealtimeGroup* pGroup = *ppGroup;
    ASSERT_NE(nullptr, pGroup);
    ScopedRecoveryOwnerMode owner(harness.task(), ownerMode);
    ASSERT_TRUE(owner.installed());

    const int64_t     readyCount = listNEles(harness.task()->pRecalcRequests);
    const int32_t     pendingGroupCount = tSimpleHashGetSize(harness.task()->pGroupPendingRecalcs);
    STimeWindow       range = {.skey = 900, .ekey = 1100};
    const STimeWindow originalRange = range;
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              stTriggerTaskAddRecalcRequest(harness.task(), pGroup, &range, false, false, false, 0));
    EXPECT_EQ(originalRange.skey, range.skey);
    EXPECT_EQ(originalRange.ekey, range.ekey);
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              stTriggerTaskAddRecalcRequest(harness.task(), nullptr, nullptr, true, false, false, 0));
    ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskReadyRecalcRequest(harness.task(), pGroup));
    pGroup->recalcNextWindow = true;
    ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskTryAddNextWindowRecalc(harness.task(), pGroup, &range));
    EXPECT_TRUE(pGroup->recalcNextWindow);
    auto* pFetched = reinterpret_cast<SSTriggerRecalcRequest*>(uintptr_t{1});
    ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskFetchRecalcRequest(harness.task(), &pFetched));
    EXPECT_EQ(nullptr, pFetched);
    EXPECT_EQ(readyCount, listNEles(harness.task()->pRecalcRequests));
    EXPECT_EQ(pendingGroupCount, tSimpleHashGetSize(harness.task()->pGroupPendingRecalcs));

    SSTriggerHistoryContext history = {};
    history.pTask = harness.task();
    history.sessionId = kRecoveryHistorySessionId;
    history.pCalcReq = reinterpret_cast<SSTriggerCalcRequest*>(uintptr_t{1});
    ASSERT_EQ(nullptr, harness.task()->pHistoryContext);
    harness.task()->pHistoryContext = &history;
    EXPECT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedSessionStartCode(kRecoveryHistorySessionId));
    EXPECT_EQ(reinterpret_cast<SSTriggerCalcRequest*>(uintptr_t{1}), history.pCalcReq);
    harness.task()->pHistoryContext = nullptr;

    SStreamRecalcReq raw = {.recalcId = 7, .start = 900, .end = 1101};
    ASSERT_NE(nullptr, taosArrayPush(harness.task()->pUserRecalcRequests, &raw));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
    EXPECT_EQ(1, taosArrayGetSize(harness.task()->pUserRecalcRequests));
    EXPECT_EQ(nullptr, harness.task()->pUserRecalcConversionGids);
    EXPECT_EQ(0, harness.task()->userRecalcConversionIndex);
    ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
  }
}

TEST_F(StreamNestedRecoveryTest, UserRecalcDuringRecoveryDefersAndConvertsExactlyOnce) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint({{RealtimePipelineHarness::kVgId, 1, 2}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());
  RecoveryShadowProbe probe;
  probe.allowReplace = true;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRecoverySuccess(0, 2, 200, false, false, installRecoveryShadowProbe, &probe));

  SStreamRecalcReq raw = {.recalcId = 8, .start = 900, .end = 1101};
  ASSERT_NE(nullptr, taosArrayPush(harness.task()->pUserRecalcRequests, &raw));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  EXPECT_EQ(1, taosArrayGetSize(harness.task()->pUserRecalcRequests));
  EXPECT_EQ(nullptr, harness.task()->pUserRecalcConversionGids);

  PipelineWalGroup first = {.gid = RealtimePipelineHarness::kGid,
                            .uid = RealtimePipelineHarness::kUid,
                            .timestamps = {1000},
                            .values = {1},
                            .version = 2};
  PipelineWalGroup second = {.gid = RealtimePipelineHarness::kGid + 1,
                             .uid = RealtimePipelineHarness::kUid + 1,
                             .timestamps = {1000},
                             .values = {2},
                             .version = 2};
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryGroups(0, {first, second}));
  EXPECT_EQ(1, taosArrayGetSize(harness.task()->pUserRecalcRequests));
  EXPECT_EQ(nullptr, harness.task()->pUserRecalcConversionGids);
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  ASSERT_EQ(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(1, taosArrayGetSize(harness.task()->pUserRecalcRequests));

  UserRecalcConversionProbe conversionProbe;
  conversionProbe.failCall = 2;
  installUserRecalcConversionProbe(&conversionProbe);
  EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, harness.dispatchSerializedRealtimeStartCode());
  EXPECT_EQ(2, conversionProbe.callCount);
  EXPECT_EQ(1, taosArrayGetSize(harness.task()->pUserRecalcRequests));
  ASSERT_NE(nullptr, harness.task()->pUserRecalcConversionGids);
  EXPECT_EQ(2, taosArrayGetSize(harness.task()->pUserRecalcConversionGids));
  EXPECT_EQ(1, harness.task()->userRecalcConversionIndex);
  EXPECT_EQ(1, listNEles(harness.task()->pRecalcRequests));
  SListNode* pFirstReadyNode = tdListGetHead(harness.task()->pRecalcRequests);
  ASSERT_NE(nullptr, pFirstReadyNode);
  auto* pFirstReady = *reinterpret_cast<SSTriggerRecalcRequest**>(pFirstReadyNode->data);
  ASSERT_NE(nullptr, pFirstReady);
  EXPECT_TRUE(pFirstReady->frozen);
  EXPECT_NE(0, pFirstReady->attempt.chainId);
  EXPECT_EQ(0, pFirstReady->attempt.executionOrdinal);
  EXPECT_EQ(nullptr, pFirstReady->pPreparedAttempt);
  EXPECT_NE(nullptr, pFirstReady->pRetryWaitNode);
  EXPECT_NE(nullptr, pFirstReady->impactDomain.pRootExtents);

  conversionProbe.failCall = 0;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  EXPECT_EQ(3, conversionProbe.callCount);
  EXPECT_EQ(0, taosArrayGetSize(harness.task()->pUserRecalcRequests));
  EXPECT_EQ(nullptr, harness.task()->pUserRecalcConversionGids);
  EXPECT_EQ(0, harness.task()->userRecalcConversionIndex);
  EXPECT_EQ(2, listNEles(harness.task()->pRecalcRequests));
  std::unordered_set<uint64_t> chainIds;
  std::unordered_set<int64_t>  gids;
  SListIter                    readyIter = {};
  tdListInitIter(harness.task()->pRecalcRequests, &readyIter, TD_LIST_FORWARD);
  SListNode* pReadyNode = nullptr;
  while ((pReadyNode = tdListNext(&readyIter)) != nullptr) {
    auto* pReady = *reinterpret_cast<SSTriggerRecalcRequest**>(pReadyNode->data);
    ASSERT_NE(nullptr, pReady);
    EXPECT_TRUE(pReady->frozen);
    EXPECT_NE(0, pReady->attempt.chainId);
    EXPECT_EQ(0, pReady->attempt.executionOrdinal);
    EXPECT_EQ(nullptr, pReady->pPreparedAttempt);
    EXPECT_NE(nullptr, pReady->pRetryWaitNode);
    EXPECT_NE(nullptr, pReady->impactDomain.pRootExtents);
    ASSERT_NE(nullptr, pReady->pContributors);
    ASSERT_EQ(1, taosArrayGetSize(pReady->pContributors));
    const auto* pContributor = static_cast<const SStreamRecalcContributor*>(taosArrayGet(pReady->pContributors, 0));
    ASSERT_NE(nullptr, pContributor);
    EXPECT_EQ(8, pContributor->recalcId);
    EXPECT_TRUE(chainIds.insert(pReady->attempt.chainId).second);
    EXPECT_TRUE(gids.insert(pReady->gid).second);
  }
  EXPECT_EQ(2, chainIds.size());
  EXPECT_EQ(2, gids.size());
}

