TEST_F(StreamNestedRecoveryTest, NormalRollupCountContinuesAfterBundleCutover) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_NONE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, true, 0, false, 2, false, {"ws://pipeline-notify.test"}, 0,
                           true));
  std::vector<uint8_t> checkpoint;
  ASSERT_TRUE(makeRecoveryCheckpoint(
      {{RealtimePipelineHarness::kVgId, 1, 2}, {RealtimePipelineHarness::kVgId + 1, 1, 2}}, {}, 0, &checkpoint));
  harness.setCheckpointBytes(std::move(checkpoint));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startCode());

  RecoveryShadowProbe probe;
  probe.allowReplace = true;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoverySuccess(0, 2, 200));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRecoverySuccess(0, 2, 200, false, false, installRecoveryShadowProbe, &probe));
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  PipelineWalGroup replayVg7 = {.gid = RealtimePipelineHarness::kGid,
                                .uid = RealtimePipelineHarness::kUid,
                                .timestamps = {1000},
                                .values = {1},
                                .version = 2,
                                .hasRollupTbCount = true,
                                .rollupTbCount = 7};
  PipelineWalGroup replayVg8 = {.gid = RealtimePipelineHarness::kGid,
                                .uid = RealtimePipelineHarness::kUid + 1,
                                .timestamps = {1000},
                                .values = {2},
                                .version = 2,
                                .hasRollupTbCount = true,
                                .rollupTbCount = 11};
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryGroups(0, {replayVg7}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryGroups(0, {replayVg8}));
  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  ASSERT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY_DRAINED, harness.task()->pNestedRecovery->phase);
  SSTriggerRealtimeContext* pShadow = harness.task()->pNestedRecovery->pShadowBundle->pContext;
  ASSERT_NE(nullptr, pShadow);
  ASSERT_NE(nullptr, pShadow->pRollupTbCount);
  ASSERT_NE(nullptr, pShadow->pRollupTbCountSeen);
  const int64_t seenKeyVg7[2] = {RealtimePipelineHarness::kVgId, RealtimePipelineHarness::kGid};
  const int64_t seenKeyVg8[2] = {RealtimePipelineHarness::kVgId + 1, RealtimePipelineHarness::kGid};
  auto* pSeenVg7 = static_cast<int32_t*>(tSimpleHashGet(pShadow->pRollupTbCountSeen, seenKeyVg7, sizeof(seenKeyVg7)));
  auto* pSeenVg8 = static_cast<int32_t*>(tSimpleHashGet(pShadow->pRollupTbCountSeen, seenKeyVg8, sizeof(seenKeyVg8)));
  auto* pCount = static_cast<int32_t*>(
      tSimpleHashGet(pShadow->pRollupTbCount, &RealtimePipelineHarness::kGid, sizeof(RealtimePipelineHarness::kGid)));
  ASSERT_NE(nullptr, pSeenVg7);
  ASSERT_NE(nullptr, pSeenVg8);
  ASSERT_NE(nullptr, pCount);
  EXPECT_EQ(7, *pSeenVg7);
  EXPECT_EQ(11, *pSeenVg8);
  EXPECT_EQ(18, *pCount);
  EXPECT_EQ(0, probe.replaceCalls);

  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  EXPECT_EQ(pShadow, harness.task()->pRealtimeContext);
  EXPECT_TRUE(pShadow->boundDetermined);
  EXPECT_EQ(1, probe.replaceCalls);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStartCode());
  ASSERT_EQ(0, harness.pendingPullCount(STRIGGER_PULL_LAST_TS));
  ASSERT_EQ(2, harness.pendingPullCount(STRIGGER_PULL_WAL_META_DATA_NEW));
  PipelineWalGroup realtimeVg7 = {.gid = RealtimePipelineHarness::kGid,
                                  .uid = RealtimePipelineHarness::kUid,
                                  .timestamps = {1001},
                                  .values = {3},
                                  .version = 3,
                                  .hasRollupTbCount = true,
                                  .rollupTbCount = 10};
  PipelineWalGroup realtimeVg8 = {.gid = RealtimePipelineHarness::kGid,
                                  .uid = RealtimePipelineHarness::kUid + 1,
                                  .timestamps = {1001},
                                  .values = {4},
                                  .version = 3,
                                  .hasRollupTbCount = true,
                                  .rollupTbCount = 13};
  ASSERT_TRUE(harness.feedGroups({realtimeVg7}));
  ASSERT_TRUE(harness.feedGroups({realtimeVg8}));
  pSeenVg7 = static_cast<int32_t*>(
      tSimpleHashGet(harness.task()->pRealtimeContext->pRollupTbCountSeen, seenKeyVg7, sizeof(seenKeyVg7)));
  pSeenVg8 = static_cast<int32_t*>(
      tSimpleHashGet(harness.task()->pRealtimeContext->pRollupTbCountSeen, seenKeyVg8, sizeof(seenKeyVg8)));
  pCount = static_cast<int32_t*>(tSimpleHashGet(harness.task()->pRealtimeContext->pRollupTbCount,
                                                &RealtimePipelineHarness::kGid, sizeof(RealtimePipelineHarness::kGid)));
  ASSERT_NE(nullptr, pSeenVg7);
  ASSERT_NE(nullptr, pSeenVg8);
  ASSERT_NE(nullptr, pCount);
  EXPECT_EQ(10, *pSeenVg7);
  EXPECT_EQ(13, *pSeenVg8);
  EXPECT_EQ(23, *pCount);
  EXPECT_EQ(1, probe.replaceCalls);
}

TEST_F(StreamNestedRecoveryTest, VirtualPseudoAhandleOwnsRecoveryTokenNotLiveOwner) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair());
  ASSERT_TRUE(harness.setRecoveryCheckpoint(1, 2, 1, 2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilRecoveryWalAttempts(2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_VALIDATE));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_VALIDATE));

  const SStreamTaskAddr* pFrozenReader = harness.frozenRecoveryReader(0);
  ASSERT_NE(nullptr, pFrozenReader);
  const SEpSet frozenEndpoint = pFrozenReader->epset;
  ASSERT_TRUE(harness.mutateLiveReaderEndpoint(0, "mutated-live-reader.test", 6799));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_REPLAY));
  EXPECT_EQ(0U, harness.nestedAttemptCount());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_REPLAY));
  ASSERT_EQ(2U, harness.nestedAttemptCount());

  CapturedPullAttempt* pPseudo = harness.findNestedAttempt(0);
  ASSERT_NE(nullptr, pPseudo);
  SSTriggerNestedPseudoAttempt* pOwner = harness.recoveryPseudoOwner(*pPseudo);
  ASSERT_NE(nullptr, pOwner);
  SSTriggerNestedPeerSource* pSource = harness.shadowSource(pPseudo->route);
  ASSERT_NE(nullptr, pSource);
  EXPECT_EQ(STREAM_NESTED_INPUT_RECOVERY, pPseudo->route.owner);
  EXPECT_EQ(STRIGGER_AHANDLE_PARAM_NESTED_RECOVERY_PSEUDO, pPseudo->ahandleParamType);
  EXPECT_EQ(reinterpret_cast<uintptr_t>(harness.task()->pNestedRecovery), pPseudo->recoveryAddress);
  EXPECT_EQ(harness.task()->pNestedRecovery->generation, pPseudo->recoveryGeneration);
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY, pPseudo->recoveryPhase);
  EXPECT_EQ(harness.task()->pNestedRecovery->replayRoundSeq, pPseudo->recoveryRoundSeq);
  EXPECT_GT(pPseudo->attemptSerial, 0U);
  EXPECT_NE(reinterpret_cast<uintptr_t>(&pSource->request), pPseudo->requestAddress);
  EXPECT_NE(reinterpret_cast<uintptr_t>(pSource->request.cids), pPseudo->requestCidsAddress);
  EXPECT_NE(reinterpret_cast<uintptr_t>(pPseudo->requestCont), pPseudo->requestPayloadAddress);
  ASSERT_EQ(pPseudo->requestLen, pOwner->requestPayloadLen);
  EXPECT_EQ(0, std::memcmp(pPseudo->requestCont, pOwner->pRequestPayload, static_cast<size_t>(pPseudo->requestLen)));
  EXPECT_TRUE(isEpsetEqual(&frozenEndpoint, &pPseudo->endpoint));

  SSTriggerRealtimeContext* pLiveContext = harness.task()->pRealtimeContext;
  ASSERT_NE(nullptr, pLiveContext);
  const uint64_t       liveNextGeneration = pLiveContext->nextNestedInputGeneration;
  const int32_t        liveGroupCount = tSimpleHashGetSize(pLiveContext->pGroups);
  const int64_t        liveRetryCount = listNEles(&pLiveContext->retryPullReqs);
  CapturedPullAttempt* pSibling = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pSibling);
  EXPECT_EQ(NestedRouteRuntimeFixture::kTerminalInputCode,
            harness.respondError(*pSibling, NestedRouteRuntimeFixture::kTerminalInputCode));
  EXPECT_EQ(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pPseudo, TSDB_CODE_RPC_NETWORK_UNAVAIL));
  EXPECT_EQ(liveNextGeneration, pLiveContext->nextNestedInputGeneration);
  EXPECT_EQ(liveGroupCount, tSimpleHashGetSize(pLiveContext->pGroups));
  EXPECT_EQ(liveRetryCount, listNEles(&pLiveContext->retryPullReqs));
}

TEST_F(StreamNestedRecoveryTest, VirtualAsymmetricReplayWaitsForRoundDrainAndSkipsCompletedReader) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair());
  ASSERT_TRUE(harness.setRecoveryCheckpoint(1, 2, 1, 3));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilRecoveryWalAttempts(2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_VALIDATE, 2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_VALIDATE, 2));
  ASSERT_NE(nullptr, harness.findRecoveryWalAttempt(1, STRIGGER_NESTED_RECOVERY_VALIDATE));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_VALIDATE, 3));

  ASSERT_EQ(2U, harness.recoveryWalAttemptCount(STRIGGER_NESTED_RECOVERY_REPLAY));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_REPLAY, 2));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_REPLAY, 2));
  ASSERT_EQ(2U, harness.nestedAttemptCount());
  const uint64_t firstRound = harness.task()->pNestedRecovery->replayRoundSeq;
  EXPECT_EQ(0U, harness.recoveryWalAttemptCount(STRIGGER_NESTED_RECOVERY_REPLAY));

  CapturedPullAttempt* pRound1A = harness.findNestedAttempt(0);
  CapturedPullAttempt* pRound1B = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pRound1A);
  ASSERT_NE(nullptr, pRound1B);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pRound1A, NestedRouteRuntimeFixture::kEventTs, 101));
  EXPECT_EQ(0U, harness.recoveryWalAttemptCount(STRIGGER_NESTED_RECOVERY_REPLAY));
  EXPECT_EQ(firstRound, harness.task()->pNestedRecovery->replayRoundSeq);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pRound1B, NestedRouteRuntimeFixture::kEventTs, 202));

  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(firstRound + 1, harness.task()->pNestedRecovery->replayRoundSeq);
  EXPECT_EQ(nullptr, harness.findRecoveryWalAttempt(0, STRIGGER_NESTED_RECOVERY_REPLAY));
  ASSERT_NE(nullptr, harness.findRecoveryWalAttempt(1, STRIGGER_NESTED_RECOVERY_REPLAY));
  EXPECT_EQ(1U, harness.recoveryWalAttemptCount(STRIGGER_NESTED_RECOVERY_REPLAY));
  harness.setWalEventTs(NestedRouteRuntimeFixture::kEventTs + 1);
  harness.setFrontierTs(NestedRouteRuntimeFixture::kEventTs + 1);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_REPLAY, 3));

  SSTriggerRealtimeContext* pShadow = harness.shadowContext();
  SSTriggerRealtimeGroup*   pGroup = harness.shadowGroup();
  ASSERT_NE(nullptr, pShadow);
  ASSERT_NE(nullptr, pGroup);
  const SSTriggerReaderDataKey retainedTableKey =
      stTriggerTaskInternalReaderDataKey(0, harness.tableUid(0), harness.reader(0).nodeId);
  EXPECT_NE(nullptr, tSimpleHashGet(pShadow->pSlices, &retainedTableKey, sizeof(retainedTableKey)));
  ASSERT_NE(nullptr, pGroup->pNestedPeerSources);
  ASSERT_EQ(1, taosArrayGetSize(pGroup->pNestedPeerSources));
  const auto* pOnlySource = static_cast<const SSTriggerNestedPeerSource*>(taosArrayGet(pGroup->pNestedPeerSources, 0));
  ASSERT_NE(nullptr, pOnlySource);
  EXPECT_EQ(harness.tableUid(1), pOnlySource->tableUid);
  EXPECT_EQ(1, pOnlySource->sourceIndex);
  EXPECT_EQ(1, pGroup->tableUids.neles);
  ASSERT_EQ(1U, harness.nestedAttemptCount());
  CapturedPullAttempt* pRound2B = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pRound2B);
  ASSERT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), true));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pRound2B, NestedRouteRuntimeFixture::kEventTs + 1, 303));

  ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
  EXPECT_EQ(STRIGGER_NESTED_RECOVERY_REPLAY_DRAINED, harness.task()->pNestedRecovery->phase);
  const auto* pReaderA =
      static_cast<const SSTriggerNestedWalReader*>(taosArrayGet(harness.task()->pNestedRecovery->pWalReaders, 0));
  const auto* pReaderB =
      static_cast<const SSTriggerNestedWalReader*>(taosArrayGet(harness.task()->pNestedRecovery->pWalReaders, 1));
  ASSERT_NE(nullptr, pReaderA);
  ASSERT_NE(nullptr, pReaderB);
  EXPECT_TRUE(pReaderA->completed);
  EXPECT_EQ(2, pReaderA->cursor);
  EXPECT_EQ(1U, pReaderA->nextPageSeq);
  EXPECT_TRUE(pReaderB->completed);
  EXPECT_EQ(3, pReaderB->cursor);
  EXPECT_EQ(2U, pReaderB->nextPageSeq);
  EXPECT_TRUE(setRecoveryCutoverRunningBlocker(harness.task(), false));
}

TEST_F(StreamNestedRecoveryTest, VirtualReplayLedgerMismatchAbortsBeforePseudoOrCutover) {
  enum class Mismatch { RequestCursor, Endpoint, ExtraPage };
  for (Mismatch mismatch : {Mismatch::RequestCursor, Mismatch::Endpoint, Mismatch::ExtraPage}) {
    SCOPED_TRACE(static_cast<int32_t>(mismatch));
    NestedRouteRuntimeFixture harness;
    RecoveryShadowProbe       probe;
    ASSERT_TRUE(harness.deployNestedVirtualPair());
    ASSERT_TRUE(harness.setRecoveryCheckpoint(1, 2, 1, 2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilRecoveryWalAttempts(2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_VALIDATE));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(1, STRIGGER_NESTED_RECOVERY_VALIDATE, 2,
                                                                installRecoveryShadowProbe, &probe));
    ASSERT_NE(nullptr, harness.task()->pNestedRecovery);
    SStreamTriggerTask*       pTask = harness.task();
    SSTriggerRealtimeContext* pLiveContext = pTask->pRealtimeContext;
    void*                     pLiveCache = pLiveContext->pCalcDataCache;
    auto* pReader = static_cast<SSTriggerNestedWalReader*>(taosArrayGet(pTask->pNestedRecovery->pWalReaders, 0));
    ASSERT_NE(nullptr, pReader);
    auto* pPage = static_cast<SSTriggerNestedWalPage*>(taosArrayGet(pReader->pValidateLedger, 0));
    ASSERT_NE(nullptr, pPage);
    if (mismatch == Mismatch::RequestCursor) {
      ++pPage->requestCursor;
    } else if (mismatch == Mismatch::Endpoint) {
      ++pPage->endpoint;
    } else {
      SSTriggerNestedWalPage extra = {.requestCursor = 2, .endpoint = 3};
      ASSERT_NE(nullptr, taosArrayPush(pReader->pValidateLedger, &extra));
    }

    EXPECT_NE(TSDB_CODE_SUCCESS, harness.respondRecoveryWalPage(0, STRIGGER_NESTED_RECOVERY_REPLAY));
    EXPECT_EQ(nullptr, pTask->pNestedRecovery);
    EXPECT_EQ(0U, harness.nestedAttemptCount());
    EXPECT_EQ(pLiveContext, pTask->pRealtimeContext);
    EXPECT_EQ(pLiveCache, pTask->pRealtimeContext->pCalcDataCache);
    EXPECT_EQ(0, probe.replaceCalls);
  }
}

