TEST_F(StreamNestedRealtimeTest, StaleInputRouteDoesNotBindReplacementCursor) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));

  CapturedPullAttempt* pOldSource0 = harness.findNestedAttempt(0);
  CapturedPullAttempt* pOldSource1 = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pOldSource0);
  ASSERT_NE(nullptr, pOldSource1);
  const uint64_t      oldGeneration = pOldSource0->route.generation;
  const EStreamStatus taskStatusBeforeTerminal = harness.taskStatus();
  const int32_t       taskErrorBeforeTerminal = harness.taskErrorCode();
  EXPECT_EQ(oldGeneration, pOldSource1->route.generation);
  EXPECT_NE(STREAM_STATUS_FAILED, taskStatusBeforeTerminal);
  EXPECT_EQ(TSDB_CODE_SUCCESS, taskErrorBeforeTerminal);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pOldSource1, NestedRouteRuntimeFixture::kTerminalInputCode));
  EXPECT_EQ(taskStatusBeforeTerminal, harness.taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness.taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness.taskStatus());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(3));
  EXPECT_EQ(taskStatusBeforeTerminal, harness.taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness.taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness.taskStatus());

  CapturedPullAttempt* pReplacement0 = harness.findNewerNestedAttempt(0, oldGeneration);
  CapturedPullAttempt* pReplacement1 = harness.findNewerNestedAttempt(1, oldGeneration);
  ASSERT_NE(nullptr, pReplacement0);
  ASSERT_NE(nullptr, pReplacement1);
  EXPECT_EQ(pOldSource0->route.ownerId, pReplacement0->route.ownerId);
  EXPECT_EQ(pOldSource0->route.sourceIndex, pReplacement0->route.sourceIndex);
  EXPECT_GT(pReplacement0->route.generation, oldGeneration);
  EXPECT_EQ(pReplacement0->route.generation, pReplacement1->route.generation);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pReplacement0, NestedRouteRuntimeFixture::kEventTs, 222));
  EXPECT_EQ(0, harness.calcSendCount());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pReplacement1, NestedRouteRuntimeFixture::kEventTs, 333));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  ASSERT_EQ(1, harness.calcSendCount());

  const SSTriggerCalcRequest* pCalcBefore = harness.latestCalc();
  ASSERT_NE(nullptr, pCalcBefore);
  ASSERT_NE(nullptr, pCalcBefore->params);
  ASSERT_EQ(1, taosArrayGetSize(pCalcBefore->params));
  const auto* pParamBefore = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalcBefore->params, 0));
  ASSERT_NE(nullptr, pParamBefore);
  const TSKEY   wstartBefore = pParamBefore->wstart;
  const TSKEY   wendBefore = pParamBefore->wend;
  const int64_t rowCountBefore = pParamBefore->wrownum;
  EXPECT_EQ(2, rowCountBefore);

  ASSERT_NE(nullptr, pCalcBefore->pAncestorContext);
  ASSERT_NE(nullptr, pCalcBefore->pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(pCalcBefore->pAncestorContext->pParamContexts));
  const auto* pContextBefore =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(pCalcBefore->pAncestorContext->pParamContexts, 0));
  ASSERT_NE(nullptr, pContextBefore);
  std::vector<ObservedScopedRow> rowsBefore;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readCommittedRows(*pContextBefore, &rowsBefore));
  const std::vector<ObservedScopedRow> expectedRows = {
      {harness.tableUid(0), 222},
      {harness.tableUid(1), 333},
  };
  EXPECT_EQ(expectedRows, rowsBefore);

  bool noticePending = true;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.confirmNoDeferredNotice(&noticePending));
  EXPECT_FALSE(noticePending);
  const int32_t       noticeCountBefore = harness.noticeSendCount();
  const EStreamStatus taskStatusBefore = harness.taskStatus();
  const int32_t       taskErrorBefore = harness.taskErrorCode();
  EXPECT_NE(STREAM_STATUS_FAILED, taskStatusBefore);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondBlock(*pOldSource0, NestedRouteRuntimeFixture::kEventTs, 111));
  EXPECT_EQ(1, harness.calcSendCount());
  noticePending = true;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.confirmNoDeferredNotice(&noticePending));
  EXPECT_FALSE(noticePending);
  EXPECT_EQ(noticeCountBefore, harness.noticeSendCount());
  EXPECT_EQ(taskStatusBefore, harness.taskStatus());
  EXPECT_EQ(taskErrorBefore, harness.taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness.taskStatus());

  const SSTriggerCalcRequest* pCalcAfter = harness.latestCalc();
  ASSERT_NE(nullptr, pCalcAfter);
  ASSERT_NE(nullptr, pCalcAfter->params);
  ASSERT_EQ(1, taosArrayGetSize(pCalcAfter->params));
  const auto* pParamAfter = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalcAfter->params, 0));
  ASSERT_NE(nullptr, pParamAfter);
  EXPECT_EQ(wstartBefore, pParamAfter->wstart);
  EXPECT_EQ(wendBefore, pParamAfter->wend);
  EXPECT_EQ(rowCountBefore, pParamAfter->wrownum);
  ASSERT_NE(nullptr, pCalcAfter->pAncestorContext);
  ASSERT_NE(nullptr, pCalcAfter->pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(pCalcAfter->pAncestorContext->pParamContexts));
  const auto* pContextAfter =
      static_cast<const SStreamAncestorParamContext*>(taosArrayGet(pCalcAfter->pAncestorContext->pParamContexts, 0));
  ASSERT_NE(nullptr, pContextAfter);
  std::vector<ObservedScopedRow> rowsAfter;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readCommittedRows(*pContextAfter, &rowsAfter));
  EXPECT_EQ(expectedRows, rowsAfter);
}

TEST_F(StreamNestedRealtimeTest, CancelFreesInputRouteOnce) {
  std::unique_ptr<NestedRouteRuntimeFixture> harness(new NestedRouteRuntimeFixture());
  ASSERT_TRUE(harness->deployNestedVirtualPair());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->driveUntilNestedAttempts(2));

  CapturedPullAttempt* pHeld = harness->findNestedAttempt(0);
  CapturedPullAttempt* pSibling = harness->findNestedAttempt(1);
  ASSERT_NE(nullptr, pHeld);
  ASSERT_NE(nullptr, pSibling);
  const uint64_t      oldGeneration = pHeld->route.generation;
  const EStreamStatus taskStatusBeforeTerminal = harness->taskStatus();
  const int32_t       taskErrorBeforeTerminal = harness->taskErrorCode();
  EXPECT_NE(STREAM_STATUS_FAILED, taskStatusBeforeTerminal);
  EXPECT_EQ(TSDB_CODE_SUCCESS, taskErrorBeforeTerminal);
  ScopedParamFreeProbe probe(pHeld->pSendInfo);
  ASSERT_TRUE(probe.valid());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->respondError(*pSibling, NestedRouteRuntimeFixture::kTerminalInputCode));
  EXPECT_EQ(0, probe.calls());
  EXPECT_FALSE(probe.sawUnexpectedParam());
  EXPECT_EQ(taskStatusBeforeTerminal, harness->taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness->taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness->taskStatus());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->dispatchSerializedRealtimeStart());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->driveUntilNestedAttempts(3));
  EXPECT_EQ(taskStatusBeforeTerminal, harness->taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness->taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness->taskStatus());
  CapturedPullAttempt* pReplacement = harness->findNewerNestedAttempt(0, oldGeneration);
  ASSERT_NE(nullptr, pReplacement);
  EXPECT_GT(pReplacement->route.generation, oldGeneration);
  EXPECT_EQ(0, probe.calls());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness->cleanupAttempt(*pHeld));
  EXPECT_EQ(1, probe.calls());
  EXPECT_FALSE(probe.sawUnexpectedParam());

  harness.reset();
  EXPECT_EQ(1, probe.calls());
  EXPECT_FALSE(probe.sawUnexpectedParam());
}

TEST_F(StreamNestedRealtimeTest, NestedInputRetryClonesRoutePerAttempt) {
  NestedRouteRuntimeFixture harness;
  ASSERT_TRUE(harness.deployNestedVirtualPair());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startThroughPublicExecute());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));

  CapturedPullAttempt* pAttempt1 = harness.findNestedAttempt(0);
  CapturedPullAttempt* pSibling = harness.findNestedAttempt(1);
  ASSERT_NE(nullptr, pAttempt1);
  ASSERT_NE(nullptr, pSibling);
  const uint64_t                generation = pAttempt1->route.generation;
  const SStreamNestedInputRoute route1 = pAttempt1->route;
  NestedPullValue               request1;
  ASSERT_TRUE(captureNestedPullValue(*pAttempt1, &request1));
  ASSERT_FALSE(request1.cids.empty());
  const int32_t       calcCountBeforeRetry = harness.calcSendCount();
  const int32_t       noticeCountBeforeRetry = harness.noticeSendCount();
  const EStreamStatus taskStatusBeforeRetry = harness.taskStatus();
  const int32_t       taskErrorBeforeRetry = harness.taskErrorCode();
  EXPECT_NE(STREAM_STATUS_FAILED, taskStatusBeforeRetry);

  {
    ScopedParamFreeProbe probe(pAttempt1->pSendInfo);
    ASSERT_TRUE(probe.valid());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pAttempt1, TSDB_CODE_RPC_NETWORK_UNAVAIL));
    EXPECT_TRUE(pAttempt1->transportCleaned);
    EXPECT_EQ(nullptr, pAttempt1->pSendInfo);
    EXPECT_EQ(1, probe.calls());
    EXPECT_FALSE(probe.sawUnexpectedParam());
  }
  expectNoNestedRetrySideEffects(harness, calcCountBeforeRetry, noticeCountBeforeRetry, taskStatusBeforeRetry,
                                 taskErrorBeforeRetry);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  CapturedPullAttempt* pAttempt2 = harness.findNestedAttempt(0, generation);
  ASSERT_NE(nullptr, pAttempt2);
  NestedPullValue request2;
  ASSERT_TRUE(captureNestedPullValue(*pAttempt2, &request2));
  expectNestedRouteEq(route1, pAttempt2->route);
  expectNestedPullValueEq(request1, request2);

  {
    ScopedParamFreeProbe probe(pAttempt2->pSendInfo);
    ASSERT_TRUE(probe.valid());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pAttempt2, TSDB_CODE_RPC_NETWORK_UNAVAIL));
    EXPECT_TRUE(pAttempt2->transportCleaned);
    EXPECT_EQ(nullptr, pAttempt2->pSendInfo);
    EXPECT_EQ(1, probe.calls());
    EXPECT_FALSE(probe.sawUnexpectedParam());
  }
  expectNoNestedRetrySideEffects(harness, calcCountBeforeRetry, noticeCountBeforeRetry, taskStatusBeforeRetry,
                                 taskErrorBeforeRetry);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  CapturedPullAttempt* pAttempt3 = harness.findNestedAttempt(0, generation);
  ASSERT_NE(nullptr, pAttempt3);
  NestedPullValue request3;
  ASSERT_TRUE(captureNestedPullValue(*pAttempt3, &request3));
  expectNestedRouteEq(route1, pAttempt3->route);
  expectNestedPullValueEq(request1, request3);

  {
    ScopedParamFreeProbe probe(pAttempt3->pSendInfo);
    ASSERT_TRUE(probe.valid());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pAttempt3, TSDB_CODE_RPC_NETWORK_UNAVAIL));
    EXPECT_TRUE(pAttempt3->transportCleaned);
    EXPECT_EQ(nullptr, pAttempt3->pSendInfo);
    EXPECT_EQ(1, probe.calls());
    EXPECT_FALSE(probe.sawUnexpectedParam());
  }
  expectNoNestedRetrySideEffects(harness, calcCountBeforeRetry, noticeCountBeforeRetry, taskStatusBeforeRetry,
                                 taskErrorBeforeRetry);
  ASSERT_EQ(3U, harness.nestedAttemptCountFor(0, generation));

  const EStreamStatus taskStatusBeforeTerminal = harness.taskStatus();
  const int32_t       taskErrorBeforeTerminal = harness.taskErrorCode();
  EXPECT_NE(STREAM_STATUS_FAILED, taskStatusBeforeTerminal);
  EXPECT_EQ(TSDB_CODE_SUCCESS, taskErrorBeforeTerminal);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondError(*pSibling, NestedRouteRuntimeFixture::kTerminalInputCode));
  EXPECT_EQ(taskStatusBeforeTerminal, harness.taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness.taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness.taskStatus());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedRealtimeStart());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveUntilNestedAttempts(2));
  EXPECT_EQ(taskStatusBeforeTerminal, harness.taskStatus());
  EXPECT_EQ(taskErrorBeforeTerminal, harness.taskErrorCode());
  EXPECT_NE(STREAM_STATUS_FAILED, harness.taskStatus());
  EXPECT_EQ(3U, harness.nestedAttemptCountFor(0, generation));
  CapturedPullAttempt* pReplacement = harness.findNewerNestedAttempt(0, generation);
  ASSERT_NE(nullptr, pReplacement);
  EXPECT_GT(pReplacement->route.generation, generation);
}

