static int32_t gNestedHistoryAhandleAllocFailures = 0;
static int32_t gNestedHistoryAhandleAllocCalls = 0;
static Stub*   gNestedHistoryAllocStub = nullptr;
static Stub*   gNestedInputRouteAllocStub = nullptr;
static int32_t gNestedHistoryFailPointerArrayInit = 0;
static int32_t gNestedHistoryFailPointerArrayPush = 0;
static Stub*   gNestedHistoryPointerArrayStub = nullptr;

static void* failNestedHistoryAhandleCalloc(int64_t num, int64_t size) {
  if (num == 1 && size == sizeof(SMsgSendInfo)) {
    ++gNestedHistoryAhandleAllocCalls;
    if (gNestedHistoryAhandleAllocFailures > 0) {
      --gNestedHistoryAhandleAllocFailures;
      terrno = TSDB_CODE_OUT_OF_MEMORY;
      return nullptr;
    }
  }

  gNestedHistoryAllocStub->reset(taosMemCalloc);
  void* pResult = taosMemCalloc(num, size);
  gNestedHistoryAllocStub->set(taosMemCalloc, failNestedHistoryAhandleCalloc);
  return pResult;
}

static void* failNestedInputRouteMalloc(int64_t size) {
  if (size == sizeof(SStreamNestedInputRoute)) {
    terrno = TSDB_CODE_OUT_OF_MEMORY;
    return nullptr;
  }

  gNestedInputRouteAllocStub->reset(taosMemMalloc);
  void* pResult = taosMemMalloc(size);
  gNestedInputRouteAllocStub->set(taosMemMalloc, failNestedInputRouteMalloc);
  return pResult;
}

static int32_t serializeNestedHistoryCalcFast(void* pBuf, int32_t bufLen, const SSTriggerCalcRequest*) {
  if (pBuf != nullptr && bufLen > 0) *static_cast<char*>(pBuf) = 0;
  return 1;
}

static int32_t acceptNestedHistoryCalcRequest(const SSTriggerCalcRequest*) { return TSDB_CODE_SUCCESS; }

static SArray* failNestedHistoryPointerArrayInit(size_t size, size_t elemSize) {
  if (gNestedHistoryFailPointerArrayInit > 0 && size == 0 && elemSize == POINTER_BYTES) {
    if (--gNestedHistoryFailPointerArrayInit == 0) {
      terrno = TSDB_CODE_OUT_OF_MEMORY;
      return nullptr;
    }
  }
  gNestedHistoryPointerArrayStub->reset(taosArrayInit);
  SArray* pArray = taosArrayInit(size, elemSize);
  gNestedHistoryPointerArrayStub->set(taosArrayInit, failNestedHistoryPointerArrayInit);
  return pArray;
}

static void* failNestedHistoryPointerArrayPush(SArray* pArray, const void* pData, int32_t nEles) {
  if (gNestedHistoryFailPointerArrayPush > 0 && pArray != nullptr && pArray->elemSize == POINTER_BYTES &&
      taosArrayGetSize(pArray) == 0 && nEles == 1) {
    if (--gNestedHistoryFailPointerArrayPush == 0) {
      terrno = TSDB_CODE_OUT_OF_MEMORY;
      return nullptr;
    }
  }
  gNestedHistoryPointerArrayStub->reset(taosArrayAddBatch);
  void* pValue = taosArrayAddBatch(pArray, pData, nEles);
  gNestedHistoryPointerArrayStub->set(taosArrayAddBatch, failNestedHistoryPointerArrayPush);
  return pValue;
}

static Stub*  gRealtimeMaterializationHashStub = nullptr;
static size_t gRealtimeMaterializationHashCapacity = 0;

static SSHashObj* failRealtimeMaterializationRangeHash(size_t capacity, _hash_fn_t hashFn) {
  if (capacity == gRealtimeMaterializationHashCapacity) {
    terrno = TSDB_CODE_OUT_OF_MEMORY;
    return nullptr;
  }
  gRealtimeMaterializationHashStub->reset(tSimpleHashInit);
  SSHashObj* pHash = tSimpleHashInit(capacity, hashFn);
  gRealtimeMaterializationHashStub->set(tSimpleHashInit, failRealtimeMaterializationRangeHash);
  return pHash;
}

class NestedHistoryHarness;
static NestedHistoryHarness* gNestedHistoryHarness = nullptr;

