  bool virtualHistoryPullContractOk() const {
    bool dataPathStarted = false;
    for (const auto& attempt : attempts_) {
      const auto& request = attempt.request.value().base;
      if (request.sessionId != kHistorySession) continue;
      dataPathStarted = dataPathStarted || request.type == STRIGGER_PULL_TSDB_META;
      if (!dataPathStarted) continue;
      if (attempt.ahandleParamType != STRIGGER_AHANDLE_PARAM_PULL_REQUEST) return false;
      switch (request.type) {
        case STRIGGER_PULL_TSDB_META:
        case STRIGGER_PULL_TSDB_META_NEXT:
        case STRIGGER_PULL_TSDB_DATA:
        case STRIGGER_PULL_TSDB_DATA_NEXT:
          break;
        default:
          return false;
      }
    }
    return dataPathStarted;
  }

