  const SStreamNestedPendingCalcEvent* pendingNestedEvent(int32_t index) const {
    SSTriggerHistoryGroup* pGroup = const_cast<NestedHistoryHarness*>(this)->historyGroup();
    if (pGroup == nullptr || index < 0) return nullptr;
    SListIter iter = {};
    tdListInitIter(&pGroup->pendingNestedEvents, &iter, TD_LIST_FORWARD);
    SListNode* pNode = nullptr;
    for (int32_t i = 0; i <= index; ++i) {
      pNode = tdListNext(&iter);
      if (pNode == nullptr) return nullptr;
    }
    return reinterpret_cast<const SStreamNestedPendingCalcEvent*>(pNode->data);
  }

