TEST_F(StreamNestedHistoryEffectsTest, NotifyHistoryPolicyMatchesExistingSingleWindow) {
  struct PolicyCase {
    bool calcMask;
    bool notifyHistory;
    bool notifyMask;
  };
  const PolicyCase cases[] = {
      {false, false, false}, {false, false, true}, {false, true, false}, {false, true, true},
      {true, false, false},  {true, false, true},  {true, true, false},  {true, true, true},
  };

  for (const PolicyCase& policy : cases) {
    SCOPED_TRACE(::testing::Message() << "calc=" << policy.calcMask << " history=" << policy.notifyHistory
                                      << " notify=" << policy.notifyMask);
    NestedHistoryHarness harness;
    prepareNestedHistoryEffects(harness, policy.calcMask ? STRIGGER_EVENT_WINDOW_CLOSE : STRIGGER_EVENT_WINDOW_NONE,
                                policy.notifyMask ? STRIGGER_EVENT_WINDOW_CLOSE : STRIGGER_EVENT_WINDOW_NONE,
                                policy.notifyHistory);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1000}, {10, 20}));

    const bool doNotify = policy.notifyHistory && policy.notifyMask;
    expectNestedHistoryEffects(harness, 0, policy.calcMask ? 1 : 0,
                               policy.calcMask && doNotify ? STRIGGER_EVENT_WINDOW_CLOSE : STRIGGER_EVENT_WINDOW_NONE,
                               !policy.calcMask && doNotify ? 1 : 0, 0);
  }
}

TEST_F(StreamNestedHistoryEffectsTest, RecalcNotifyHistoryPolicyMatchesExistingSingleWindow) {
  for (bool notifyHistory : {false, true}) {
    SCOPED_TRACE(::testing::Message() << "notifyHistory=" << notifyHistory);
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionCount, {1000, 1000},
                                  NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep);
    ASSERT_TRUE(
        harness.setHistoryEffectPolicy(STRIGGER_EVENT_WINDOW_CLOSE, STRIGGER_EVENT_WINDOW_CLOSE, notifyHistory));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetaAt(1000, NestedHistoryHarness::kTableUid, 2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1000}, {10, 20}));
    EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcDataRows({1000, 1000}, {10, 20}));

    PipelineCalcAttempt* pAttempt = harness.calcAttempt(0);
    ASSERT_NE(nullptr, pAttempt);
    ASSERT_NE(nullptr, pAttempt->decoded.params);
    const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pAttempt->decoded.params, 0));
    ASSERT_NE(nullptr, pParam);
    EXPECT_EQ(notifyHistory ? STRIGGER_EVENT_WINDOW_CLOSE : STRIGGER_EVENT_WINDOW_NONE, pParam->notifyType);

    EXPECT_TRUE(gNestedOutboxPayloads.empty());
  }
}

