TEST_F(StreamNestedHistoryRangeTest, CalcPredicateMatchesLegacyForEachLeafType) {
  const TSKEY longScanEnd = NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep;
  {
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionCount, {1002, 1002}, longScanEnd, false);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetaAt(1000, NestedHistoryHarness::kTableUid, 2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1001}, {1, 1}));
    ASSERT_NE(nullptr, harness.historyGroup());
    EXPECT_EQ(0, listNEles(&harness.historyGroup()->pendingNestedEvents));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    EXPECT_EQ(0, harness.calcAttemptCount());
  }
  {
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionSession, {1010, 1010}, longScanEnd, false);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1020, NestedHistoryHarness::kTableUid, 2}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1020}, {1, 1}));
    ASSERT_NE(nullptr, harness.historyGroup());
    EXPECT_EQ(0, listNEles(&harness.historyGroup()->pendingNestedEvents));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    EXPECT_EQ(1, harness.calcAttemptCount());
  }
  {
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionState, {1002, 1002}, longScanEnd, false);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetaAt(1000, NestedHistoryHarness::kTableUid, 2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1001}, {1, 2}));
    ASSERT_NE(nullptr, harness.historyGroup());
    EXPECT_EQ(0, listNEles(&harness.historyGroup()->pendingNestedEvents));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    EXPECT_EQ(1, harness.calcAttemptCount());
  }
  {
    NestedHistoryHarness harness;
    startNestedHistoryRangeRecalc(harness, NestedHistoryPlan::SessionEvent, {1002, 1002}, longScanEnd, false);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetaAt(1000, NestedHistoryHarness::kTableUid, 2));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPipelineRows({{1000, false, 1, 1, 0}, {1001, false, 1, 0, 1}}));
    ASSERT_NE(nullptr, harness.historyGroup());
    EXPECT_EQ(0, listNEles(&harness.historyGroup()->pendingNestedEvents));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
    EXPECT_EQ(0, harness.calcAttemptCount());
  }
}

