static std::vector<col_id_t> copyVirtualDataCids(const CapturedPullAttempt& attempt) {
  std::vector<col_id_t> result;
  const SArray*         pCids = attempt.request.value().tsdbDataReq.cids;
  for (int32_t i = 0; i < taosArrayGetSize(pCids); ++i) {
    result.push_back(*static_cast<const col_id_t*>(taosArrayGet(pCids, i)));
  }
  return result;
}

static std::vector<std::pair<int32_t, int64_t>> snapshotVirtualReaders(NestedHistoryHarness& harness) {
  std::vector<std::pair<int32_t, int64_t>> result;
  for (int32_t i = 0; i < taosArrayGetSize(harness.task()->readerList); ++i) {
    const auto* pReader = static_cast<const SStreamTaskAddr*>(taosArrayGet(harness.task()->readerList, i));
    if (pReader != nullptr) result.emplace_back(pReader->nodeId, pReader->taskId);
  }
  return result;
}

static std::vector<std::string> snapshotVirtualReaderEndpoints(NestedHistoryHarness& harness) {
  std::vector<std::string> result;
  for (int32_t i = 0; i < taosArrayGetSize(harness.task()->readerList); ++i) {
    const auto* pReader = static_cast<const SStreamTaskAddr*>(taosArrayGet(harness.task()->readerList, i));
    if (pReader == nullptr) continue;
    std::string value = std::to_string(pReader->nodeId) + ":" + std::to_string(pReader->taskId) + ":" +
                        std::to_string(pReader->epset.inUse) + ":" + std::to_string(pReader->epset.numOfEps);
    for (int32_t ep = 0; ep < pReader->epset.numOfEps; ++ep) {
      value += ":" + std::string(pReader->epset.eps[ep].fqdn) + ":" + std::to_string(pReader->epset.eps[ep].port);
    }
    result.push_back(std::move(value));
  }
  return result;
}

static bool virtualEndpointMatches(const SEpSet& endpoint, const char* pFqdn, uint16_t port) {
  for (int32_t i = 0; i < endpoint.numOfEps; ++i) {
    if (strcmp(endpoint.eps[i].fqdn, pFqdn) == 0 && endpoint.eps[i].port == port) return true;
  }
  return false;
}

static std::vector<uint64_t> snapshotVirtualMappings(NestedHistoryHarness& harness) {
  std::vector<uint64_t>  result;
  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  if (pGroup == nullptr || pGroup->pVirtTableInfos == nullptr) return result;
  for (int32_t i = 0; i < taosArrayGetSize(pGroup->pVirtTableInfos); ++i) {
    auto* pInfo = static_cast<SSTriggerVirtTableInfo*>(taosArrayGetP(pGroup->pVirtTableInfos, i));
    if (pInfo == nullptr) continue;
    result.push_back(reinterpret_cast<uintptr_t>(pInfo));
    result.push_back(static_cast<uint64_t>(pInfo->tbUid));
    result.push_back(static_cast<uint64_t>(pInfo->tbVer));
    result.push_back(static_cast<uint64_t>(pInfo->vgId));
    result.push_back(reinterpret_cast<uintptr_t>(pInfo->pTrigColRefs));
    result.push_back(static_cast<uint64_t>(taosArrayGetSize(pInfo->pTrigColRefs)));
    for (int32_t refIndex = 0; refIndex < taosArrayGetSize(pInfo->pTrigColRefs); ++refIndex) {
      const auto* pRef = static_cast<const SSTriggerTableColRef*>(taosArrayGet(pInfo->pTrigColRefs, refIndex));
      if (pRef == nullptr) continue;
      result.push_back(static_cast<uint64_t>(pRef->otbSuid));
      result.push_back(static_cast<uint64_t>(pRef->otbUid));
      result.push_back(static_cast<uint64_t>(pRef->otbVgId));
      result.push_back(reinterpret_cast<uintptr_t>(pRef->pColMatches));
      result.push_back(static_cast<uint64_t>(taosArrayGetSize(pRef->pColMatches)));
      for (int32_t matchIndex = 0; matchIndex < taosArrayGetSize(pRef->pColMatches); ++matchIndex) {
        const auto* pMatch = static_cast<const SSTriggerColMatch*>(taosArrayGet(pRef->pColMatches, matchIndex));
        if (pMatch == nullptr) continue;
        result.push_back(static_cast<uint64_t>(pMatch->otbColId));
        result.push_back(static_cast<uint64_t>(pMatch->vtbSlotId));
      }
    }
  }
  return result;
}

static int32_t finishVirtualDataRound(NestedHistoryHarness& harness, int32_t remainingSources = 2) {
  for (int32_t source = 0; source < remainingSources; ++source) {
    CapturedPullAttempt* pAttempt = harness.findVirtualDataPull();
    if (pAttempt == nullptr) return TSDB_CODE_INTERNAL_ERROR;
    const int64_t uid = pAttempt->request.value().tsdbDataReq.uid;
    const TSKEY   timestamp = uid == NestedHistoryHarness::kPhysicalUidA ? NestedHistoryHarness::kScanStart
                                                                         : NestedHistoryHarness::kScanStart + 1;
    const int32_t value = uid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202;
    int32_t       code = harness.respondVirtualRows(*pAttempt, timestamp, value);
    if (code != TSDB_CODE_SUCCESS) return code;
  }
  return TSDB_CODE_SUCCESS;
}

TEST_F(StreamNestedHistoryVirtualTest, WaitsForExistingDiscoveryReadiness) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startVirtualDiscovery());
  EXPECT_EQ(2, harness.pullAttemptCount(STRIGGER_PULL_VTABLE_INFO, NestedHistoryHarness::kRealtimeSession, true));
  EXPECT_EQ(nullptr, harness.historyContext());
  EXPECT_EQ(0, harness.pullAttemptCount(STRIGGER_PULL_FIRST_TS, NestedHistoryHarness::kHistorySession));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondOneVirtualTableInfo());
  EXPECT_EQ(nullptr, harness.pendingMgmtRequest());
  EXPECT_EQ(nullptr, harness.historyContext());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondOneVirtualTableInfo());
  ASSERT_NE(nullptr, harness.pendingMgmtRequest());
  EXPECT_EQ(nullptr, harness.historyContext());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMgmtReaders());
  EXPECT_EQ(4, harness.readerCount());
  EXPECT_EQ(nullptr, harness.historyContext());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllOriginalTableInfo());
  ASSERT_EQ(4, harness.pullAttemptCount(STRIGGER_PULL_SET_TABLE, NestedHistoryHarness::kRealtimeSession, true));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondNextEmpty(STRIGGER_PULL_SET_TABLE, NestedHistoryHarness::kRealtimeSession));
  EXPECT_FALSE(harness.task()->virTableInfoReady);
  EXPECT_EQ(nullptr, harness.historyContext());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllSetTable());
  EXPECT_TRUE(harness.task()->virTableInfoReady);
  EXPECT_EQ(-1, atomic_load_64(&harness.task()->waitingMgmtReqId));
  EXPECT_EQ(nullptr, harness.pendingMgmtRequest());
  EXPECT_EQ(nullptr, harness.historyContext());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualLastTs());
  ASSERT_NE(nullptr, harness.historyContext());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                {{NestedHistoryHarness::kScanStart, NestedHistoryHarness::kScanStart,
                                                  NestedHistoryHarness::kPhysicalUidA, 1}}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(
                                   NestedHistoryHarness::kOriginalReaderTaskB,
                                   {{NestedHistoryHarness::kScanStart + 1, NestedHistoryHarness::kScanStart + 1,
                                     NestedHistoryHarness::kPhysicalUidB, 1}}));
  ASSERT_NE(nullptr, harness.findVirtualDataPull());
}

TEST_F(StreamNestedHistoryVirtualTest, OneExistingMergerPerLogicalTable) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
  ExistingMergerProbe probe;

  const int32_t metaCode = harness.driveVirtualHistoryToMeta();
  const auto    sourceMergers = probe.uniqueMergers(ExistingMergerCall::SetMergeInfo);
  EXPECT_EQ(2U, sourceMergers.size());
  ASSERT_EQ(TSDB_CODE_SUCCESS, metaCode);
  ASSERT_EQ(TSDB_CODE_SUCCESS, finishVirtualDataRound(harness));

  ASSERT_EQ(2U, sourceMergers.size());
  EXPECT_NE(sourceMergers[0], sourceMergers[1]);
  for (SSTriggerVtableMerger* pMerger : sourceMergers) {
    EXPECT_EQ(1, probe.count(ExistingMergerCall::Init, pMerger));
    EXPECT_EQ(1, probe.count(ExistingMergerCall::SetMergeInfo, pMerger));
    EXPECT_EQ(1, probe.count(ExistingMergerCall::SetMetaDatas, pMerger));
    EXPECT_GE(probe.count(ExistingMergerCall::NextDataBlock, pMerger), 2);
    EXPECT_EQ(1, probe.count(ExistingMergerCall::BindDataBlock, pMerger));
    EXPECT_EQ(1, probe.count(ExistingMergerCall::Destroy, pMerger));
  }
  EXPECT_EQ(nullptr, harness.historyGroup()->pPeerMerger);
  EXPECT_EQ(nullptr, harness.historyGroup()->pNestedPeerSources);
}

