TEST_F(StreamNestedHistoryVirtualTest, ResponseBindsRequestingLogicalSource) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
  ExistingMergerProbe probe;

  const int32_t        metaCode = harness.driveVirtualHistoryToMeta();
  CapturedPullAttempt* pFirst = harness.findVirtualDataPull();
  ASSERT_NE(nullptr, pFirst);
  ASSERT_EQ(TSDB_CODE_SUCCESS, metaCode);
  const uintptr_t firstRequestAddress = NestedHistoryHarness::requestAddress(*pFirst);
  const int64_t   firstPhysicalUid = pFirst->request.value().tsdbDataReq.uid;
  auto*           pFirstMerger = probe.lastMerger(ExistingMergerCall::GetMetaToFetch);
  ASSERT_NE(0U, firstRequestAddress);
  EXPECT_EQ(STRIGGER_AHANDLE_PARAM_PULL_REQUEST, pFirst->ahandleParamType);
  ASSERT_NE(nullptr, pFirstMerger);
  const TSKEY firstTs = firstPhysicalUid == NestedHistoryHarness::kPhysicalUidA ? NestedHistoryHarness::kScanStart
                                                                                : NestedHistoryHarness::kScanStart + 1;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualRows(*pFirst, firstTs,
                                       firstPhysicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202));
  EXPECT_EQ(1, probe.count(ExistingMergerCall::BindDataBlock, pFirstMerger));
  EXPECT_TRUE(probe.calledBefore(ExistingMergerCall::GetMetaToFetch, ExistingMergerCall::BindDataBlock, pFirstMerger));

  CapturedPullAttempt* pSecond = harness.findVirtualDataPull();
  ASSERT_NE(nullptr, pSecond);
  const uintptr_t secondRequestAddress = NestedHistoryHarness::requestAddress(*pSecond);
  const int64_t   secondPhysicalUid = pSecond->request.value().tsdbDataReq.uid;
  auto*           pSecondMerger = probe.lastMerger(ExistingMergerCall::GetMetaToFetch);
  ASSERT_NE(nullptr, pSecondMerger);
  EXPECT_EQ(STRIGGER_AHANDLE_PARAM_PULL_REQUEST, pSecond->ahandleParamType);
  EXPECT_NE(firstRequestAddress, secondRequestAddress);
  EXPECT_NE(pFirstMerger, pSecondMerger);
  EXPECT_EQ(0, probe.count(ExistingMergerCall::BindDataBlock, pSecondMerger));
  const TSKEY secondTs = secondPhysicalUid == NestedHistoryHarness::kPhysicalUidA
                             ? NestedHistoryHarness::kScanStart
                             : NestedHistoryHarness::kScanStart + 1;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualRows(*pSecond, secondTs,
                                       secondPhysicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202));
  EXPECT_EQ(1, probe.count(ExistingMergerCall::BindDataBlock, pSecondMerger));
  EXPECT_TRUE(probe.calledBefore(ExistingMergerCall::GetMetaToFetch, ExistingMergerCall::BindDataBlock, pSecondMerger));

  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  SStreamCacheScope              scope = {.gid = pEvent->leafIdentity.gid,
                                          .lineage = {.pScopes = pEvent->leafIdentity.lineage.pScopes}};
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  std::sort(rows.begin(), rows.end(), observedScopedRowLess);
  EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                            {NestedHistoryHarness::kVirtualUidB, 202}}),
            rows);
  EXPECT_TRUE(harness.virtualHistoryPullContractOk());
}

