  const int64_t firstUid = pFirstAttempt->request.value().tsdbTsDataReq.uid;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(firstUid, {1000, 1002}, {10, 11}));
  ASSERT_NE(nullptr, harness.historyGroup());
