TEST_F(StreamNestedHistoryPeerTest, AllSourcesRegisteredBeforeFirstNext) {
  {
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(
                                     NestedHistoryHarness::kOriginalReaderTaskA,
                                     {{NestedHistoryHarness::kScanStart, NestedHistoryHarness::kScanStart,
                                       NestedHistoryHarness::kPhysicalUidA, 1},
                                      {NestedHistoryHarness::kScanStart + 1, NestedHistoryHarness::kScanStart + 1,
                                       NestedHistoryHarness::kPhysicalUidA, 1}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {}));

    EXPECT_EQ(1, registrationProbe.get().firstNextSourceCount);
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA}), registrationProbe.get().addedTableUids);

    CapturedPullAttempt* pFirstData = harness.findVirtualDataPull(NestedHistoryHarness::kPhysicalUidA);
    ASSERT_NE(nullptr, pFirstData);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pFirstData, NestedHistoryHarness::kScanStart, 101));
    CapturedPullAttempt* pSecondData = harness.findVirtualDataPull(NestedHistoryHarness::kPhysicalUidA);
    ASSERT_NE(nullptr, pSecondData);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pSecondData, NestedHistoryHarness::kScanStart + 1, 102));

    const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
    ASSERT_NE(nullptr, pEvent);
    EXPECT_EQ(2, pEvent->calcParam.wrownum);
    ASSERT_NE(nullptr, pEvent->pSnapshots);
    ASSERT_EQ(1, taosArrayGetSize(pEvent->pSnapshots));
    const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
    ASSERT_NE(nullptr, pSnapshot);
    EXPECT_EQ(2, pSnapshot->values.window.rownum);

    SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
    std::vector<ObservedScopedRow> rows;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
    std::sort(rows.begin(), rows.end(), observedScopedRowLess);
    EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                              {NestedHistoryHarness::kVirtualUidA, 102}}),
              rows);
  }

  for (bool lowerEquality : {true, false}) {
    SCOPED_TRACE(lowerEquality ? "lower-bound equality" : "upper-bound equality");
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual(NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep, true));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    STimeWindow range = {};
    ASSERT_TRUE(harness.pendingMetaRange(&range));
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                  {{range.skey, range.skey, NestedHistoryHarness::kPhysicalUidA, 0}}));
    const NestedHistoryMetaRow equalityMeta =
        lowerEquality ? NestedHistoryMetaRow{range.skey - 1, range.skey, NestedHistoryHarness::kPhysicalUidB, 1}
                      : NestedHistoryMetaRow{range.ekey, range.ekey + 1, NestedHistoryHarness::kPhysicalUidB, 1};
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {equalityMeta}));

    ASSERT_EQ(1U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA}), registrationProbe.get().roundTableUids[0]);
  }
}

