TEST_F(StreamNestedHistoryEquivalenceTest, PermutingSourcesPreservesIdentitySnapshotAndRows) {
  auto runScenario = [](bool reverseLogicalOrder, bool secondSourceOnNextPage, CanonicalNestedObservation* pObservation,
                        std::vector<NestedHistoryPeerSubmitRecord>* pSubmits, std::vector<int64_t>* pRegistrationOrder,
                        std::array<int32_t, 3>* pMergerCounts) {
    ExistingMergerProbe  mergerProbe;
    NestedHistoryHarness harness;
    if (!harness.deployVirtual()) return TSDB_CODE_INTERNAL_ERROR;
    int32_t code = harness.driveVirtualDiscovery(reverseLogicalOrder);
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.startHistoryRequest();
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.respondAllVirtualFirstTs();
    if (code != TSDB_CODE_SUCCESS) return code;
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

    code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {});
    if (code != TSDB_CODE_SUCCESS) return code;
    code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {});
    if (code != TSDB_CODE_SUCCESS) return code;
    if (!secondSourceOnNextPage) {
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                 {{1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1}});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                 {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}});
    } else {
      std::vector<NestedHistoryMetaRow> firstPage;
      firstPage.reserve(STREAM_RETURN_ROWS_NUM);
      firstPage.push_back({1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1});
      for (int32_t row = 1; row < STREAM_RETURN_ROWS_NUM; ++row) {
        firstPage.push_back({1000, 1000, 900000 + row, 1});
      }
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA, firstPage);
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskA, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskB, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskA, {});
      if (code != TSDB_CODE_SUCCESS) return code;
      code = harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                     {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}});
    }
    if (code != TSDB_CODE_SUCCESS) return code;

    for (int32_t source = 0; source < 2; ++source) {
      CapturedPullAttempt* pData = harness.findVirtualDataPull();
      if (pData == nullptr) return TSDB_CODE_INTERNAL_ERROR;
      const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
      code = harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202);
      if (code != TSDB_CODE_SUCCESS) return code;
    }

    if (!captureHistoryCanonicalObservation(harness, pObservation)) return TSDB_CODE_INTERNAL_ERROR;
    *pSubmits = registrationProbe.get().submits;
    if (registrationProbe.get().roundTableUids.size() != 1) return TSDB_CODE_INTERNAL_ERROR;
    *pRegistrationOrder = registrationProbe.get().roundTableUids[0];
    *pMergerCounts = {{mergerProbe.count(ExistingMergerCall::SetMergeInfo),
                       mergerProbe.count(ExistingMergerCall::GetMetaToFetch),
                       mergerProbe.count(ExistingMergerCall::BindDataBlock)}};
    return TSDB_CODE_SUCCESS;
  };

  CanonicalNestedObservation                 baseline;
  std::vector<NestedHistoryPeerSubmitRecord> baselineSubmits;
  std::vector<int64_t>                       baselineRegistration;
  std::array<int32_t, 3>                     baselineMergerCounts = {};
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            runScenario(false, false, &baseline, &baselineSubmits, &baselineRegistration, &baselineMergerCounts));
  EXPECT_EQ(1000, baseline.wstart);
  EXPECT_EQ(1000, baseline.wend);
  EXPECT_EQ(2, baseline.wrownum);
  ASSERT_EQ(1U, baseline.snapshots.size());
  EXPECT_EQ(1000, baseline.snapshots[0][3]);
  EXPECT_EQ(1000, baseline.snapshots[0][4]);
  EXPECT_EQ(2, baseline.snapshots[0][6]);
  EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                            {NestedHistoryHarness::kVirtualUidB, 202}}),
            baseline.rows);
  EXPECT_GT(baseline.triggerTime, 0);
  for (int32_t count : baselineMergerCounts) EXPECT_GT(count, 0);
  ASSERT_EQ(1U, baselineSubmits.size());
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB}),
            baselineSubmits[0].tableUids);
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB, NestedHistoryHarness::kVirtualUidA}),
            baselineRegistration);

  for (bool reverseLogicalOrder : {false, true}) {
    for (bool secondSourceOnNextPage : {false, true}) {
      if (!reverseLogicalOrder && !secondSourceOnNextPage) continue;
      CanonicalNestedObservation                 observation;
      std::vector<NestedHistoryPeerSubmitRecord> submits;
      std::vector<int64_t>                       registrationOrder;
      std::array<int32_t, 3>                     mergerCounts = {};
      ASSERT_EQ(TSDB_CODE_SUCCESS, runScenario(reverseLogicalOrder, secondSourceOnNextPage, &observation, &submits,
                                               &registrationOrder, &mergerCounts));
      EXPECT_EQ(reverseLogicalOrder
                    ? (std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB})
                    : (std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB, NestedHistoryHarness::kVirtualUidA}),
                registrationOrder);
      expectCanonicalNestedObservationEqual(baseline, observation);
      EXPECT_GT(observation.triggerTime, 0);
      EXPECT_EQ(baselineSubmits, submits);
      EXPECT_EQ(baselineMergerCounts, mergerCounts);
    }
  }
}

TEST_F(StreamNestedHistoryPeerTest, LateAddSourceFailsBeforeChainMutation) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
  ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  std::vector<NestedHistoryMetaRow> firstPage;
  firstPage.reserve(STREAM_RETURN_ROWS_NUM);
  firstPage.push_back({1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1});
  for (int32_t row = 1; row < STREAM_RETURN_ROWS_NUM; ++row) {
    firstPage.push_back({1000, 1000, 910000 + row, 1});
  }
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA, firstPage));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskA, {}));

  EXPECT_TRUE(registrationProbe.get().addedTableUids.empty());
  EXPECT_EQ(0, registrationProbe.get().nextCalls);
  EXPECT_EQ(nullptr, harness.findVirtualDataPull());
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));

  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaNextForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                    {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}}));
  EXPECT_FALSE(registrationProbe.get().addAfterNext);
  EXPECT_EQ(2, registrationProbe.get().firstNextSourceCount);

  SSTriggerHistoryGroup* pGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, registrationProbe.get().pStartedMerger);
  ASSERT_EQ(registrationProbe.get().pStartedMerger, pGroup->pPeerMerger);
  SWindowChainState*                pChainBefore = pGroup->pWindowChain;
  const int32_t                     sourcesBefore = taosArrayGetSize(pGroup->pNestedPeerSources);
  const int32_t                     eventsBefore = listNEles(&pGroup->pendingNestedEvents);
  const auto                        submitsBefore = registrationProbe.get().submits;
  int32_t                           dummySource = 0;
  SStreamTriggerPeerSourceOps       lateOps = {};
  lateOps.peek = nestedHistoryLateSourcePeek;
  lateOps.consume = nestedHistoryLateSourceConsume;
  EXPECT_EQ(TSDB_CODE_INVALID_PARA,
            stTriggerMergerPeerAddSource(registrationProbe.get().pStartedMerger, 999999, &lateOps, &dummySource));
  EXPECT_EQ(pChainBefore, pGroup->pWindowChain);
  EXPECT_EQ(sourcesBefore, taosArrayGetSize(pGroup->pNestedPeerSources));
  EXPECT_EQ(eventsBefore, listNEles(&pGroup->pendingNestedEvents));
  EXPECT_EQ(submitsBefore, registrationProbe.get().submits);
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));

  for (int32_t source = 0; source < 2; ++source) {
    CapturedPullAttempt* pData = harness.findVirtualDataPull();
    ASSERT_NE(nullptr, pData);
    const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202));
  }
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  EXPECT_EQ(2, pEvent->calcParam.wrownum);
  ASSERT_NE(nullptr, pEvent->pSnapshots);
  const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
  ASSERT_NE(nullptr, pSnapshot);
  EXPECT_EQ(2, pSnapshot->values.window.rownum);
  ASSERT_EQ(1U, registrationProbe.get().submits.size());
  EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA, NestedHistoryHarness::kVirtualUidB}),
            registrationProbe.get().submits[0].tableUids);
  SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  std::sort(rows.begin(), rows.end(), observedScopedRowLess);
  EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidA, 101},
                                            {NestedHistoryHarness::kVirtualUidB, 202}}),
            rows);
}

TEST_F(StreamNestedHistoryPeerTest, ReaderFanoutCompletesBeforeSourceRegistry) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deployVirtual());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
  ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                {{1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1}}));
  EXPECT_TRUE(registrationProbe.get().addedTableUids.empty());
  EXPECT_EQ(0, registrationProbe.get().nextCalls);
  EXPECT_EQ(nullptr, harness.findVirtualDataPull());
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));

  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB,
                                                {{1000, 1000, NestedHistoryHarness::kPhysicalUidB, 1}}));
  EXPECT_EQ(2, registrationProbe.get().firstNextSourceCount);
  EXPECT_FALSE(registrationProbe.get().addAfterNext);

  for (int32_t source = 0; source < 2; ++source) {
    CapturedPullAttempt* pData = harness.findVirtualDataPull();
    ASSERT_NE(nullptr, pData);
    const int64_t physicalUid = pData->request.value().tsdbDataReq.uid;
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualRows(*pData, 1000, physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202));
  }
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  EXPECT_EQ(2, pEvent->calcParam.wrownum);
  ASSERT_NE(nullptr, pEvent->pSnapshots);
  const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
  ASSERT_NE(nullptr, pSnapshot);
  EXPECT_EQ(2, pSnapshot->values.window.rownum);
}

TEST_F(StreamNestedHistoryPeerTest, LaterStepMayIntroduceNormalSource) {
  constexpr int64_t laterTableUid = 5000;
  {
    NestedHistoryHarness                     harness;
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;
    ASSERT_TRUE(harness.deploy(NestedHistoryPlan::SessionCount, 0,
                               NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                       {1001, 1001, NestedHistoryHarness::kTableUid, 1}}));
    for (int32_t page = 0; page < 2; ++page) {
      CapturedPullAttempt* pData = harness.findDataPull(NestedHistoryHarness::kTableUid);
      ASSERT_NE(nullptr, pData);
      ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(NestedHistoryHarness::kTableUid, {1000 + page}, {10 + page}));
    }
    ASSERT_NE(nullptr, harness.pendingNestedEvent(0));
    ASSERT_EQ(1U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kTableUid}), registrationProbe.get().roundTableUids[0]);

    STimeWindow secondRange = {};
    ASSERT_TRUE(harness.pendingMetaRange(&secondRange));
    ASSERT_GT(secondRange.skey, 1001);
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondMetas({{secondRange.skey, secondRange.skey, laterTableUid, 1},
                                    {secondRange.skey + 1, secondRange.skey + 1, laterTableUid, 1}}));
    ASSERT_EQ(2U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{laterTableUid}), registrationProbe.get().roundTableUids[1]);
    for (int32_t page = 0; page < 2; ++page) {
      CapturedPullAttempt* pData = harness.findDataPull(laterTableUid);
      ASSERT_NE(nullptr, pData);
      ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(laterTableUid, {secondRange.skey + page}, {50 + page}));
    }

    SSTriggerHistoryGroup* pGroup = harness.historyGroup();
    ASSERT_NE(nullptr, pGroup);
    ASSERT_GE(listNEles(&pGroup->pendingNestedEvents), 2);
    const SStreamNestedPendingCalcEvent* pEvent =
        harness.pendingNestedEvent(listNEles(&pGroup->pendingNestedEvents) - 1);
    ASSERT_NE(nullptr, pEvent);
    EXPECT_EQ(2, pEvent->calcParam.wrownum);
    ASSERT_NE(nullptr, pEvent->pSnapshots);
    const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
    ASSERT_NE(nullptr, pSnapshot);
    EXPECT_EQ(2, pSnapshot->values.window.rownum);
    SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
    std::vector<ObservedScopedRow> rows;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
    EXPECT_TRUE(rows.empty());
  }

  {
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual(NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    const auto readersBefore = snapshotVirtualReaders(harness);
    const auto endpointsBefore = snapshotVirtualReaderEndpoints(harness);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    const auto mappingsBefore = snapshotVirtualMappings(harness);
    ASSERT_FALSE(mappingsBefore.empty());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                  {{1000, 1000, NestedHistoryHarness::kPhysicalUidA, 1},
                                                   {1001, 1001, NestedHistoryHarness::kPhysicalUidA, 1}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskB, {}));
    ASSERT_EQ(1U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidA}), registrationProbe.get().roundTableUids[0]);
    for (int32_t row = 0; row < 2; ++row) {
      CapturedPullAttempt* pData = harness.findVirtualDataPull(NestedHistoryHarness::kPhysicalUidA);
      ASSERT_NE(nullptr, pData);
      ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pData, 1000 + row, 101 + row));
    }

    STimeWindow secondRange = {};
    ASSERT_TRUE(harness.pendingMetaRange(&secondRange));
    ASSERT_GT(secondRange.skey, 1001);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA,
                                                  {{secondRange.skey, secondRange.skey, 999999, 1}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(
                  NestedHistoryHarness::kOriginalReaderTaskB,
                  {{secondRange.skey, secondRange.skey, NestedHistoryHarness::kPhysicalUidB, 1},
                   {secondRange.skey + 1, secondRange.skey + 1, NestedHistoryHarness::kPhysicalUidB, 1}}));
    ASSERT_EQ(2U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB}), registrationProbe.get().roundTableUids[1]);
    EXPECT_EQ(nullptr, harness.findVirtualDataPull(999999));
    for (int32_t row = 0; row < 2; ++row) {
      CapturedPullAttempt* pData = harness.findVirtualDataPull(NestedHistoryHarness::kPhysicalUidB);
      ASSERT_NE(nullptr, pData);
      ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pData, secondRange.skey + row, 201 + row));
    }

    EXPECT_EQ(readersBefore, snapshotVirtualReaders(harness));
    EXPECT_EQ(endpointsBefore, snapshotVirtualReaderEndpoints(harness));
    EXPECT_EQ(mappingsBefore, snapshotVirtualMappings(harness));
    EXPECT_EQ(nullptr, harness.pendingMgmtRequest());
    const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(1);
    ASSERT_NE(nullptr, pEvent);
    EXPECT_EQ(2, pEvent->calcParam.wrownum);
    SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
    std::vector<ObservedScopedRow> rows;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
    std::sort(rows.begin(), rows.end(), observedScopedRowLess);
    EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidB, 201},
                                              {NestedHistoryHarness::kVirtualUidB, 202}}),
              rows);
  }

  {
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual(NestedHistoryHarness::kScanStart + 2 * NestedHistoryHarness::kHistoryStep));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    const auto readersBefore = snapshotVirtualReaders(harness);
    const auto endpointsBefore = snapshotVirtualReaderEndpoints(harness);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    const auto mappingsBefore = snapshotVirtualMappings(harness);
    ASSERT_FALSE(mappingsBefore.empty());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondAllVirtualFirstTs());
    SSTriggerHistoryGroup* pGroup = harness.historyGroup();
    ASSERT_NE(nullptr, pGroup);
    SWindowChainState* pChainBefore = pGroup->pWindowChain;
    STimeWindow        firstRange = {};
    ASSERT_TRUE(harness.pendingMetaRange(&firstRange));
    ScopedNestedHistoryPeerRegistrationProbe registrationProbe;

    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(
                                     NestedHistoryHarness::kOriginalReaderTaskA,
                                     {{firstRange.skey - 1, firstRange.skey, NestedHistoryHarness::kPhysicalUidA, 0}}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(
                                     NestedHistoryHarness::kOriginalReaderTaskB,
                                     {{firstRange.ekey, firstRange.ekey, NestedHistoryHarness::kPhysicalUidB, 0}}));

    ASSERT_EQ(1U, registrationProbe.get().roundTableUids.size());
    EXPECT_TRUE(registrationProbe.get().roundTableUids[0].empty());
    EXPECT_TRUE(registrationProbe.get().submits.empty());
    EXPECT_EQ(pChainBefore, pGroup->pWindowChain);
    EXPECT_EQ(nullptr, pGroup->pPeerMerger);
    EXPECT_EQ(nullptr, pGroup->pNestedPeerSources);
    EXPECT_EQ(0, listNEles(&pGroup->pendingNestedEvents));
    EXPECT_EQ(nullptr, harness.findVirtualDataPull());
    EXPECT_EQ(readersBefore, snapshotVirtualReaders(harness));
    EXPECT_EQ(endpointsBefore, snapshotVirtualReaderEndpoints(harness));
    EXPECT_EQ(mappingsBefore, snapshotVirtualMappings(harness));
    EXPECT_EQ(nullptr, harness.pendingMgmtRequest());

    STimeWindow secondRange = {};
    ASSERT_TRUE(harness.pendingMetaRange(&secondRange));
    EXPECT_EQ(firstRange.ekey + 1, secondRange.skey);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kPartitionReaderTaskB, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualMetaForReader(NestedHistoryHarness::kOriginalReaderTaskA, {}));
    ASSERT_EQ(TSDB_CODE_SUCCESS,
              harness.respondVirtualMetaForReader(
                  NestedHistoryHarness::kOriginalReaderTaskB,
                  {{secondRange.skey, secondRange.skey, NestedHistoryHarness::kPhysicalUidB, 1},
                   {secondRange.skey + 1, secondRange.skey + 1, NestedHistoryHarness::kPhysicalUidB, 1}}));
    ASSERT_EQ(2U, registrationProbe.get().roundTableUids.size());
    EXPECT_EQ((std::vector<int64_t>{NestedHistoryHarness::kVirtualUidB}), registrationProbe.get().roundTableUids[1]);
    for (int32_t row = 0; row < 2; ++row) {
      CapturedPullAttempt* pData = harness.findVirtualDataPull(NestedHistoryHarness::kPhysicalUidB);
      ASSERT_NE(nullptr, pData);
      ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pData, secondRange.skey + row, 301 + row));
    }
    ASSERT_EQ(2U, registrationProbe.get().submits.size());
    const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
    ASSERT_NE(nullptr, pEvent);
    EXPECT_EQ(secondRange.skey, pEvent->calcParam.wstart);
    EXPECT_EQ(secondRange.skey + 1, pEvent->calcParam.wend);
    EXPECT_EQ(2, pEvent->calcParam.wrownum);
    SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
    std::vector<ObservedScopedRow> rows;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
    std::sort(rows.begin(), rows.end(), observedScopedRowLess);
    EXPECT_EQ((std::vector<ObservedScopedRow>{{NestedHistoryHarness::kVirtualUidB, 301},
                                              {NestedHistoryHarness::kVirtualUidB, 302}}),
              rows);
  }
}

TEST_F(StreamNestedHistoryPeerTest, SourceEofDoesNotEndRound) {
  constexpr int64_t    eofTableUid = 2000;
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, eofTableUid, 1},
                                                     {1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                     {1001, 1001, NestedHistoryHarness::kTableUid, 1}}));

  CapturedPullAttempt* pEofData = harness.pendingDataPull();
  ASSERT_NE(nullptr, pEofData);
  ASSERT_EQ(eofTableUid, pEofData->request.value().tsdbTsDataReq.uid);
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondEmptyRowsFor(eofTableUid));
  EXPECT_EQ(nullptr, harness.pendingNestedEvent(0));
  EXPECT_EQ(0, harness.pullAttemptCount(STRIGGER_PULL_TSDB_META, NestedHistoryHarness::kHistorySession, true));

  for (int32_t page = 0; page < 2; ++page) {
    CapturedPullAttempt* pLiveData = harness.findDataPull(NestedHistoryHarness::kTableUid);
    ASSERT_NE(nullptr, pLiveData);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(NestedHistoryHarness::kTableUid, {1000 + page}, {10 + page}));
  }
  const SStreamNestedPendingCalcEvent* pEvent = harness.pendingNestedEvent(0);
  ASSERT_NE(nullptr, pEvent);
  EXPECT_EQ(1000, pEvent->calcParam.wstart);
  EXPECT_EQ(1001, pEvent->calcParam.wend);
  EXPECT_EQ(2, pEvent->calcParam.wrownum);
  ASSERT_NE(nullptr, pEvent->pSnapshots);
  const auto* pSnapshot = static_cast<const SWindowAncestorSnapshot*>(taosArrayGet(pEvent->pSnapshots, 0));
  ASSERT_NE(nullptr, pSnapshot);
  EXPECT_EQ(2, pSnapshot->values.window.rownum);
  SStreamCacheScope              scope = borrowCacheScope(pEvent->leafIdentity);
  std::vector<ObservedScopedRow> rows;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.readHistoryRows(scope, &rows));
  EXPECT_TRUE(rows.empty());
}

TEST_F(StreamNestedHistoryLifecycleTest, PerSourceOnDemandPullRequestSurvivesRetry) {
  {
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deploy());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                       {1001, 1001, NestedHistoryHarness::kSecondTableUid, 1}}));

    CapturedPullAttempt* pInitialAttempt = harness.pendingDataPull();
    ASSERT_NE(nullptr, pInitialAttempt);
    const uintptr_t requestAddress = NestedHistoryHarness::requestAddress(*pInitialAttempt);
    const int64_t   requestUid = pInitialAttempt->request.value().tsdbTsDataReq.uid;
    ASSERT_NE(0U, requestAddress);
    EXPECT_EQ(TSDB_CODE_RPC_NETWORK_UNAVAIL, harness.respondPullError(*pInitialAttempt, TSDB_CODE_RPC_NETWORK_UNAVAIL));
    ASSERT_NE(nullptr, harness.historyContext());
    ASSERT_EQ(1, listNEles(&harness.historyContext()->retryPullReqs));

    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
    ASSERT_EQ(0, listNEles(&harness.historyContext()->retryPullReqs));
    CapturedPullAttempt* pRetryAttempt = harness.findDataPull(requestUid);
    ASSERT_NE(nullptr, pRetryAttempt);
    EXPECT_EQ(requestAddress, NestedHistoryHarness::requestAddress(*pRetryAttempt));
    EXPECT_EQ(2, harness.dataPullAttemptCount(requestUid));
    const TSKEY requestTs = requestUid == NestedHistoryHarness::kTableUid ? 1000 : 1001;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(requestUid, {requestTs}, {10}));

    CapturedPullAttempt* pOtherAttempt = harness.pendingDataPull();
    ASSERT_NE(nullptr, pOtherAttempt);
    const int64_t otherUid = pOtherAttempt->request.value().tsdbTsDataReq.uid;
    ASSERT_NE(requestUid, otherUid);
    const TSKEY otherTs = otherUid == NestedHistoryHarness::kTableUid ? 1000 : 1001;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRowsFor(otherUid, {otherTs}, {20}));
    EXPECT_EQ(1, listNEles(&harness.historyGroup()->pendingNestedEvents));
  }

  {
    ExistingMergerProbe  probe;
    NestedHistoryHarness harness;
    ASSERT_TRUE(harness.deployVirtual());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualDiscovery());
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.driveVirtualHistoryToMeta());

    CapturedPullAttempt* pInitialAttempt = harness.findVirtualDataPull();
    ASSERT_NE(nullptr, pInitialAttempt);
    const uintptr_t requestAddress = NestedHistoryHarness::requestAddress(*pInitialAttempt);
    const int64_t   physicalUid = pInitialAttempt->request.value().tsdbDataReq.uid;
    ASSERT_NE(0U, requestAddress);
    EXPECT_EQ(TSDB_CODE_RPC_NETWORK_UNAVAIL,
              harness.respondVirtualPullError(*pInitialAttempt, TSDB_CODE_RPC_NETWORK_UNAVAIL));
    ASSERT_EQ(1, listNEles(&harness.historyContext()->retryPullReqs));

    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
    ASSERT_EQ(0, listNEles(&harness.historyContext()->retryPullReqs));
    CapturedPullAttempt* pRetryAttempt = harness.findVirtualDataPull(physicalUid);
    ASSERT_NE(nullptr, pRetryAttempt);
    EXPECT_EQ(requestAddress, NestedHistoryHarness::requestAddress(*pRetryAttempt));
    EXPECT_EQ(2, harness.virtualDataPullAttemptCount(physicalUid));
    const TSKEY   retryTs = physicalUid == NestedHistoryHarness::kPhysicalUidA ? 1000 : 1001;
    const int32_t retryValue = physicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pRetryAttempt, retryTs, retryValue));

    CapturedPullAttempt* pOtherAttempt = harness.findVirtualDataPull();
    ASSERT_NE(nullptr, pOtherAttempt);
    const int64_t otherPhysicalUid = pOtherAttempt->request.value().tsdbDataReq.uid;
    ASSERT_NE(physicalUid, otherPhysicalUid);
    const TSKEY   otherTs = otherPhysicalUid == NestedHistoryHarness::kPhysicalUidA ? 1000 : 1001;
    const int32_t otherValue = otherPhysicalUid == NestedHistoryHarness::kPhysicalUidA ? 101 : 202;
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondVirtualRows(*pOtherAttempt, otherTs, otherValue));
    EXPECT_EQ(1, listNEles(&harness.historyGroup()->pendingNestedEvents));
    EXPECT_GT(probe.count(ExistingMergerCall::GetMetaToFetch), 0);
    EXPECT_GT(probe.count(ExistingMergerCall::BindDataBlock), 0);
  }
}

TEST_F(StreamNestedAllocationFailureTest, AhandleFailureIsFatalWithoutInFlightOwner) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());

  Stub allocStub;
  gNestedHistoryAllocStub = &allocStub;
  gNestedHistoryAhandleAllocFailures = 1;
  gNestedHistoryAhandleAllocCalls = 0;
  allocStub.set(taosMemCalloc, failNestedHistoryAhandleCalloc);
  const int32_t code = harness.respondMetas(
      {{1000, 1000, NestedHistoryHarness::kTableUid, 1}, {1001, 1001, NestedHistoryHarness::kSecondTableUid, 1}});
  allocStub.reset(taosMemCalloc);
  gNestedHistoryAhandleAllocFailures = 0;
  gNestedHistoryAllocStub = nullptr;

  EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, code);
  EXPECT_EQ(1, gNestedHistoryAhandleAllocCalls);
  ASSERT_NE(nullptr, harness.historyContext());
  EXPECT_EQ(nullptr, harness.historyContext()->pCalcReq);
  EXPECT_EQ(0, listNEles(&harness.historyContext()->retryPullReqs));
  EXPECT_EQ(0, harness.pendingDataPullCount());
  expectNestedHistoryFatalProgressUncommitted(harness);
  EXPECT_EQ(0, atomic_load_8(&harness.task()->historyFinished));
}

