TEST_F(StreamNestedAllocationFailureTest, RetryAhandleFailureYieldsWithStableOwner) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMetas({{1000, 1000, NestedHistoryHarness::kTableUid, 1},
                                                     {1001, 1001, NestedHistoryHarness::kSecondTableUid, 1}}));

  CapturedPullAttempt* pInitialAttempt = harness.pendingDataPull();
  ASSERT_NE(nullptr, pInitialAttempt);
  const uintptr_t requestAddress = NestedHistoryHarness::requestAddress(*pInitialAttempt);
  const int64_t   requestUid = pInitialAttempt->request.value().tsdbTsDataReq.uid;
  ASSERT_NE(0U, requestAddress);
  EXPECT_EQ(TSDB_CODE_RPC_NETWORK_UNAVAIL, harness.respondPullError(*pInitialAttempt, TSDB_CODE_RPC_NETWORK_UNAVAIL));
  ASSERT_NE(nullptr, harness.historyContext());
  ASSERT_EQ(1, listNEles(&harness.historyContext()->retryPullReqs));

  Stub allocStub;
  gNestedHistoryAllocStub = &allocStub;
  gNestedHistoryAhandleAllocFailures = 2;
  gNestedHistoryAhandleAllocCalls = 0;
  allocStub.set(taosMemCalloc, failNestedHistoryAhandleCalloc);
  const int32_t retryCode = harness.dispatchSerializedHistoryStart();
  allocStub.reset(taosMemCalloc);
  gNestedHistoryAhandleAllocFailures = 0;
  gNestedHistoryAllocStub = nullptr;

  EXPECT_EQ(TSDB_CODE_OUT_OF_MEMORY, retryCode);
  EXPECT_EQ(1, gNestedHistoryAhandleAllocCalls);
  ASSERT_EQ(1, listNEles(&harness.historyContext()->retryPullReqs));
  SListNode* pRetryNode = listHead(&harness.historyContext()->retryPullReqs);
  ASSERT_NE(nullptr, pRetryNode);
  ASSERT_NE(nullptr, pRetryNode->data);
  EXPECT_EQ(requestAddress, reinterpret_cast<uintptr_t>(*reinterpret_cast<SSTriggerPullRequest**>(pRetryNode->data)));
  EXPECT_EQ(0, harness.pendingDataPullCount());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchSerializedHistoryStart());
  EXPECT_EQ(0, listNEles(&harness.historyContext()->retryPullReqs));
  CapturedPullAttempt* pRetryAttempt = harness.findDataPull(requestUid);
  ASSERT_NE(nullptr, pRetryAttempt);
  EXPECT_EQ(requestAddress, NestedHistoryHarness::requestAddress(*pRetryAttempt));
  EXPECT_EQ(2, harness.dataPullAttemptCount(requestUid));
  ASSERT_EQ(1, harness.pendingDataPullCount());
}

