  EXPECT_EQ(0, harness.pendingControlCount(NestedHistoryHarness::kHistorySession));

  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskAddRecalcRequest(harness.task(), nullptr, nullptr, true, false, false, 0));
