TEST_F(StreamNestedHistoryRecoveryBoundaryTest, CheckpointV3BytesRemainUnchanged) {
  const auto captureCheckpoint = [](bool completeHistory, std::vector<uint8_t>* pBytes) {
    NestedHistoryHarness harness;
    if (!harness.deploy() || harness.startAndCreateHistory() != TSDB_CODE_SUCCESS ||
        harness.respondRealtimeWal(NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep + 1, 7) !=
            TSDB_CODE_SUCCESS) {
      return false;
    }
    if (completeHistory) {
      if (!harness.setHistoryEffectPolicy(STRIGGER_EVENT_WINDOW_NONE, STRIGGER_EVENT_WINDOW_NONE, false) ||
          harness.startHistoryRequest() != TSDB_CODE_SUCCESS || harness.respondFirstTs() != TSDB_CODE_SUCCESS ||
          harness.respondMeta() != TSDB_CODE_SUCCESS ||
          harness.respondRows({1000, 1000}, {10, 20}) != TSDB_CODE_SUCCESS ||
          harness.respondPendingEmptyMetas() != TSDB_CODE_SUCCESS || harness.historyContext() == nullptr ||
          tSimpleHashGetSize(harness.historyContext()->pGroups) != 0) {
        return false;
      }
    }

    SStreamTriggerTask* pTask = harness.task();
    pTask->historyFinished = 1;
    atomic_store_32(&pTask->checkpointVersion, 40);
    tSimpleHashCleanup(pTask->pHistoryCutoffTime);
    pTask->pHistoryCutoffTime = tSimpleHashInit(1, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BIGINT));
    const int64_t fixedCutoff = NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep;
    if (pTask->pHistoryCutoffTime == nullptr ||
        tSimpleHashPut(pTask->pHistoryCutoffTime, &NestedHistoryHarness::kGid, sizeof(NestedHistoryHarness::kGid),
                       &fixedCutoff, sizeof(fixedCutoff)) != TSDB_CODE_SUCCESS) {
      return false;
    }
    int32_t               iter = 0;
    SSTriggerWalProgress* pProgress = static_cast<SSTriggerWalProgress*>(
        tSimpleHashIterate(pTask->pRealtimeContext->pReaderWalProgress, nullptr, &iter));
    if (pProgress == nullptr) return false;
    while (pProgress != nullptr) {
      pProgress->startVer = 2;
      pProgress->savedVer = 2;
      pProgress->doneVer = 2;
      pProgress->lastScanVer = 2;
      pProgress = static_cast<SSTriggerWalProgress*>(
          tSimpleHashIterate(pTask->pRealtimeContext->pReaderWalProgress, pProgress, &iter));
    }
    pTask->task.undeployMsg.doCheckpoint = 1;
    pTask->task.undeployMsg.doCleanup = 0;
    const int64_t expectedStreamId = pTask->task.streamId;
    gNestedHistoryCheckpointStreamId = 0;
    gNestedHistoryCheckpointBytes.clear();
    if (harness.undeploy() != TSDB_CODE_SUCCESS || gNestedHistoryCheckpointStreamId != expectedStreamId ||
        gNestedHistoryCheckpointBytes.empty()) {
      return false;
    }
    *pBytes = gNestedHistoryCheckpointBytes;
    return true;
  };

  Stub checkpointStub;
  checkpointStub.set(streamWriteCheckPoint, captureNestedHistoryCheckpoint);
  std::vector<uint8_t> baseline;
  std::vector<uint8_t> afterHistory;
  ASSERT_TRUE(captureCheckpoint(false, &baseline));
  ASSERT_TRUE(captureCheckpoint(true, &afterHistory));
  checkpointStub.reset(streamWriteCheckPoint);

  ASSERT_EQ(baseline, afterHistory);
  SDecoder decoder = {};
  tDecoderInit(&decoder, baseline.data(), static_cast<int64_t>(baseline.size()));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tStartDecode(&decoder));
  int32_t checkpointVersion = 0;
  int64_t streamId = 0;
  int32_t formatVersion = 0;
  int32_t walCount = 0;
  int32_t vgId = 0;
  int64_t startVer = 0;
  int64_t doneVer = 0;
  int32_t cutoffCount = 0;
  int64_t cutoffGid = 0;
  int64_t cutoffTime = 0;
  int8_t  historyFinished = 0;
  int32_t extRegistryCount = 0;
  int32_t extBindingCount = 0;
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &checkpointVersion));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI64(&decoder, &streamId));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &formatVersion));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &walCount));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &vgId));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI64(&decoder, &startVer));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI64(&decoder, &doneVer));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &cutoffCount));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI64(&decoder, &cutoffGid));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI64(&decoder, &cutoffTime));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI8(&decoder, &historyFinished));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &extRegistryCount));
  ASSERT_EQ(TSDB_CODE_SUCCESS, tDecodeI32(&decoder, &extBindingCount));
  tEndDecode(&decoder);
  tDecoderClear(&decoder);
  EXPECT_EQ(41, checkpointVersion);
  EXPECT_EQ(42, streamId);
  // v8 (STREAM_TRIGGER_CHECKPOINT_FORMAT_VERSION): the EXT binding completed cutoff moved to
  // nanosecond wire values; the macro itself lives in streamTriggerTask.c and is not visible here.
  EXPECT_EQ(8, formatVersion);
  EXPECT_EQ(1, walCount);
  EXPECT_EQ(NestedHistoryHarness::kReaderNodeId, vgId);
  EXPECT_EQ(2, startVer);
  EXPECT_EQ(2, doneVer);
  EXPECT_EQ(1, cutoffCount);
  EXPECT_EQ(NestedHistoryHarness::kGid, cutoffGid);
  EXPECT_EQ(NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep, cutoffTime);
  EXPECT_EQ(1, historyFinished);
  EXPECT_EQ(0, extRegistryCount);
  EXPECT_EQ(0, extBindingCount);
}

TEST_F(StreamNestedHistoryRecoveryBoundaryTest, HistoryCompletionDoesNotInstallRealtimeChain) {
  NestedHistoryHarness harness;
  ASSERT_TRUE(harness.deploy());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startAndCreateHistory());
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            harness.respondRealtimeWal(NestedHistoryHarness::kScanStart + NestedHistoryHarness::kHistoryStep + 1, 7));
  SSTriggerRealtimeGroup* pRealtimeGroup = harness.realtimeGroup();
  ASSERT_NE(nullptr, pRealtimeGroup);
  ASSERT_NE(nullptr, pRealtimeGroup->pWindowChain);
  SWindowChainState* pRealtimeChain = pRealtimeGroup->pWindowChain;
  int64_t            realtimeDeadline = stWindowChainNextDelayDeadline(pRealtimeChain);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.startHistoryRequest());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondFirstTs());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondMeta());
  SSTriggerHistoryGroup* pHistoryGroup = harness.historyGroup();
  ASSERT_NE(nullptr, pHistoryGroup);
  ASSERT_NE(nullptr, pHistoryGroup->pWindowChain);
  EXPECT_NE(pRealtimeChain, pHistoryGroup->pWindowChain);
  int32_t realtimePending = listNEles(&pRealtimeGroup->pendingNestedEvents);
  int32_t realtimeParWinPending = listNEles(&pRealtimeGroup->pendingNestedParWinEvents);

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondRows({1000, 1001}, {10, 20}));
  ASSERT_EQ(1, listNEles(&pHistoryGroup->pendingNestedEvents));
  EXPECT_EQ(pRealtimeChain, pRealtimeGroup->pWindowChain);
  EXPECT_EQ(realtimeDeadline, stWindowChainNextDelayDeadline(pRealtimeGroup->pWindowChain));
  EXPECT_EQ(realtimePending, listNEles(&pRealtimeGroup->pendingNestedEvents));
  EXPECT_EQ(realtimeParWinPending, listNEles(&pRealtimeGroup->pendingNestedParWinEvents));

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondPendingEmptyMetas());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcDataRows({1000, 1001}, {10, 20}));
  ASSERT_EQ(1, harness.calcAttemptCount());
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.respondCalcAttempt(0));
  ASSERT_NE(nullptr, harness.historyContext());
  EXPECT_EQ(0, tSimpleHashGetSize(harness.historyContext()->pGroups));
  EXPECT_EQ(pRealtimeChain, pRealtimeGroup->pWindowChain);
  EXPECT_EQ(realtimeDeadline, stWindowChainNextDelayDeadline(pRealtimeGroup->pWindowChain));
  EXPECT_EQ(realtimePending, listNEles(&pRealtimeGroup->pendingNestedEvents));
  EXPECT_EQ(realtimeParWinPending, listNEles(&pRealtimeGroup->pendingNestedParWinEvents));
}

