TEST_F(StreamNestedRealtimeTest, FreezesNonePolicyForCalcOnlyIdleAndResume) {
  ScopedStreamBatchRequestWait batchWait(10);
  gRealtimePipelineClockNs = NANOSECOND_PER_MSEC;
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false,
                           STRIGGER_EVENT_IDLE | STRIGGER_EVENT_RESUME, STRIGGER_EVENT_WINDOW_NONE, 0, 1, false, 50));
  Stub clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineClock);
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({1000}, {1}));

  SSTriggerRealtimeGroup* pGroup = harness.group(42);
  ASSERT_NE(nullptr, pGroup);
  EXPECT_EQ(1, pGroup->lastRecvTimeMono);
  gRealtimePipelineClockNs = 51 * NANOSECOND_PER_MSEC;
  ASSERT_TRUE(harness.feedZeroRowWal());
  EXPECT_EQ(1, pGroup->idleState);
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());

  ASSERT_TRUE(harness.feedRows({1005}, {2}));
  EXPECT_EQ(0, pGroup->idleState);
  ASSERT_GT(pGroup->nextExecTime, gRealtimePipelineClockNs);
  ASSERT_TRUE(harness.feedZeroRowWal());
  gRealtimePipelineClockNs = pGroup->nextExecTime + 1;
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());
  ASSERT_TRUE(harness.feedZeroRowWal());

  const SSTriggerCalcRequest* pRequest = harness.capturedCalc();
  ASSERT_NE(nullptr, pRequest);
  ASSERT_NE(nullptr, pRequest->params);
  ASSERT_EQ(2, taosArrayGetSize(pRequest->params));
  const auto* pIdle = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 0));
  const auto* pResume = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 1));
  ASSERT_NE(nullptr, pIdle);
  ASSERT_NE(nullptr, pResume);
  EXPECT_EQ(NANOSECOND_PER_MSEC, pIdle->idlestart);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pIdle->idleend);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pIdle->triggerTime);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pIdle->notifyType);
  EXPECT_EQ(NANOSECOND_PER_MSEC, pResume->idlestart);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->idleend);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->triggerTime);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pResume->notifyType);

  ASSERT_NE(nullptr, pRequest->pContextPolicy);
  ASSERT_NE(nullptr, pRequest->pContextPolicy->pEntries);
  ASSERT_EQ(2, taosArrayGetSize(pRequest->pContextPolicy->pEntries));
  const auto* pPolicy0 =
      static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pRequest->pContextPolicy->pEntries, 0));
  const auto* pPolicy1 =
      static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pRequest->pContextPolicy->pEntries, 1));
  ASSERT_NE(nullptr, pPolicy0);
  ASSERT_NE(nullptr, pPolicy1);
  EXPECT_EQ(42, pPolicy0->gid);
  EXPECT_EQ(0, pPolicy0->paramIndex);
  EXPECT_EQ(STREAM_CONTEXT_POLICY_NONE, pPolicy0->contextPolicy);
  EXPECT_EQ(42, pPolicy1->gid);
  EXPECT_EQ(1, pPolicy1->paramIndex);
  EXPECT_EQ(STREAM_CONTEXT_POLICY_NONE, pPolicy1->contextPolicy);
  EXPECT_EQ(nullptr, pRequest->pAncestorContext);
  EXPECT_EQ(TSDB_CODE_SUCCESS, tValidateSTriggerCalcRequestAncestorContext(pRequest, true));
}

TEST_F(StreamNestedRealtimeTest, NestedIdleAndResumePullResponseTurnsSampleOneFrozenNow) {
  ScopedStreamBatchRequestWait batchWait(10);
  RealtimePipelineHarness      harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false,
                           STRIGGER_EVENT_IDLE | STRIGGER_EVENT_RESUME, STRIGGER_EVENT_WINDOW_NONE, 0, 1, false, 50));
  ScopedRealtimePipelinePhaseClock clock(NANOSECOND_PER_MSEC,
                                         NANOSECOND_PER_MSEC);
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({1000}, {1}));
  SSTriggerRealtimeGroup* pGroup = harness.group();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, harness.context());
  ASSERT_NE(nullptr, harness.context()->pMaxDelayHeap);

  const int64_t idleNow = 51 * NANOSECOND_PER_MSEC;
  clock.reset(idleNow, idleNow);
  // Ignore the harness's round-trip decode; advance on the actual response.
  clock.advanceOnWalDecode(harness.context()->pTempSlices,
                           idleNow + NANOSECOND_PER_MSEC);
  ASSERT_TRUE(harness.feedZeroRowWal());
  EXPECT_TRUE(clock.advanced());
  EXPECT_EQ(1, pGroup->idleState);
  ASSERT_EQ(1, listNEles(&pGroup->pendingNestedEvents));
  const SListNode* pIdleNode = listHead(&pGroup->pendingNestedEvents);
  ASSERT_NE(nullptr, pIdleNode);
  const auto* pIdleEvent = reinterpret_cast<const SStreamNestedPendingCalcEvent*>(pIdleNode->data);
  EXPECT_EQ(idleNow, pIdleEvent->calcParam.triggerTime);
  EXPECT_EQ(idleNow, pIdleEvent->calcParam.idleend);
  EXPECT_EQ(idleNow + 10 * NANOSECOND_PER_MSEC, pGroup->nextExecTime);
  EXPECT_EQ(1U, heapSize(harness.context()->pMaxDelayHeap));
  EXPECT_EQ(&pGroup->heapNode, heapMin(harness.context()->pMaxDelayHeap));
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());

  const int64_t resumeNow = 101 * NANOSECOND_PER_MSEC;
  clock.reset(resumeNow, 61 * NANOSECOND_PER_MSEC);
  clock.advanceOnWalDecode(harness.context()->pTempSlices,
                           resumeNow + NANOSECOND_PER_MSEC);
  ASSERT_TRUE(harness.feedRows({1005}, {2}));
  EXPECT_TRUE(clock.advanced());
  EXPECT_EQ(0, pGroup->idleState);
  EXPECT_EQ(resumeNow, pGroup->lastRecvTimeWall);
  ASSERT_EQ(2, listNEles(&pGroup->pendingNestedEvents));
  SListIter eventIter = {};
  tdListInitIter(&pGroup->pendingNestedEvents, &eventIter, TD_LIST_FORWARD);
  ASSERT_NE(nullptr, tdListNext(&eventIter));
  const SListNode* pResumeNode = tdListNext(&eventIter);
  ASSERT_NE(nullptr, pResumeNode);
  const auto* pResumeEvent = reinterpret_cast<const SStreamNestedPendingCalcEvent*>(pResumeNode->data);
  EXPECT_EQ(resumeNow, pResumeEvent->calcParam.triggerTime);
  EXPECT_EQ(resumeNow, pResumeEvent->calcParam.idleend);
  EXPECT_EQ(resumeNow + 10 * NANOSECOND_PER_MSEC, pGroup->nextExecTime);
  EXPECT_EQ(1U, heapSize(harness.context()->pMaxDelayHeap));
  EXPECT_EQ(&pGroup->heapNode, heapMin(harness.context()->pMaxDelayHeap));
}

TEST_F(StreamNestedRealtimeTest, BatchesGroupLeafPoliciesWithoutNotifyInference) {
  ScopedStreamBatchRequestWait batchWait(10);
  gRealtimePipelineClockNs = NANOSECOND_PER_MSEC;
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false,
                           STRIGGER_EVENT_IDLE | STRIGGER_EVENT_RESUME | STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, false, 50));
  Stub clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineClock);
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({1000}, {1}));
  gRealtimePipelineClockNs = 51 * NANOSECOND_PER_MSEC;
  ASSERT_TRUE(harness.feedZeroRowWal());
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());
  ASSERT_TRUE(harness.feedRows({1015}, {2}));

  SSTriggerRealtimeGroup* pGroup = harness.group(42);
  ASSERT_NE(nullptr, pGroup);
  ASSERT_GT(pGroup->nextExecTime, gRealtimePipelineClockNs);
  ASSERT_TRUE(harness.feedZeroRowWal());
  gRealtimePipelineClockNs = pGroup->nextExecTime + 1;
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());
  ASSERT_TRUE(harness.feedZeroRowWal());

  const SSTriggerCalcRequest* pRequest = harness.capturedCalc();
  ASSERT_NE(nullptr, pRequest);
  ASSERT_NE(nullptr, pRequest->params);
  ASSERT_EQ(3, taosArrayGetSize(pRequest->params));
  const auto* pIdle = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 0));
  const auto* pResume = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 1));
  const auto* pClose = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pRequest->params, 2));
  ASSERT_NE(nullptr, pIdle);
  ASSERT_NE(nullptr, pResume);
  ASSERT_NE(nullptr, pClose);
  EXPECT_EQ(NANOSECOND_PER_MSEC, pIdle->idlestart);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pIdle->idleend);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pIdle->triggerTime);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pIdle->notifyType);
  EXPECT_EQ(NANOSECOND_PER_MSEC, pResume->idlestart);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->idleend);
  EXPECT_EQ(51 * NANOSECOND_PER_MSEC, pResume->triggerTime);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pResume->notifyType);
  EXPECT_EQ(1000, pClose->wstart);
  EXPECT_EQ(1000, pClose->wend);
  EXPECT_EQ(0, pClose->wduration);
  EXPECT_EQ(1, pClose->wrownum);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pClose->notifyType);

  ASSERT_NE(nullptr, pRequest->pContextPolicy);
  ASSERT_NE(nullptr, pRequest->pContextPolicy->pEntries);
  ASSERT_EQ(3, taosArrayGetSize(pRequest->pContextPolicy->pEntries));
  const int8_t expectedPolicies[] = {STREAM_CONTEXT_POLICY_NONE, STREAM_CONTEXT_POLICY_NONE,
                                     STREAM_CONTEXT_POLICY_ANCESTOR};
  for (int32_t i = 0; i < 3; ++i) {
    const auto* pPolicy =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pRequest->pContextPolicy->pEntries, i));
    ASSERT_NE(nullptr, pPolicy);
    EXPECT_EQ(42, pPolicy->gid);
    EXPECT_EQ(i, pPolicy->paramIndex);
    EXPECT_EQ(expectedPolicies[i], pPolicy->contextPolicy);
  }

  ASSERT_NE(nullptr, pRequest->pAncestorContext);
  ASSERT_NE(nullptr, pRequest->pAncestorContext->pParamContexts);
  ASSERT_EQ(1, taosArrayGetSize(pRequest->pAncestorContext->pParamContexts));
  EXPECT_TRUE(pRequest->pAncestorContext->pReadScopeBindings == nullptr ||
              taosArrayGetSize(pRequest->pAncestorContext->pReadScopeBindings) == 0);
  PipelineAncestorObservation close = {};
  ASSERT_TRUE(readAncestorObservation(pRequest, 42, 2, &close));
  EXPECT_EQ(42, close.leafGid);
  EXPECT_EQ(WINDOW_TYPE_SESSION, close.leafTriggerType);
  EXPECT_EQ(1000, close.leafOpeningTs);
  EXPECT_EQ(0, close.leafNativeDiscriminator);
  EXPECT_EQ(0, close.scope.layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, close.scope.triggerType);
  EXPECT_EQ(1000, close.scope.openingTs);
  EXPECT_EQ(0, close.scope.nativeDiscriminator);
  EXPECT_EQ(0, close.snapshot.layerIndex);
  EXPECT_EQ(WINDOW_TYPE_SESSION, close.snapshot.triggerType);
  EXPECT_EQ(0, close.snapshot.placeholderMask);
  EXPECT_EQ(1000, close.snapshot.values.window.start);
  EXPECT_EQ(1015, close.snapshot.values.window.end);
  EXPECT_EQ(15, close.snapshot.values.window.duration);
  EXPECT_EQ(2, close.snapshot.values.window.rownum);
  EXPECT_EQ(TSDB_CODE_SUCCESS, tValidateSTriggerCalcRequestAncestorContext(pRequest, true));
}

