    EXPECT_STREQ(name->valuestring, missing ? "" : "sensor_a");
    EXPECT_STREQ("2f0a3aa99365141f693d55a7e2c7da2d",
                 cJSON_GetStringValue(cJSON_GetObjectItemCaseSensitive(event, "triggerId")));
