TEST_F(StreamNestedRealtimeTest, ExtNotifyNameUsesReaderRouteAndResumesTheWindow) {
  for (bool missing : {false, true}) {
    SCOPED_TRACE(missing);
    RealtimePipelineHarness harness;
    ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_NONE,
                             STRIGGER_EVENT_WINDOW_CLOSE));
    ASSERT_TRUE(harness.start());
    ASSERT_TRUE(harness.feedRows({1000}, {1}));
    auto* context = harness.context();
    auto* group = harness.group();
    ASSERT_NE(group, nullptr);
    context->pReaderExtProgress = tSimpleHashInit(1, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BIGINT));
    ASSERT_NE(context->pReaderExtProgress, nullptr);
    tSimpleHashSetFreeFp(context->pReaderExtProgress, destroyRecoveryTestExtProgress);
    auto* progress = static_cast<SSTriggerExtProgress*>(taosMemoryCalloc(1, sizeof(SSTriggerExtProgress)));
    ASSERT_NE(progress, nullptr);
    progress->pTaskAddr = static_cast<SStreamTaskAddr*>(taosArrayGet(harness.task()->readerList, 0));
    progress->pOwnerTask = harness.task();
    progress->sessionId = context->sessionId;
    ASSERT_EQ(TSDB_CODE_SUCCESS, tSimpleHashPut(context->pReaderExtProgress, &progress->pTaskAddr->taskId,
                                                sizeof(int64_t), &progress, POINTER_BYTES));
    group->extReaderTaskId = progress->pTaskAddr->taskId;
    group->vgId = -1;  // EXT groups have no entry in the WAL reader map.
    harness.task()->partitionByTbname = true;
    harness.task()->stbPartByTbname = true;
    harness.task()->notifyEventType = STRIGGER_EVENT_WINDOW_CLOSE;
    ASSERT_TRUE(harness.feedRows({1015}, {2}));
    ASSERT_TRUE(context->notifyGroupColValuePending);
    EXPECT_EQ(0, harness.groupColPullCount(42));
    EXPECT_EQ(1, progress->pendingPulls);
    ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchExtGroupColValue(missing ? nullptr : "influx_series"));
    EXPECT_FALSE(context->notifyGroupColValuePending);
    ASSERT_EQ(1, harness.noticeSendCount());
    std::unique_ptr<cJSON, decltype(&cJSON_Delete)> root(cJSON_Parse(harness.noticePayload().c_str()), cJSON_Delete);
    ASSERT_NE(root, nullptr);
    cJSON* event = nestedNoticeEvent(root.get());
    EXPECT_STREQ(missing ? "" : "influx_series",
                 cJSON_GetStringValue(cJSON_GetObjectItemCaseSensitive(event, "triggerTableName")));
  }
}

TEST_F(StreamNestedRealtimeTest, NotifyWithoutCalcQueuesBeforeReturning) {
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_NONE,
                           STRIGGER_EVENT_WINDOW_CLOSE));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({1000, 1015}, {1, 2}));

  EXPECT_EQ(0, harness.calcSendCount());
  EXPECT_EQ(0, harness.calcParamCount());
  EXPECT_EQ(nullptr, harness.capturedCalc());
  ASSERT_EQ(1, harness.noticeSendCount());
  EXPECT_EQ("ws://pipeline-notify.test", harness.noticeUrl());
  ASSERT_FALSE(harness.noticePayload().empty());
  const std::string sentUrl = harness.noticeUrl();
  const std::string sentPayload = harness.noticePayload();

  const auto hasExactMembers = [](const cJSON* pObject, std::initializer_list<const char*> expected) {
    if (!cJSON_IsObject(pObject)) return false;
    int32_t memberCount = 0;
    for (const cJSON* pMember = pObject->child; pMember != nullptr; pMember = pMember->next) ++memberCount;
    if (memberCount != static_cast<int32_t>(expected.size())) return false;
    for (const char* pName : expected) {
      int32_t matches = 0;
      for (const cJSON* pMember = pObject->child; pMember != nullptr; pMember = pMember->next) {
        if (pMember->string != nullptr && std::string(pMember->string) == pName) ++matches;
      }
      if (matches != 1) return false;
    }
    return true;
  };

  std::unique_ptr<cJSON, decltype(&cJSON_Delete)> pRoot(cJSON_Parse(sentPayload.c_str()), cJSON_Delete);
  ASSERT_NE(nullptr, pRoot);
  ASSERT_TRUE(hasExactMembers(pRoot.get(), {"messageId", "timestamp", "streams"}));
  cJSON* pMessageId = cJSON_GetObjectItemCaseSensitive(pRoot.get(), "messageId");
  cJSON* pTimestamp = cJSON_GetObjectItemCaseSensitive(pRoot.get(), "timestamp");
  cJSON* pStreams = cJSON_GetObjectItemCaseSensitive(pRoot.get(), "streams");
  ASSERT_TRUE(cJSON_IsString(pMessageId));
  ASSERT_TRUE(cJSON_IsNumber(pTimestamp));
  ASSERT_TRUE(cJSON_IsArray(pStreams));
  ASSERT_EQ(1, cJSON_GetArraySize(pStreams));

  cJSON* pStream = cJSON_GetArrayItem(pStreams, 0);
  ASSERT_TRUE(hasExactMembers(pStream, {"streamName", "events"}));
  cJSON* pStreamName = cJSON_GetObjectItemCaseSensitive(pStream, "streamName");
  cJSON* pEvents = cJSON_GetObjectItemCaseSensitive(pStream, "events");
  ASSERT_TRUE(cJSON_IsString(pStreamName));
  EXPECT_STREQ("deploy_window_plan", cJSON_GetStringValue(pStreamName));
  ASSERT_TRUE(cJSON_IsArray(pEvents));
  ASSERT_EQ(1, cJSON_GetArraySize(pEvents));

  cJSON* pEvent = cJSON_GetArrayItem(pEvents, 0);
  ASSERT_TRUE(hasExactMembers(pEvent, {"eventType", "eventTime", "triggerId", "triggerType", "groupId",
                                       "triggerTableName", "windowStart", "windowEnd"}));
  EXPECT_EQ(nullptr, cJSON_GetObjectItemCaseSensitive(pEvent, "tableName"));
  cJSON* pEventType = cJSON_GetObjectItemCaseSensitive(pEvent, "eventType");
  cJSON* pEventTime = cJSON_GetObjectItemCaseSensitive(pEvent, "eventTime");
  cJSON* pTriggerId = cJSON_GetObjectItemCaseSensitive(pEvent, "triggerId");
  cJSON* pTriggerType = cJSON_GetObjectItemCaseSensitive(pEvent, "triggerType");
  cJSON* pGroupId = cJSON_GetObjectItemCaseSensitive(pEvent, "groupId");
  cJSON* pWindowStart = cJSON_GetObjectItemCaseSensitive(pEvent, "windowStart");
  cJSON* pWindowEnd = cJSON_GetObjectItemCaseSensitive(pEvent, "windowEnd");
  ASSERT_TRUE(cJSON_IsString(pEventType));
  ASSERT_TRUE(cJSON_IsNumber(pEventTime));
  ASSERT_TRUE(cJSON_IsString(pTriggerId));
  ASSERT_TRUE(cJSON_IsString(pTriggerType));
  ASSERT_TRUE(cJSON_IsString(pGroupId));
  ASSERT_TRUE(cJSON_IsNumber(pWindowStart));
  ASSERT_TRUE(cJSON_IsNumber(pWindowEnd));
  EXPECT_STREQ("WINDOW_CLOSE", cJSON_GetStringValue(pEventType));
  EXPECT_STREQ("2f0a3aa99365141f693d55a7e2c7da2d", cJSON_GetStringValue(pTriggerId));
  EXPECT_STREQ("Session", cJSON_GetStringValue(pTriggerType));
  EXPECT_STREQ("42", cJSON_GetStringValue(pGroupId));
  EXPECT_EQ(1000, static_cast<int64_t>(cJSON_GetNumberValue(pWindowStart)));
  EXPECT_EQ(1000, static_cast<int64_t>(cJSON_GetNumberValue(pWindowEnd)));
  EXPECT_TRUE(gLegacyNotifyPayload.empty());

  bool stillPending = true;
  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.confirmNoDeferredNotice(&stillPending));
  EXPECT_FALSE(stillPending);
  EXPECT_EQ(1, harness.noticeSendCount());
  EXPECT_EQ(sentUrl, harness.noticeUrl());
  EXPECT_EQ(sentPayload, harness.noticePayload());
  EXPECT_TRUE(gLegacyNotifyPayload.empty());
}

