  ASSERT_TRUE(harness.feedGroups({{42, 1001, {1000, 2000}, {1, 2}, 2}, {43, 1002, {1000, 2000}, {3, 4}, 2}}));
  EXPECT_GT(harness.group(42)->pPendingCalcParams.neles, 0);
  EXPECT_GT(harness.group(43)->pPendingCalcParams.neles, 0);
