TEST_F(StreamTriggerTaskTest, NestedRealtimePacksMultipleGroupsWithExactLineage) {
  gRealtimePipelineClockNs = 100 * NANOSECOND_PER_MSEC;
  RealtimePipelineHarness harness;
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedSessionHierarchy, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 0, 1, false, 0, true));
  Stub clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineClock);
  ASSERT_TRUE(harness.start());

  const int64_t wallTime42 = 100 * NANOSECOND_PER_MSEC;
  gRealtimePipelineClockNs = wallTime42;
  const PipelineWalGroup group42 = {42, 1001, {1000, 1015, 1040, 1055}, {1, 2, 3, 4}, 2};
  ASSERT_TRUE(harness.feedGroups({group42}));
  SSTriggerRealtimeGroup* pGroup42 = harness.group(42);
  ASSERT_NE(nullptr, pGroup42);
  const int64_t deadline42 = pGroup42->nextExecTime;
  ASSERT_GT(deadline42, wallTime42);

  const int64_t wallTime43 = wallTime42 + NANOSECOND_PER_MSEC;
  ASSERT_GT(wallTime43, wallTime42);
  ASSERT_LT(wallTime43, deadline42);
  gRealtimePipelineClockNs = wallTime43;
  const PipelineWalGroup group43 = {43, 1002, {2000, 2015}, {5, 6}, 3};
  ASSERT_TRUE(harness.feedGroups({group43}));
  SSTriggerRealtimeGroup* pGroup43 = harness.group(43);
  ASSERT_NE(nullptr, pGroup43);
  const int64_t deadline43 = pGroup43->nextExecTime;
  ASSERT_LT(deadline42, deadline43);

  ASSERT_TRUE(harness.feedZeroRowWal());
  gRealtimePipelineClockNs = deadline43 + 1;
  ASSERT_TRUE(harness.dispatchSerializedRealtimeStart());
  ASSERT_TRUE(harness.feedZeroRowWal());
  const SSTriggerCalcRequest* pRequest = harness.capturedCalc();
  ASSERT_NE(nullptr, pRequest);
  ASSERT_TRUE(pRequest->isMultiGroupCalc);

  const SSTriggerGroupCalcInfo* pCalc42 = pipelineGroupCalcInfo(pRequest, 42);
  const SSTriggerGroupCalcInfo* pCalc43 = pipelineGroupCalcInfo(pRequest, 43);
  ASSERT_NE(nullptr, pCalc42);
  ASSERT_NE(nullptr, pCalc43);
  ASSERT_NE(nullptr, pCalc42->pParams);
  ASSERT_NE(nullptr, pCalc43->pParams);
  ASSERT_EQ(3, taosArrayGetSize(pCalc42->pParams));
  ASSERT_EQ(1, taosArrayGetSize(pCalc43->pParams));
  const TSKEY expectedParamStarts42[] = {1000, 1015, 1040};
  const TSKEY expectedParamEnds42[] = {1000, 1015, 1040};
  for (int32_t i = 0; i < 3; ++i) {
    const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc42->pParams, i));
    ASSERT_NE(nullptr, pParam);
    EXPECT_EQ(expectedParamStarts42[i], pParam->wstart);
    EXPECT_EQ(expectedParamEnds42[i], pParam->wend);
    EXPECT_EQ(0, pParam->wduration);
    EXPECT_EQ(1, pParam->wrownum);
    EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pParam->notifyType);
  }
  const auto* pParam43 = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc43->pParams, 0));
  ASSERT_NE(nullptr, pParam43);
  EXPECT_EQ(2000, pParam43->wstart);
  EXPECT_EQ(2000, pParam43->wend);
  EXPECT_EQ(0, pParam43->wduration);
  EXPECT_EQ(1, pParam43->wrownum);
  EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pParam43->notifyType);

  ASSERT_NE(nullptr, pRequest->pContextPolicy);
  ASSERT_NE(nullptr, pRequest->pContextPolicy->pEntries);
  ASSERT_EQ(4, taosArrayGetSize(pRequest->pContextPolicy->pEntries));
  const int64_t expectedPolicyGids[] = {42, 42, 42, 43};
  const int32_t expectedPolicyIndices[] = {0, 1, 2, 0};
  const TSKEY   expectedLeafOpenings[] = {1000, 1015, 1040, 2000};
  const TSKEY   expectedLineageOpenings[] = {1000, 1000, 1040, 2000};
  for (int32_t i = 0; i < 4; ++i) {
    const auto* pPolicy =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pRequest->pContextPolicy->pEntries, i));
    ASSERT_NE(nullptr, pPolicy);
    EXPECT_EQ(expectedPolicyGids[i], pPolicy->gid);
    EXPECT_EQ(expectedPolicyIndices[i], pPolicy->paramIndex);
    EXPECT_EQ(STREAM_CONTEXT_POLICY_ANCESTOR, pPolicy->contextPolicy);
    PipelineAncestorObservation observation = {};
    ASSERT_TRUE(readAncestorObservation(pRequest, expectedPolicyGids[i], expectedPolicyIndices[i], &observation));
    EXPECT_EQ(expectedPolicyGids[i], observation.leafGid);
    EXPECT_EQ(WINDOW_TYPE_SESSION, observation.leafTriggerType);
    EXPECT_EQ(expectedLeafOpenings[i], observation.leafOpeningTs);
    EXPECT_EQ(0, observation.leafNativeDiscriminator);
    EXPECT_EQ(0, observation.scope.layerIndex);
    EXPECT_EQ(WINDOW_TYPE_SESSION, observation.scope.triggerType);
    EXPECT_EQ(expectedLineageOpenings[i], observation.scope.openingTs);
    EXPECT_EQ(0, observation.scope.nativeDiscriminator);
  }

  ASSERT_NE(nullptr, pRequest->pGroupReadInfos);
  const int32_t vgId = 7;
  auto* const*  ppReadInfos =
      static_cast<SArray* const*>(tSimpleHashGet(pRequest->pGroupReadInfos, &vgId, sizeof(vgId)));
  ASSERT_NE(nullptr, ppReadInfos);
  ASSERT_NE(nullptr, *ppReadInfos);
  ASSERT_EQ(3, taosArrayGetSize(*ppReadInfos));
  const int64_t expectedReadGids[] = {42, 42, 43};
  const TSKEY   expectedFirstStarts[] = {1000, 1040, 2000};
  const TSKEY   expectedFirstEnds[] = {1000, 1040, 2000};
  const TSKEY   expectedLastStarts[] = {1015, 1040, 2000};
  const TSKEY   expectedLastEnds[] = {1015, 1040, 2000};
  for (int32_t i = 0; i < 3; ++i) {
    const auto* pReadInfo = static_cast<const SSTriggerGroupReadInfo*>(taosArrayGet(*ppReadInfos, i));
    ASSERT_NE(nullptr, pReadInfo);
    EXPECT_EQ(expectedReadGids[i], pReadInfo->gid);
    EXPECT_EQ(expectedFirstStarts[i], pReadInfo->firstParam.wstart);
    EXPECT_EQ(expectedFirstEnds[i], pReadInfo->firstParam.wend);
    EXPECT_EQ(expectedLastStarts[i], pReadInfo->lastParam.wstart);
    EXPECT_EQ(expectedLastEnds[i], pReadInfo->lastParam.wend);
  }

  ASSERT_NE(nullptr, pRequest->pAncestorContext);
  ASSERT_NE(nullptr, pRequest->pAncestorContext->pParamContexts);
  ASSERT_EQ(4, taosArrayGetSize(pRequest->pAncestorContext->pParamContexts));
  ASSERT_NE(nullptr, pRequest->pAncestorContext->pReadScopeBindings);
  ASSERT_EQ(3, taosArrayGetSize(pRequest->pAncestorContext->pReadScopeBindings));
  const int64_t expectedBindingGids[] = {42, 42, 43};
  const TSKEY   expectedBindingOpenings[] = {1000, 1040, 2000};
  for (int32_t i = 0; i < 3; ++i) {
    const auto* pBinding =
        static_cast<const SStreamReadScopeBinding*>(taosArrayGet(pRequest->pAncestorContext->pReadScopeBindings, i));
    ASSERT_NE(nullptr, pBinding);
    EXPECT_EQ(7, pBinding->vgId);
    EXPECT_EQ(i, pBinding->readInfoIndex);
    EXPECT_EQ(expectedBindingGids[i], pBinding->scope.gid);
    ASSERT_NE(nullptr, pBinding->scope.lineage.pScopes);
    ASSERT_EQ(1, taosArrayGetSize(pBinding->scope.lineage.pScopes));
    const auto* pScope = static_cast<const SScopeInstanceId*>(taosArrayGet(pBinding->scope.lineage.pScopes, 0));
    ASSERT_NE(nullptr, pScope);
    EXPECT_EQ(0, pScope->layerIndex);
    EXPECT_EQ(WINDOW_TYPE_SESSION, pScope->triggerType);
    EXPECT_EQ(expectedBindingOpenings[i], pScope->openingTs);
    EXPECT_EQ(0, pScope->nativeDiscriminator);
  }
  EXPECT_EQ(TSDB_CODE_SUCCESS, tValidateSTriggerCalcRequestAncestorContext(pRequest, true));
}

