  ASSERT_TRUE(harness.feedGroups({{100, 2000, {2000, 2015}, {3, 4}, 3}}));
  SSTriggerRealtimeGroup* pUnchecked = harness.group(100);
  ASSERT_NE(nullptr, pUnchecked);
  EXPECT_EQ(0, pUnchecked->nestedPendingParamCount);
