TEST_F(StreamNestedRealtimeTest, KeepsSingleMaxDelayHeapNode) {
  gRealtimePipelineClockNs = 100 * NANOSECOND_PER_MSEC;
  RealtimePipelineHarness harness;
  Stub                    clockStub;
  clockStub.set(taosClockGetTime, captureRealtimePipelineClock);
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedIntervalOverlap, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE, 1000));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({1000}, {1}));

  SSTriggerRealtimeGroup* pGroup = harness.group();
  ASSERT_NE(nullptr, pGroup);
  ASSERT_NE(nullptr, pGroup->pWindowChain);
  SWindowChainState* pChain = pGroup->pWindowChain;
  HeapNode*          pHeapNode = &pGroup->heapNode;
  ASSERT_NE(nullptr, harness.context());
  ASSERT_NE(nullptr, harness.context()->pMaxDelayHeap);
  EXPECT_EQ(INT64_C(1100000000), stWindowChainNextDelayDeadline(pChain));
  EXPECT_EQ(INT64_C(1100000000), pGroup->nextExecTime);
  EXPECT_EQ(1U, heapSize(harness.context()->pMaxDelayHeap));
  EXPECT_EQ(pHeapNode, heapMin(harness.context()->pMaxDelayHeap));

  ASSERT_TRUE(harness.feedRows({2000}, {2}));
  SSTriggerRealtimeGroup* pSameGroup = harness.group();
  ASSERT_NE(nullptr, pSameGroup);
  EXPECT_EQ(pChain, pSameGroup->pWindowChain);
  EXPECT_EQ(pHeapNode, &pSameGroup->heapNode);
  EXPECT_EQ(1U, heapSize(harness.context()->pMaxDelayHeap));
  EXPECT_EQ(pHeapNode, heapMin(harness.context()->pMaxDelayHeap));
  EXPECT_EQ(INT64_C(1100000000), stWindowChainNextDelayDeadline(pSameGroup->pWindowChain));
  EXPECT_EQ(INT64_C(1100000000), pSameGroup->nextExecTime);
  EXPECT_EQ(0, harness.calcSendCount());
}

