TEST_F(StreamNestedRealtimeTest, OuterClosePublishesFrozenOldSnapshot) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedIntervalCount, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({8000, 9000, 10000}, {1, 2, 3}));
  ASSERT_EQ(0, harness.calcSendCount());
  ASSERT_EQ(1, harness.pendingPullCount(STRIGGER_PULL_WAL_CALC_DATA_NEW));
  ASSERT_NE(nullptr, harness.context()->pCalcReq);
  ASSERT_NE(nullptr, harness.context()->pNestedCalcMaterialization);
  EXPECT_EQ(0, listNEles(&harness.group()->pendingNestedEvents));
  ASSERT_TRUE(harness.respondCalcRows({8000, 9000, 10000}, {1, 2, 3}));
  ASSERT_EQ(1, harness.calcSendCount());

  const SSTriggerCalcRequest* pCalc = harness.capturedCalc();
  ASSERT_NE(nullptr, pCalc);
  ASSERT_NE(nullptr, pCalc->params);
  ASSERT_EQ(2, taosArrayGetSize(pCalc->params));
  int32_t completedCount = 0;
  int32_t forcedCount = 0;
  int32_t forcedParamIndex = -1;
  for (int32_t i = 0; i < taosArrayGetSize(pCalc->params); ++i) {
    const auto* pParam = static_cast<const SSTriggerCalcParam*>(taosArrayGet(pCalc->params, i));
    ASSERT_NE(nullptr, pParam);
    EXPECT_EQ(STRIGGER_EVENT_WINDOW_NONE, pParam->notifyType);
    EXPECT_FALSE(pParam->wstart == 9000 && pParam->wend == 10000);
    if (pParam->wstart == 8000 && pParam->wend == 9000 && pParam->wrownum == 2) {
      ++completedCount;
    } else if (pParam->wstart == 9000 && pParam->wend == 9000 && pParam->wrownum == 1) {
      ++forcedCount;
      forcedParamIndex = i;
    } else {
      ADD_FAILURE() << "unexpected outer-close param: [" << pParam->wstart << ',' << pParam->wend
                    << "], wrownum=" << pParam->wrownum;
    }
  }
  EXPECT_EQ(1, completedCount);
  EXPECT_EQ(1, forcedCount);
  ASSERT_GE(forcedParamIndex, 0);

  ASSERT_NE(nullptr, pCalc->pContextPolicy);
  ASSERT_NE(nullptr, pCalc->pContextPolicy->pEntries);
  const SStreamContextPolicyEntry* pForcedPolicy = nullptr;
  for (int32_t i = 0; i < taosArrayGetSize(pCalc->pContextPolicy->pEntries); ++i) {
    const auto* pPolicy =
        static_cast<const SStreamContextPolicyEntry*>(taosArrayGet(pCalc->pContextPolicy->pEntries, i));
    if (pPolicy != nullptr && pPolicy->gid == RealtimePipelineHarness::kGid &&
        pPolicy->paramIndex == forcedParamIndex) {
      ASSERT_EQ(nullptr, pForcedPolicy);
      pForcedPolicy = pPolicy;
    }
  }
  ASSERT_NE(nullptr, pForcedPolicy);
  EXPECT_EQ(STREAM_CONTEXT_POLICY_ANCESTOR, pForcedPolicy->contextPolicy);

  PipelineAncestorObservation observation = {};
  ASSERT_TRUE(readAncestorObservation(pCalc, RealtimePipelineHarness::kGid, forcedParamIndex, &observation));
  EXPECT_EQ(RealtimePipelineHarness::kGid, observation.leafGid);
  EXPECT_EQ(WINDOW_TYPE_COUNT, observation.leafTriggerType);
  EXPECT_EQ(9000, observation.leafOpeningTs);
  EXPECT_EQ(0, observation.scope.layerIndex);
  EXPECT_EQ(WINDOW_TYPE_INTERVAL, observation.scope.triggerType);
  EXPECT_EQ(0, observation.scope.openingTs);
  EXPECT_EQ(0, observation.snapshot.layerIndex);
  EXPECT_EQ(WINDOW_TYPE_INTERVAL, observation.snapshot.triggerType);
  EXPECT_EQ(0, observation.snapshot.values.window.start);
  EXPECT_EQ(9999, observation.snapshot.values.window.end);
  EXPECT_EQ(9999, observation.snapshot.values.window.duration);
  EXPECT_EQ(2, observation.snapshot.values.window.rownum);
  EXPECT_EQ(TSDB_CODE_SUCCESS, tValidateSTriggerCalcRequestAncestorContext(pCalc, true));
  ASSERT_NE(nullptr, pCalc->pAncestorContext);
  EXPECT_EQ(0, taosArrayGetSize(pCalc->pAncestorContext->pReadScopeBindings));

  SStreamCacheScope          oldOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 0, 0}});
  SStreamCacheScope          newOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 10000, 0}});
  const std::vector<TSKEY>   oldValues = harness.readScopeTimestamps(oldOuter);
  const std::vector<TSKEY>   newValues = harness.readScopeTimestamps(newOuter);
  RealtimePipelineHarness::destroyScope(&oldOuter);
  RealtimePipelineHarness::destroyScope(&newOuter);
  EXPECT_EQ(std::vector<TSKEY>({8000, 9000}), oldValues);
  EXPECT_TRUE(newValues.empty());
}

TEST_F(StreamNestedRealtimeTest, CompletedCalcEvictsClosedAncestorScope) {
  RealtimePipelineHarness harness;
  harness.enableNestedTrowsCacheProjection();
  harness.retainCalcAttempts();
  ASSERT_TRUE(harness.init(RealtimePipelinePlan::NestedIntervalCount, false, STRIGGER_EVENT_WINDOW_CLOSE,
                           STRIGGER_EVENT_WINDOW_NONE));
  ASSERT_TRUE(harness.start());
  ASSERT_TRUE(harness.feedRows({8000, 9000, 10000}, {1, 2, 3}));
  ASSERT_TRUE(harness.respondCalcRows({8000, 9000, 10000}, {1, 2, 3}));
  ASSERT_EQ(1, harness.calcAttemptCount());

  SStreamCacheScope oldOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 0, 0}});
  SStreamCacheScope newOuter = RealtimePipelineHarness::makeScope({{0, WINDOW_TYPE_INTERVAL, 10000, 0}});
  EXPECT_EQ(std::vector<TSKEY>({8000, 9000}), harness.readScopeTimestamps(oldOuter));
  EXPECT_TRUE(harness.readScopeTimestamps(newOuter).empty());

  ASSERT_EQ(TSDB_CODE_SUCCESS, harness.dispatchCalcAttempt(0, TSDB_CODE_SUCCESS));
  harness.cleanupCalcAttemptTransport(0);
  EXPECT_TRUE(harness.readScopeTimestamps(oldOuter).empty());
  EXPECT_TRUE(harness.readScopeTimestamps(newOuter).empty());
  RealtimePipelineHarness::destroyScope(&oldOuter);
  RealtimePipelineHarness::destroyScope(&newOuter);
}

