  auto* savedProgress = *static_cast<SSTriggerExtProgress**>(taosArrayGet(saved.ownedProgress, 0));
  savedProgress->pUidWindow = tSimpleHashInit(1, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BIGINT));
