  SExtUidWindow window = {.skey = 100, .ekey = 200};
  int64_t uid = 9001;
  ASSERT_EQ(tSimpleHashPut(savedProgress->pUidWindow, &uid, sizeof(uid), &window, sizeof(window)), 0);

  void* checkpoint = nullptr;
