  snapshot = CopyRecalcSnapshot(task_.pRecalcTracker, 88);
  EXPECT_EQ(snapshot.status, STREAM_RECALC_STATUS_RUNNING);
  EXPECT_EQ(snapshot.progressPct, 50);
  EXPECT_NE(context_.progressStepId, 0U);
