SStreamAncestorContext* makePoolAncestorContext(int64_t gid) {
  auto* context = static_cast<SStreamAncestorContext*>(taosMemoryCalloc(1, sizeof(SStreamAncestorContext)));
  EXPECT_NE(context, nullptr);
  if (context == nullptr) return nullptr;
  context->pParamContexts = taosArrayInit(1, sizeof(SStreamAncestorParamContext));
  EXPECT_NE(context->pParamContexts, nullptr);
  if (context->pParamContexts == nullptr) return context;

  SStreamAncestorParamContext param = {};
  param.leafIdentity.gid = gid;
  param.leafIdentity.triggerType = WINDOW_TYPE_COUNT;
  param.leafIdentity.lineage.pScopes = taosArrayInit(1, sizeof(SScopeInstanceId));
  EXPECT_NE(param.leafIdentity.lineage.pScopes, nullptr);
  const SScopeInstanceId scope = {
      .layerIndex = 0, .triggerType = WINDOW_TYPE_INTERVAL, .openingTs = 100, .nativeDiscriminator = 1};
  EXPECT_NE(taosArrayPush(param.leafIdentity.lineage.pScopes, &scope), nullptr);
  param.pSnapshots = taosArrayInit(1, sizeof(SWindowAncestorSnapshot));
  EXPECT_NE(param.pSnapshots, nullptr);
  const SWindowAncestorSnapshot snapshot = {
      .layerIndex = 0, .triggerType = WINDOW_TYPE_INTERVAL, .values = {.sliding = {.currentTs = 100}}};
  EXPECT_NE(taosArrayPush(param.pSnapshots, &snapshot), nullptr);
  EXPECT_NE(taosArrayPush(context->pParamContexts, &param), nullptr);
  return context;
}

SStreamContextPolicy* makePoolContextPolicy(int64_t gid) {
  auto* policy = static_cast<SStreamContextPolicy*>(taosMemoryCalloc(1, sizeof(SStreamContextPolicy)));
  EXPECT_NE(policy, nullptr);
  if (policy == nullptr) return nullptr;
  policy->pEntries = taosArrayInit(1, sizeof(SStreamContextPolicyEntry));
  EXPECT_NE(policy->pEntries, nullptr);
  if (policy->pEntries == nullptr) return policy;
  const SStreamContextPolicyEntry entry = {
      .gid = gid, .paramIndex = 0, .contextPolicy = STREAM_CONTEXT_POLICY_ANCESTOR};
  EXPECT_NE(taosArrayPush(policy->pEntries, &entry), nullptr);
  return policy;
}

bool setPoolContextDiscriminator(SStreamAncestorContext* context, int64_t discriminator) {
  auto* param = static_cast<SStreamAncestorParamContext*>(
      taosArrayGet(context == nullptr ? nullptr : context->pParamContexts, 0));
  if (param == nullptr) return false;
  auto* scope = static_cast<SScopeInstanceId*>(taosArrayGet(param->leafIdentity.lineage.pScopes, 0));
  if (scope == nullptr) return false;
  scope->nativeDiscriminator = discriminator;
  return true;
}

bool appendPoolParamIdentity(SStreamAncestorContext* context, int64_t gid, int64_t discriminator, int32_t paramIndex) {
  if (context == nullptr || context->pParamContexts == nullptr) return false;
  SStreamAncestorParamContext param = {};
  param.paramIndex = paramIndex;
  param.leafIdentity.gid = gid;
  param.leafIdentity.triggerType = WINDOW_TYPE_COUNT;
  param.leafIdentity.lineage.pScopes = taosArrayInit(1, sizeof(SScopeInstanceId));
  if (param.leafIdentity.lineage.pScopes == nullptr) return false;
  const SScopeInstanceId scope = {
      .layerIndex = 0,
      .triggerType = WINDOW_TYPE_INTERVAL,
      .openingTs = 100,
      .nativeDiscriminator = discriminator,
  };
  if (taosArrayPush(param.leafIdentity.lineage.pScopes, &scope) == nullptr ||
      taosArrayPush(context->pParamContexts, &param) == nullptr) {
    taosArrayDestroy(param.leafIdentity.lineage.pScopes);
    return false;
  }
  return true;
}

bool appendPoolReadScopeBinding(SStreamAncestorContext* context, int64_t gid, int64_t discriminator,
                                int32_t readInfoIndex) {
  auto* param = static_cast<SStreamAncestorParamContext*>(
      taosArrayGet(context == nullptr ? nullptr : context->pParamContexts, 0));
  if (param == nullptr) return false;
  if (context->pReadScopeBindings == nullptr) {
    context->pReadScopeBindings = taosArrayInit(2, sizeof(SStreamReadScopeBinding));
    if (context->pReadScopeBindings == nullptr) return false;
  }

  SStreamReadScopeBinding binding = {.vgId = 7, .readInfoIndex = readInfoIndex, .scope = {.gid = gid}};
  binding.scope.lineage.pScopes = taosArrayDup(param->leafIdentity.lineage.pScopes, nullptr);
  if (binding.scope.lineage.pScopes == nullptr) return false;
  auto* scope = static_cast<SScopeInstanceId*>(taosArrayGet(binding.scope.lineage.pScopes, 0));
  if (scope == nullptr) {
    taosArrayDestroy(binding.scope.lineage.pScopes);
    return false;
  }
  scope->nativeDiscriminator = discriminator;
  if (taosArrayPush(context->pReadScopeBindings, &binding) == nullptr) {
    taosArrayDestroy(binding.scope.lineage.pScopes);
    return false;
  }
  return true;
}

SStreamAncestorContext* makePoolProjectedContext(int64_t gid, int64_t discriminator) {
  SStreamAncestorContext* context = makePoolAncestorContext(gid);
  EXPECT_TRUE(setPoolContextDiscriminator(context, discriminator));
  EXPECT_TRUE(appendPoolReadScopeBinding(context, gid, discriminator, 0));
  return context;
}

SSDataBlock* makePoolCacheBlock() {
  SSDataBlock* block = nullptr;
  if (createDataBlock(&block) != TSDB_CODE_SUCCESS) return nullptr;
  SColumnInfoData tsInfo = createColumnInfoData(TSDB_DATA_TYPE_TIMESTAMP, sizeof(TSKEY), 1);
  SColumnInfoData valueInfo = createColumnInfoData(TSDB_DATA_TYPE_INT, sizeof(int32_t), 2);
  if (blockDataAppendColInfo(block, &tsInfo) != TSDB_CODE_SUCCESS ||
      blockDataAppendColInfo(block, &valueInfo) != TSDB_CODE_SUCCESS ||
      blockDataEnsureCapacity(block, 2) != TSDB_CODE_SUCCESS) {
    blockDataDestroy(block);
    return nullptr;
  }
  auto*         tsCol = static_cast<SColumnInfoData*>(taosArrayGet(block->pDataBlock, 0));
  auto*         valueCol = static_cast<SColumnInfoData*>(taosArrayGet(block->pDataBlock, 1));
  const TSKEY   timestamps[] = {100, 101};
  const int32_t values[] = {10, 20};
  for (int32_t row = 0; row < 2; ++row) {
    if (colDataSetVal(tsCol, row, reinterpret_cast<const char*>(&timestamps[row]), false) != TSDB_CODE_SUCCESS ||
        colDataSetVal(valueCol, row, reinterpret_cast<const char*>(&values[row]), false) != TSDB_CODE_SUCCESS) {
      blockDataDestroy(block);
      return nullptr;
    }
  }
  block->info.rows = 2;
  return block;
}

class CalcPoolHarness {
 public:
  bool init(int32_t slotCount = 2) {
    task_.task.streamId = 0x700;
    task_.task.taskId = 0x701;
    task_.triggerType = STREAM_TRIGGER_COUNT;
    task_.lowLatencyCalc = true;
    taosInitRWLatch(&task_.calcPoolLock);

    task_.runnerList = taosArrayInit_s(sizeof(SStreamRunnerTarget), 1);
    if (task_.runnerList == nullptr) return false;
    auto* runner = static_cast<SStreamRunnerTarget*>(taosArrayGet(task_.runnerList, 0));
    runner->addr.taskId = 0x702;
    runner->execReplica = slotCount;

    task_.pCalcNodes = taosArrayInit_s(sizeof(SSTriggerCalcNode), 1);
    if (task_.pCalcNodes == nullptr) return false;
    auto* node = static_cast<SSTriggerCalcNode*>(taosArrayGet(task_.pCalcNodes, 0));
    node->pSlots = taosArrayInit_s(sizeof(SSTriggerCalcSlot), slotCount);
    if (node->pSlots == nullptr) return false;
    for (int32_t i = 0; i < slotCount; ++i) {
      auto* slot = static_cast<SSTriggerCalcSlot*>(taosArrayGet(node->pSlots, i));
      TD_DLIST_APPEND(&node->idleSlots, slot);
    }

    task_.pGroupRunning = tSimpleHashInit(4, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BINARY));
    task_.pSessionRunning = tSimpleHashInit(4, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BIGINT));
    if (task_.pGroupRunning == nullptr || task_.pSessionRunning == nullptr) return false;

    realtime_.pTask = &task_;
    realtime_.sessionId = kRealtimeSessionId;
    realtime_.status = STRIGGER_CONTEXT_IDLE;
    task_.pRealtimeContext = &realtime_;
    return true;
  }

  bool enableCacheRead() {
    if (gStreamMgmt.taskMap != nullptr || initStreamDataSink() != TSDB_CODE_SUCCESS) return false;
    dataSinkOwned_ = true;
    if (stCreateCalcDataCacheIterMap(&realtime_.pCalcDataCacheIters) != TSDB_CODE_SUCCESS) return false;

    task_.task.type = STREAM_TRIGGER_TASK;
    task_.task.nodeId = 7;
    task_.addOptions = STREAM_OPTION_NESTED_WINDOW_PLAN;
    taosInitRWLatch(&task_.task.entryLock);
    gStreamMgmt.taskMap = taosHashInit(1, taosGetDefaultHashFunction(TSDB_DATA_TYPE_BINARY), false, HASH_ENTRY_LOCK);
    if (gStreamMgmt.taskMap == nullptr) return false;
    taskMapOwned_ = true;
    SStreamTask* task = reinterpret_cast<SStreamTask*>(&task_);
    if (taosHashPut(gStreamMgmt.taskMap, &task_.task.streamId, sizeof(task_.task.streamId) + sizeof(task_.task.taskId),
                    &task, POINTER_BYTES) != TSDB_CODE_SUCCESS) {
      return false;
    }
    taskRegistered_ = true;
    return initStreamDataCache(task_.task.streamId, task_.task.taskId, realtime_.sessionId, DATA_CLEAN_IMMEDIATE, 0,
                               &cache_) == TSDB_CODE_SUCCESS;
  }

  ~CalcPoolHarness() {
    if (taskRegistered_) {
      EXPECT_EQ(taosHashRemove(gStreamMgmt.taskMap, &task_.task.streamId,
                               sizeof(task_.task.streamId) + sizeof(task_.task.taskId)),
                TSDB_CODE_SUCCESS);
    }
    if (taskMapOwned_) {
      taosHashCleanup(gStreamMgmt.taskMap);
      gStreamMgmt.taskMap = nullptr;
    }
    taosHashCleanup(realtime_.pCalcDataCacheIters);
    realtime_.pCalcDataCacheIters = nullptr;
    if (dataSinkOwned_) destroyDataSinkMgr();
    if (task_.pCalcNodes != nullptr) {
      auto* node = static_cast<SSTriggerCalcNode*>(taosArrayGet(task_.pCalcNodes, 0));
      if (node != nullptr && node->pSlots != nullptr) {
        for (int32_t i = 0; i < taosArrayGetSize(node->pSlots); ++i) {
          auto* slot = static_cast<SSTriggerCalcSlot*>(taosArrayGet(node->pSlots, i));
          tDestroySTriggerCalcRequest(&slot->req);
        }
        taosArrayDestroy(node->pSlots);
      }
      taosArrayDestroy(task_.pCalcNodes);
    }
    tSimpleHashCleanup(task_.pGroupRunning);
    tSimpleHashCleanup(task_.pSessionRunning);
    taosArrayDestroy(task_.runnerList);
  }

  void attachContext(SSTriggerCalcRequest* request) {
    SSTriggerCalcParam param = {.wstart = 100, .wend = 199, .notifyType = STRIGGER_EVENT_WINDOW_CLOSE};
    ASSERT_NE(taosArrayPush(request->params, &param), nullptr);
    request->pContextPolicy = makePoolContextPolicy(request->gid);
    ASSERT_NE(request->pContextPolicy, nullptr);
    request->pAncestorContext = makePoolAncestorContext(request->gid);
    ASSERT_NE(request->pAncestorContext, nullptr);
  }

  int32_t readCacheIterator(int64_t gid, int64_t sessionId, SStreamContextPolicy* policy,
                            SStreamAncestorContext* context, int32_t* value, bool* finished, bool multiGroup = false) {
    if (value == nullptr || finished == nullptr) return TSDB_CODE_INVALID_PARA;
    SStreamRuntimeFuncInfo runtime = {};
    runtime.groupId = gid;
    runtime.curIdx = 0;
    runtime.sessionId = sessionId;
    runtime.curNodeId = task_.task.nodeId;
    runtime.isMultiGroupCalc = multiGroup;
    runtime.pContextPolicy = policy;
    runtime.pAncestorContext = context;
    SStreamCacheReadInfo readInfo = {};
    readInfo.taskInfo.streamId = task_.task.streamId;
    readInfo.taskInfo.taskId = task_.task.taskId;
    readInfo.taskInfo.sessionId = sessionId;
    readInfo.gid = gid;
    readInfo.start = 100;
    readInfo.end = 101;
    readInfo.pRuntime = &runtime;
    int32_t code = stRunnerFetchDataFromCache(&readInfo, finished);
    if (code == TSDB_CODE_SUCCESS && readInfo.pBlock != nullptr) {
      const auto* values = static_cast<const SColumnInfoData*>(taosArrayGet(readInfo.pBlock->pDataBlock, 1));
      if (values == nullptr) {
        code = TSDB_CODE_INVALID_PARA;
      } else {
        *value = *reinterpret_cast<const int32_t*>(colDataGetData(values, 0));
      }
    }
    blockDataDestroy(readInfo.pBlock);
    stClearStreamCacheReadScope(&readInfo);
    return code;
  }

  int32_t populateCacheIterator(int64_t gid, int64_t sessionId, SStreamContextPolicy* policy,
                                SStreamAncestorContext* context, bool multiGroup = false) {
    const auto* param = static_cast<const SStreamAncestorParamContext*>(taosArrayGet(context->pParamContexts, 0));
    if (param == nullptr) return TSDB_CODE_INVALID_PARA;
    SStreamCacheScope scope = {.gid = param->leafIdentity.gid, .lineage = param->leafIdentity.lineage};
    SSDataBlock*      source = makePoolCacheBlock();
    if (source == nullptr) return terrno;
    source->info.id.blockId = 1;
    int32_t code = putStreamDataCacheScoped(cache_, &scope, 100, 100, source, 0, 0);
    if (code == TSDB_CODE_SUCCESS) {
      source->info.id.blockId = 2;
      code = putStreamDataCacheScoped(cache_, &scope, 101, 101, source, 1, 1);
    }
    blockDataDestroy(source);
    if (code != TSDB_CODE_SUCCESS) return code;
    int32_t value = 0;
    bool    finished = false;
    code = readCacheIterator(gid, sessionId, policy, context, &value, &finished, multiGroup);
    if (code != TSDB_CODE_SUCCESS) return code;
    return !finished && value == 10 ? TSDB_CODE_SUCCESS : TSDB_CODE_INTERNAL_ERROR;
  }

  int32_t cacheIteratorCount() const { return taosHashGetSize(realtime_.pCalcDataCacheIters); }

  int32_t processResponse(SSTriggerCalcRequest* request, int32_t responseCode, uint64_t generation = 0) {
    SSTriggerAHandle responseAhandle = {};
    responseAhandle.sessionId = request->sessionId;
    responseAhandle.param = request;
    SMsgSendInfo responseSendInfo = {};
    responseSendInfo.param = &responseAhandle;
    responseSendInfo.requestObjRefId =
        generation == 0 ? reinterpret_cast<SSTriggerCalcSlot*>(request)->generation : generation;
    SRpcMsg response = {};
    response.msgType = TDMT_STREAM_TRIGGER_CALC_RSP;
    response.code = responseCode;
    response.info.ahandle = &responseSendInfo;
    int64_t errorTaskId = 0;
    return stTriggerTaskProcessRsp(&task_.task, &response, &errorTaskId);
  }

  SStreamTriggerTask task_ = {};

 private:
  SSTriggerRealtimeContext realtime_ = {};
  void*                    cache_ = nullptr;
  bool                     dataSinkOwned_ = false;
  bool                     taskMapOwned_ = false;
  bool                     taskRegistered_ = false;
};

TEST_F(StreamTriggerTaskTest, SameGroupReleaseKeepsDropBlockedUntilLastRequest) {
  CalcPoolHarness harness;
  ASSERT_TRUE(harness.init(3));

  SSTriggerCalcRequest* first = nullptr;
  SSTriggerCalcRequest* second = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &first));
  ASSERT_NE(nullptr, first);
  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskAcquireRequest(&harness.task_, kRealtimeSessionId, 101, &second));
  ASSERT_NE(nullptr, second);

  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskReleaseRequest(&harness.task_, &second, false));
  SSTriggerDropRequest* dropRequest = nullptr;
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAcquireDropTableRequest(&harness.task_, kRealtimeSessionId, 101, &dropRequest));
  EXPECT_EQ(nullptr, dropRequest);
  destroyPoolDropRequest(&dropRequest);

  ASSERT_EQ(TSDB_CODE_SUCCESS, stTriggerTaskReleaseRequest(&harness.task_, &first, true));
  ASSERT_EQ(TSDB_CODE_SUCCESS,
            stTriggerTaskAcquireDropTableRequest(&harness.task_, kRealtimeSessionId, 101, &dropRequest));
  ASSERT_NE(nullptr, dropRequest);
  destroyPoolDropRequest(&dropRequest);
}

